window.__HW_BACKGROUND__ = {"2-1":{"skills":[{"name":{"en":"Count tally marks","es":"Contar marcas de conteo"},"why":{"en":"Tonight you collect answers to a question as data, and tally marks are a quick way to count them.","es":"Hoy reúnes respuestas a una pregunta como datos, y las marcas de conteo te ayudan a contarlas."},"steps":[{"en":"Each mark stands for 1.","es":"Cada marca vale 1."},{"en":"A slash across four marks makes a group of 5.","es":"Una raya que cruza cuatro marcas forma un grupo de 5."},{"en":"Count the groups by 5s, then add the extra marks.","es":"Cuenta los grupos de 5 en 5 y luego suma las marcas sueltas."}],"example":{"en":"Two groups of 5 and 3 more marks: 5 + 5 + 3 = 13.","es":"Dos grupos de 5 y 3 marcas más: 5 + 5 + 3 = 13."},"model":{"kind":"grid","data":{"rows":3,"cols":5,"filled":13,"groupSize":5,"label":"5 + 5 + 3 = 13"},"alt":{"en":"Dots in rows of 5: two full rows of 5 and 3 more, 13 in all.","es":"Puntos en filas de 5: dos filas completas de 5 y 3 más, 13 en total."}},"check":{"q":{"en":"A tally shows 3 groups of 5 and 2 more marks. How many is that?","es":"Un conteo muestra 3 grupos de 5 y 2 marcas más. ¿Cuántos son?"},"options":["5","17","32"],"correctIdx":1,"calc":{"expr":"3 × 5 + 2","value":"17"},"feedback":[{"en":"That counts each group as 1. Each group is worth 5: 5 + 5 + 5 + 2.","es":"Así cuentas cada grupo como 1. Cada grupo vale 5: 5 + 5 + 5 + 2."},{"en":"Yes. 5 + 5 + 5 = 15, and 15 + 2 = 17.","es":"Sí. 5 + 5 + 5 = 15, y 15 + 2 = 17."},{"en":"32 puts the digits side by side. Count 5, 10, 15, then add 2.","es":"32 pone los dígitos lado a lado. Cuenta 5, 10, 15 y luego suma 2."}]}},{"name":{"en":"Compare two bars on a bar graph","es":"Comparar dos barras en una gráfica de barras"},"why":{"en":"Answers to a statistical question are often shown in a bar graph, so you read and compare bars.","es":"Las respuestas a una pregunta estadística muchas veces se muestran en una gráfica de barras que debes leer."},"steps":[{"en":"Read where the top of each bar lines up on the scale.","es":"Mira con qué número de la escala se alinea la parte de arriba de cada barra."},{"en":"To find how many more, subtract the smaller count from the bigger one.","es":"Para saber cuántos más, resta la cantidad menor de la mayor."}],"example":{"en":"The dogs bar reaches 9 and the cats bar reaches 5: 9 − 5 = 4 more chose dogs.","es":"La barra de perros llega a 9 y la de gatos a 5: 9 − 5 = 4 más eligieron perros."},"model":{"kind":"barplot","data":{"categories":[{"label":{"en":"Dogs","es":"Perros"},"value":9},{"label":{"en":"Cats","es":"Gatos"},"value":5}]},"alt":{"en":"A bar graph: the dogs bar reaches 9 and the cats bar reaches 5.","es":"Una gráfica de barras: la barra de perros llega a 9 y la de gatos a 5."}},"check":{"q":{"en":"The soccer bar reaches 12. The baseball bar reaches 7. How many more chose soccer?","es":"La barra de fútbol llega a 12. La de béisbol llega a 7. ¿Cuántos más eligieron fútbol?"},"options":["19","7","5"],"correctIdx":2,"calc":{"expr":"12 − 7","value":"5"},"feedback":[{"en":"19 adds the bars. How many more means subtract: 12 − 7.","es":"19 suma las barras. Cuántos más significa restar: 12 − 7."},{"en":"7 is just the baseball bar. Subtract it from the soccer bar.","es":"7 es solo la barra de béisbol. Réstala de la barra de fútbol."},{"en":"Yes. 12 − 7 = 5 more chose soccer.","es":"Sí. 12 − 7 = 5, así que 5 más eligieron fútbol."}]}}]},"2-10":{"skills":[{"name":{"en":"Find the mean of a data set","es":"Hallar la media de un conjunto de datos"},"why":{"en":"Tonight you compare the mean and the median to choose which one describes the data fairly.","es":"Hoy comparas la media y la mediana para elegir cuál describe los datos de manera justa."},"steps":[{"en":"Add all the values.","es":"Suma todos los valores."},{"en":"Divide the total by how many values there are.","es":"Divide el total entre la cantidad de valores."}],"example":{"en":"3, 4, 5: the total is 12, and 12 ÷ 3 = 4.","es":"3, 4, 5: el total es 12, y 12 ÷ 3 = 4."},"model":{"kind":"balance","data":{"left":["3","4","5"],"right":["4","4","4"]},"alt":{"en":"A level balance: 3, 4, and 5 on one side equal three 4s on the other, so the mean is 4.","es":"Una balanza nivelada: 3, 4 y 5 de un lado pesan lo mismo que tres 4 del otro; la media es 4."}},"check":{"q":{"en":"Find the mean of 2, 3, 4, and 15.","es":"Halla la media de 2, 3, 4 y 15."},"options":["24","8","6"],"correctIdx":2,"calc":{"expr":"(2 + 3 + 4 + 15) ÷ 4","value":"6"},"feedback":[{"en":"24 is the total. Divide it by 4, the number of values.","es":"24 es el total. Divídelo entre 4, la cantidad de valores."},{"en":"8 divides by 3. Count again: there are 4 values.","es":"8 divide entre 3. Cuenta otra vez: hay 4 valores."},{"en":"Yes. 24 ÷ 4 = 6. The 15 pulls the mean up.","es":"Sí. 24 ÷ 4 = 6. El 15 hace subir la media."}]}},{"name":{"en":"Find the median of a data set","es":"Hallar la mediana de un conjunto de datos"},"why":{"en":"The median is the other center you compare, and one far-off value barely moves it.","es":"La mediana es el otro centro que comparas, y un valor muy lejano casi no la cambia."},"steps":[{"en":"Put the values in order.","es":"Ordena los valores."},{"en":"Take the middle value.","es":"Toma el valor del medio."},{"en":"If two values share the middle, add them and divide by 2.","es":"Si dos valores están en el medio, súmalos y divide entre 2."}],"example":{"en":"5, 10, 15, 26, 30: the middle value is 15.","es":"5, 10, 15, 26, 30: el valor del medio es 15."},"model":{"kind":"numberline","data":{"min":0,"max":30,"step":1,"points":[{"value":5,"kind":"given","label":"5"},{"value":10,"kind":"given","label":"10"},{"value":15,"kind":"answer","label":{"en":"median 15","es":"mediana 15"}},{"value":26,"kind":"given","label":"26"},{"value":30,"kind":"given","label":"30"}]},"alt":{"en":"The values 5, 10, 15, 26, and 30 on a number line, with the middle value 15 marked.","es":"Los valores 5, 10, 15, 26 y 30 en una recta numérica, con el valor del medio, 15, marcado."}},"check":{"q":{"en":"Find the median of 15, 2, 4, and 3.","es":"Halla la mediana de 15, 2, 4 y 3."},"options":["4","3.5","6"],"correctIdx":1,"calc":{"expr":"(3 + 4) ÷ 2","value":"3.5"},"feedback":[{"en":"4 is one of the two middle values. Use the number halfway between 3 and 4.","es":"4 es uno de los dos valores del medio. Usa el número a la mitad entre 3 y 4."},{"en":"Yes. In order: 2, 3, 4, 15. Halfway between 3 and 4 is 3.5.","es":"Sí. En orden: 2, 3, 4, 15. A la mitad entre 3 y 4 está 3.5."},{"en":"6 is the mean. For the median, order the values and take the middle.","es":"6 es la media. Para la mediana, ordena los valores y toma el del medio."}]}}]},"2-11":{"skills":[{"name":{"en":"Know tenths and hundredths","es":"Conocer las décimas y las centésimas"},"why":{"en":"Lining up decimal points keeps tenths with tenths and hundredths with hundredths when you add or subtract.","es":"Alinear los puntos decimales mantiene décimas con décimas y centésimas con centésimas al sumar o restar."},"steps":[{"en":"The first digit after the point is tenths.","es":"El primer dígito después del punto son las décimas."},{"en":"The next digit to the right is hundredths.","es":"El dígito que sigue a la derecha son las centésimas."},{"en":"A zero at the end does not change the value: 0.5 = 0.50.","es":"Un cero al final no cambia el valor: 0.5 = 0.50."}],"example":{"en":"In 4.37, the 3 is 3 tenths and the 7 is 7 hundredths.","es":"En 4.37, el 3 son 3 décimas y el 7 son 7 centésimas."},"model":{"kind":"grid","data":{"rows":10,"cols":10,"filled":37,"groupSize":10,"label":{"en":"0.37: 3 tenths, 7 hundredths","es":"0.37: 3 décimas, 7 centésimas"}},"alt":{"en":"A hundred grid showing the .37 in 4.37: 3 full rows of tenths and 7 more hundredths.","es":"Una cuadrícula de cien que muestra el .37 de 4.37: 3 filas de décimas y 7 centésimas más."}},"check":{"q":{"en":"Which number has the same value as 2.6?","es":"¿Qué número tiene el mismo valor que 2.6?"},"options":["2.06","2.60","26"],"correctIdx":1,"calc":{"expr":"2.6","value":"2.6"},"feedback":[{"en":"2.06 moves the 6 to the hundredths place. In 2.6, the 6 is tenths.","es":"2.06 mueve el 6 a las centésimas. En 2.6, el 6 son décimas."},{"en":"Yes. A zero at the end does not change the value.","es":"Sí. Un cero al final no cambia el valor."},{"en":"26 drops the decimal point. 2.6 is between 2 and 3.","es":"26 quita el punto decimal. 2.6 está entre 2 y 3."}]}},{"name":{"en":"Subtract with regrouping","es":"Restar reagrupando"},"why":{"en":"Subtracting decimals works like whole numbers, so you often regroup from the next place.","es":"Restar decimales funciona como con números enteros, así que muchas veces reagrupas del lugar siguiente."},"steps":[{"en":"Start at the right.","es":"Empieza por la derecha."},{"en":"If the top digit is smaller, take 1 from the place to its left.","es":"Si el dígito de arriba es menor, toma 1 del lugar a su izquierda."},{"en":"That 1 becomes 10 in this place. Then subtract.","es":"Ese 1 se vuelve 10 en este lugar. Luego resta."}],"example":{"en":"52 − 17: 2 is less than 7, so regroup. 12 − 7 = 5 and 4 − 1 = 3. Answer: 35.","es":"52 − 17: 2 es menor que 7, así que reagrupa. 12 − 7 = 5 y 4 − 1 = 3. Resultado: 35."},"model":{"kind":"numberline","data":{"min":0,"max":60,"step":5,"points":[{"value":17,"kind":"given","label":"17"},{"value":52,"kind":"given","label":"52"}]},"alt":{"en":"A number line with points at 17 and 52; the gap between them is 52 − 17.","es":"Una recta numérica con puntos en 17 y 52; el espacio entre ellos es 52 − 17."}},"check":{"q":{"en":"What is 6.3 − 2.8?","es":"¿Cuánto es 6.3 − 2.8?"},"options":["4.5","9.1","3.5"],"correctIdx":2,"calc":{"expr":"6.3 − 2.8","value":"3.5"},"feedback":[{"en":"4.5 does 8 − 3 in the tenths. Regroup instead: 13 − 8 = 5, then 5 − 2 = 3.","es":"4.5 hace 8 − 3 en las décimas. Mejor reagrupa: 13 − 8 = 5, luego 5 − 2 = 3."},{"en":"9.1 adds the numbers. This problem subtracts.","es":"9.1 suma los números. Este problema es una resta."},{"en":"Yes. 13 tenths − 8 tenths = 5 tenths, and 5 − 2 = 3.","es":"Sí. 13 décimas − 8 décimas = 5 décimas, y 5 − 2 = 3."}]}}]},"2-12":{"skills":[{"name":{"en":"Multiply two-digit whole numbers","es":"Multiplicar números enteros de dos dígitos"},"why":{"en":"Tonight you multiply decimals as if there were no decimal points, then place the point.","es":"Hoy multiplicas decimales como si no hubiera puntos decimales y luego colocas el punto."},"steps":[{"en":"Multiply by the ones digit.","es":"Multiplica por el dígito de las unidades."},{"en":"Multiply by the tens digit. Write a 0 in the ones place first.","es":"Multiplica por el dígito de las decenas. Primero escribe un 0 en las unidades."},{"en":"Add the two rows.","es":"Suma las dos filas."}],"example":{"en":"12 × 26: 12 × 6 = 72 and 12 × 20 = 240. Then 72 + 240 = 312.","es":"12 × 26: 12 × 6 = 72 y 12 × 20 = 240. Luego 72 + 240 = 312."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":26,"height":12,"split":[20,6]}},"alt":{"en":"A 12 by 26 rectangle split into a 12 by 20 part and a 12 by 6 part.","es":"Un rectángulo de 12 por 26 dividido en una parte de 12 por 20 y otra de 12 por 6."}},"check":{"q":{"en":"What is 23 × 14?","es":"¿Cuánto es 23 × 14?"},"options":["322","115","92"],"correctIdx":0,"calc":{"expr":"23 × 14","value":"322"},"feedback":[{"en":"Yes. 23 × 4 = 92 and 23 × 10 = 230. 92 + 230 = 322.","es":"Sí. 23 × 4 = 92 y 23 × 10 = 230. 92 + 230 = 322."},{"en":"115 forgets the 0 in the tens row. 23 × 10 is 230, not 23.","es":"115 olvida el 0 en la fila de las decenas. 23 × 10 es 230, no 23."},{"en":"92 is only 23 × 4. Also multiply by the 1 ten, then add.","es":"92 es solo 23 × 4. Multiplica también por la decena y luego suma."}]}},{"name":{"en":"Estimate a product by rounding","es":"Estimar un producto redondeando"},"why":{"en":"A quick estimate tells you if the decimal point in tonight's product is in a sensible place.","es":"Una estimación rápida te dice si el punto decimal del producto de hoy está en un lugar lógico."},"steps":[{"en":"Round each factor to the nearest whole number.","es":"Redondea cada factor al número entero más cercano."},{"en":"Multiply the rounded numbers.","es":"Multiplica los números redondeados."},{"en":"Your exact answer should be close to the estimate.","es":"Tu respuesta exacta debe quedar cerca de la estimación."}],"example":{"en":"3.4 × 2.6 is about 3 × 3 = 9, so 8.84 makes sense and 88.4 does not.","es":"3.4 × 2.6 es más o menos 3 × 3 = 9, así que 8.84 tiene sentido y 88.4 no."},"model":{"kind":"numberline","data":{"min":0,"max":12,"step":1,"points":[{"value":8.84,"kind":"given","label":"8.84"},{"value":9,"kind":"answer","label":{"en":"about 9","es":"cerca de 9"}}]},"alt":{"en":"A number line where 8.84 sits right next to the estimate 9.","es":"Una recta numérica donde 8.84 queda justo al lado de la estimación 9."}},"check":{"q":{"en":"Estimate 4.8 × 3.1 by rounding each factor to a whole number.","es":"Estima 4.8 × 3.1 redondeando cada factor a un número entero."},"options":["12","15","20"],"correctIdx":1,"calc":{"expr":"5 × 3","value":"15"},"feedback":[{"en":"12 rounds 4.8 down to 4. 4.8 is closer to 5.","es":"12 redondea 4.8 hacia abajo a 4. 4.8 está más cerca de 5."},{"en":"Yes. 4.8 rounds to 5 and 3.1 rounds to 3: 5 × 3 = 15.","es":"Sí. 4.8 se redondea a 5 y 3.1 a 3: 5 × 3 = 15."},{"en":"20 rounds 3.1 up to 4. 3.1 is closer to 3.","es":"20 redondea 3.1 hacia arriba a 4. 3.1 está más cerca de 3."}]}}]},"2-2":{"skills":[{"name":{"en":"Place a value in the right interval","es":"Ubicar un valor en el intervalo correcto"},"why":{"en":"Tonight each data value goes into an interval, like 10–19, before you draw the histogram bars.","es":"Hoy cada valor de los datos va en un intervalo, como 10–19, antes de dibujar las barras del histograma."},"steps":[{"en":"Read the first and last number of each interval.","es":"Lee el primer y el último número de cada intervalo."},{"en":"A value belongs where it is between those two numbers, or equal to one of them.","es":"Un valor va donde queda entre esos dos números, o es igual a uno de ellos."}],"example":{"en":"14 goes in 10–19, because 14 is between 10 and 19. 20 starts the next interval, 20–29.","es":"14 va en 10–19, porque 14 está entre 10 y 19. El 20 empieza el siguiente intervalo, 20–29."},"model":{"kind":"numberline","data":{"min":0,"max":30,"step":1,"points":[{"value":10,"kind":"given","label":"10"},{"value":14,"kind":"answer","label":"14"},{"value":19,"kind":"given","label":"19"},{"value":20,"kind":"error","label":"20"}]},"alt":{"en":"A number line with 14 marked between 10 and 19; 20 is crossed out because it starts the next interval.","es":"Una recta numérica con 14 marcado entre 10 y 19; el 20 está tachado porque empieza el siguiente intervalo."}},"check":{"q":{"en":"How many of these values go in the 10–19 interval: 8, 12, 19, 20, 15?","es":"¿Cuántos de estos valores van en el intervalo 10–19: 8, 12, 19, 20, 15?"},"options":["3","4","2"],"correctIdx":0,"calc":{"expr":"1 + 1 + 1","value":"3"},"feedback":[{"en":"Yes. 12, 19, and 15 are in 10–19.","es":"Sí. 12, 19 y 15 están en 10–19."},{"en":"That counts 20 too. 20 is past 19, so it starts the next interval.","es":"Así cuentas también el 20. El 20 pasa del 19, así que va en el siguiente intervalo."},{"en":"19 was left out. The last number of the interval counts too.","es":"Faltó el 19. El último número del intervalo también cuenta."}]}},{"name":{"en":"Add the bar heights for the total","es":"Sumar las alturas de las barras para el total"},"why":{"en":"Adding all the bar heights tells how many data values the histogram shows in all.","es":"Sumar las alturas de todas las barras te dice cuántos valores muestra el histograma en total."},"steps":[{"en":"Read the height of each bar on the scale.","es":"Lee la altura de cada barra en la escala."},{"en":"Add all the heights. Check that you used every bar.","es":"Suma todas las alturas. Revisa que usaste todas las barras."}],"example":{"en":"Bars of 3, 5, and 2: 3 + 5 + 2 = 10 values in all.","es":"Barras de 3, 5 y 2: 3 + 5 + 2 = 10 valores en total."},"model":{"kind":"barplot","data":{"categories":[{"label":"0–9","value":3},{"label":"10–19","value":5},{"label":"20–29","value":2}]},"alt":{"en":"Three histogram bars with heights 3, 5, and 2.","es":"Tres barras de histograma con alturas de 3, 5 y 2."}},"check":{"q":{"en":"A histogram has bars of 4, 7, 6, and 3. How many values does it show?","es":"Un histograma tiene barras de 4, 7, 6 y 3. ¿Cuántos valores muestra?"},"options":["7","17","20"],"correctIdx":2,"calc":{"expr":"4 + 7 + 6 + 3","value":"20"},"feedback":[{"en":"7 is only the tallest bar. Add the heights of all four bars.","es":"7 es solo la barra más alta. Suma las alturas de las cuatro barras."},{"en":"17 leaves out the last bar. Add the 3 too.","es":"17 deja fuera la última barra. Suma también el 3."},{"en":"Yes. 4 + 7 + 6 + 3 = 20 values.","es":"Sí. 4 + 7 + 6 + 3 = 20 valores."}]}}]},"2-3":{"skills":[{"name":{"en":"Put numbers in order, least to greatest","es":"Ordenar números de menor a mayor"},"why":{"en":"The median is the middle number, but only after the data are in order.","es":"La mediana es el número del medio, pero solo después de ordenar los datos."},"steps":[{"en":"Find the least number and write it first.","es":"Busca el número menor y escríbelo primero."},{"en":"Keep picking the next smallest until you use every number.","es":"Sigue eligiendo el siguiente más pequeño hasta usar todos los números."},{"en":"Count: your list should have as many numbers as before.","es":"Cuenta: tu lista debe tener la misma cantidad de números que antes."}],"example":{"en":"9, 3, 7, 5 in order is 3, 5, 7, 9.","es":"9, 3, 7, 5 ordenados quedan 3, 5, 7, 9."},"model":{"kind":"numberline","data":{"min":0,"max":10,"step":1,"points":[{"value":3,"kind":"given","label":"3"},{"value":5,"kind":"given","label":"5"},{"value":7,"kind":"given","label":"7"},{"value":9,"kind":"given","label":"9"}]},"alt":{"en":"The numbers 3, 5, 7, and 9 sit on a number line from least to greatest.","es":"Los números 3, 5, 7 y 9 están en una recta numérica de menor a mayor."}},"check":{"q":{"en":"Order 12, 7, 15, 9 from least to greatest. Which number is 2nd?","es":"Ordena 12, 7, 15, 9 de menor a mayor. ¿Qué número queda en el 2.º lugar?"},"options":["7","9","12"],"correctIdx":1,"calc":{"expr":"9","value":"9"},"feedback":[{"en":"7 is 2nd in the list as given. Order it first: 7, 9, 12, 15.","es":"7 es el 2.º en la lista sin ordenar. Primero ordénala: 7, 9, 12, 15."},{"en":"Yes. In order the list is 7, 9, 12, 15, so 9 is 2nd.","es":"Sí. Ordenada, la lista es 7, 9, 12, 15, así que 9 es el 2.º."},{"en":"That orders greatest to least. Start with the least number, 7.","es":"Así ordenas de mayor a menor. Empieza con el número menor, 7."}]}},{"name":{"en":"Find the number halfway between two numbers","es":"Hallar el número a la mitad entre dos números"},"why":{"en":"With an even count, the median is halfway between the two middle numbers.","es":"Si hay una cantidad par de datos, la mediana está a la mitad entre los dos números del medio."},"steps":[{"en":"Add the two numbers.","es":"Suma los dos números."},{"en":"Divide the sum by 2.","es":"Divide la suma entre 2."}],"example":{"en":"Halfway between 4 and 6: 4 + 6 = 10, then 10 ÷ 2 = 5.","es":"A la mitad entre 4 y 6: 4 + 6 = 10, luego 10 ÷ 2 = 5."},"model":{"kind":"numberline","data":{"min":0,"max":10,"step":1,"points":[{"value":4,"kind":"given","label":"4"},{"value":5,"kind":"answer","label":"5"},{"value":6,"kind":"given","label":"6"}]},"alt":{"en":"A number line where 5 sits exactly halfway between 4 and 6.","es":"Una recta numérica donde el 5 queda justo a la mitad entre 4 y 6."}},"check":{"q":{"en":"What number is halfway between 7 and 10?","es":"¿Qué número está a la mitad entre 7 y 10?"},"options":["8","17","8.5"],"correctIdx":2,"calc":{"expr":"(7 + 10) ÷ 2","value":"8.5"},"feedback":[{"en":"8 drops the half. 17 ÷ 2 is 8.5, so keep the .5.","es":"8 pierde la mitad. 17 ÷ 2 es 8.5, así que deja el .5."},{"en":"17 is the sum. Now divide it by 2.","es":"17 es la suma. Ahora divídela entre 2."},{"en":"Yes. 7 + 10 = 17, and 17 ÷ 2 = 8.5.","es":"Sí. 7 + 10 = 17, y 17 ÷ 2 = 8.5."}]}}]},"2-4":{"skills":[{"name":{"en":"Find the median of a data set","es":"Hallar la mediana de un conjunto de datos"},"why":{"en":"A box plot marks the median and the middle of each half, so you find middles several times.","es":"Un diagrama de caja marca la mediana y el medio de cada mitad, así que hallas el medio varias veces."},"steps":[{"en":"Put the numbers in order.","es":"Ordena los números."},{"en":"Cross off one number from each end until one or two are left.","es":"Tacha un número de cada extremo hasta que queden uno o dos."},{"en":"If two are left, add them and divide by 2.","es":"Si quedan dos, súmalos y divide entre 2."}],"example":{"en":"2, 4, 6, 9, 11: cross off 2 and 11, then 4 and 9. The median is 6.","es":"2, 4, 6, 9, 11: tacha 2 y 11, luego 4 y 9. La mediana es 6."},"model":{"kind":"numberline","data":{"min":0,"max":12,"step":1,"points":[{"value":2,"kind":"given","label":"2"},{"value":4,"kind":"given","label":"4"},{"value":6,"kind":"answer","label":{"en":"median 6","es":"mediana 6"}},{"value":9,"kind":"given","label":"9"},{"value":11,"kind":"given","label":"11"}]},"alt":{"en":"The values 2, 4, 6, 9, and 11 on a number line, with 6 marked as the median.","es":"Los valores 2, 4, 6, 9 y 11 en una recta numérica, con el 6 marcado como la mediana."}},"check":{"q":{"en":"What is the median of 3, 5, 8, 10?","es":"¿Cuál es la mediana de 3, 5, 8, 10?"},"options":["6.5","13","8"],"correctIdx":0,"calc":{"expr":"(5 + 8) ÷ 2","value":"6.5"},"feedback":[{"en":"Yes. 5 and 8 are in the middle: 13 ÷ 2 = 6.5.","es":"Sí. 5 y 8 están en el medio: 13 ÷ 2 = 6.5."},{"en":"13 is 5 + 8. Divide by 2 to land halfway.","es":"13 es 5 + 8. Divide entre 2 para quedar a la mitad."},{"en":"8 is only one of the two middle numbers. Use the number halfway between 5 and 8.","es":"8 es solo uno de los dos números del medio. Usa el número a la mitad entre 5 y 8."}]}},{"name":{"en":"Read a value on a number line","es":"Leer un valor en una recta numérica"},"why":{"en":"A box plot is drawn above a number line, so you read the value at each tick mark.","es":"Un diagrama de caja se dibuja sobre una recta numérica, así que lees el valor de cada marca."},"steps":[{"en":"Find what each jump is worth: subtract two labels and divide by the jumps between them.","es":"Halla cuánto vale cada salto: resta dos números escritos y divide entre los saltos que hay entre ellos."},{"en":"Count jumps forward from a labeled number.","es":"Cuenta los saltos hacia adelante desde un número escrito."}],"example":{"en":"Labels 0 and 10 with 5 jumps between: each jump is 10 ÷ 5 = 2. Three jumps past 0 is 6.","es":"Números 0 y 10 con 5 saltos entre ellos: cada salto vale 10 ÷ 5 = 2. Tres saltos después de 0 es 6."},"model":{"kind":"numberline","data":{"min":0,"max":10,"step":2,"points":[{"value":6,"kind":"answer","label":"6"}]},"alt":{"en":"A number line from 0 to 10 with jumps of 2; three jumps past 0 lands on 6.","es":"Una recta numérica de 0 a 10 con saltos de 2; tres saltos después de 0 llegan a 6."}},"check":{"q":{"en":"A number line counts by 5s starting at 20. A point is 3 jumps past 20. What value is it?","es":"Una recta numérica cuenta de 5 en 5 desde 20. Un punto está 3 saltos después de 20. ¿Qué valor es?"},"options":["23","35","15"],"correctIdx":1,"calc":{"expr":"20 + 3 × 5","value":"35"},"feedback":[{"en":"23 counts each jump as 1. Each jump is 5: 25, 30, 35.","es":"23 cuenta cada salto como 1. Cada salto vale 5: 25, 30, 35."},{"en":"Yes. 20, then 25, 30, 35.","es":"Sí. 20, luego 25, 30, 35."},{"en":"15 is only the 3 jumps. Start counting from 20, not from 0.","es":"15 son solo los 3 saltos. Empieza a contar desde 20, no desde 0."}]}}]},"2-5":{"skills":[{"name":{"en":"Split ordered data into a lower and upper half","es":"Dividir los datos ordenados en mitad inferior y superior"},"why":{"en":"The interquartile range uses the middle of each half, so you split the data first.","es":"El rango intercuartílico usa el medio de cada mitad, así que primero divides los datos."},"steps":[{"en":"Order the data and find the median.","es":"Ordena los datos y halla la mediana."},{"en":"Numbers below the median form the lower half. Numbers above it form the upper half.","es":"Los números antes de la mediana forman la mitad inferior. Los de después forman la mitad superior."},{"en":"With an odd count, leave the median out of both halves.","es":"Si la cantidad es impar, deja la mediana fuera de las dos mitades."}],"example":{"en":"2, 5, 7, 9, 12: the median is 7. Lower half: 2, 5. Upper half: 9, 12.","es":"2, 5, 7, 9, 12: la mediana es 7. Mitad inferior: 2, 5. Mitad superior: 9, 12."},"model":{"kind":"numberline","data":{"min":0,"max":14,"step":1,"points":[{"value":2,"kind":"given","label":"2"},{"value":5,"kind":"given","label":"5"},{"value":7,"kind":"answer","label":{"en":"median 7","es":"mediana 7"}},{"value":9,"kind":"given","label":"9"},{"value":12,"kind":"given","label":"12"}]},"alt":{"en":"The data 2, 5, 7, 9, 12 on a number line; the median 7 splits the lower half from the upper half.","es":"Los datos 2, 5, 7, 9, 12 en una recta numérica; la mediana 7 separa la mitad inferior de la superior."}},"check":{"q":{"en":"Data: 1, 4, 6, 8, 10, 13. What is the middle of the lower half?","es":"Datos: 1, 4, 6, 8, 10, 13. ¿Cuál es el medio de la mitad inferior?"},"options":["7","10","4"],"correctIdx":2,"calc":{"expr":"4","value":"4"},"feedback":[{"en":"7 is the median of all the data. Look only at the lower half: 1, 4, 6.","es":"7 es la mediana de todos los datos. Mira solo la mitad inferior: 1, 4, 6."},{"en":"10 is the middle of the upper half. Use the lower half: 1, 4, 6.","es":"10 es el medio de la mitad superior. Usa la mitad inferior: 1, 4, 6."},{"en":"Yes. The lower half is 1, 4, 6, and its middle is 4.","es":"Sí. La mitad inferior es 1, 4, 6, y su número del medio es 4."}]}},{"name":{"en":"Subtract to find how far apart","es":"Restar para hallar qué tan separados están"},"why":{"en":"Range and interquartile range are both found by subtracting a smaller value from a larger one.","es":"El rango y el rango intercuartílico se hallan restando un valor menor de uno mayor."},"steps":[{"en":"Find the larger and the smaller value.","es":"Busca el valor mayor y el menor."},{"en":"Subtract the smaller from the larger. Regroup when a top digit is too small.","es":"Resta el menor del mayor. Reagrupa cuando un dígito de arriba es muy pequeño."}],"example":{"en":"From 9 to 23: 23 − 9 = 14.","es":"De 9 a 23: 23 − 9 = 14."},"model":{"kind":"numberline","data":{"min":0,"max":24,"step":1,"points":[{"value":9,"kind":"given","label":"9"},{"value":23,"kind":"given","label":"23"}]},"alt":{"en":"A number line with points at 9 and 23; the space between them is the distance.","es":"Una recta numérica con puntos en 9 y 23; el espacio entre ellos es la distancia."}},"check":{"q":{"en":"The data go from 37 to 82. How far apart are they?","es":"Los datos van de 37 a 82. ¿Qué tan separados están?"},"options":["45","119","55"],"correctIdx":0,"calc":{"expr":"82 − 37","value":"45"},"feedback":[{"en":"Yes. 82 − 37 = 45.","es":"Sí. 82 − 37 = 45."},{"en":"119 adds the numbers. Subtract to find how far apart they are.","es":"119 suma los números. Resta para hallar qué tan separados están."},{"en":"55 subtracts 2 from 7 in the ones. Regroup: 12 − 7 = 5, then 7 − 3 = 4.","es":"55 resta 2 de 7 en las unidades. Reagrupa: 12 − 7 = 5, luego 7 − 3 = 4."}]}}]},"2-6":{"skills":[{"name":{"en":"Find how many times a number fits","es":"Hallar cuántas veces cabe un número"},"why":{"en":"Each step of long division asks how many times the divisor fits into part of the dividend.","es":"Cada paso de la división larga pregunta cuántas veces cabe el divisor en una parte del dividendo."},"steps":[{"en":"Use times facts for the divisor: 7 × 5, 7 × 6, 7 × 7.","es":"Usa las tablas del divisor: 7 × 5, 7 × 6, 7 × 7."},{"en":"Stop at the biggest product that is not more than the number.","es":"Detente en el producto más grande que no pasa del número."},{"en":"What is left over must be less than the divisor.","es":"Lo que sobra debe ser menor que el divisor."}],"example":{"en":"How many 7s fit in 45? 7 × 6 = 42 and 7 × 7 = 49. So 6 fit, with 3 left over.","es":"¿Cuántos 7 caben en 45? 7 × 6 = 42 y 7 × 7 = 49. Caben 6 y sobran 3."},"model":{"kind":"numberline","data":{"min":35,"max":49,"step":1,"points":[{"value":42,"kind":"given","label":"42"},{"value":45,"kind":"answer","label":"45"},{"value":49,"kind":"error","label":"49"}]},"alt":{"en":"A number line: 7 × 6 = 42 fits under 45, but 7 × 7 = 49 goes past it.","es":"Una recta numérica: 7 × 6 = 42 cabe antes de 45, pero 7 × 7 = 49 se pasa."}},"check":{"q":{"en":"How many times does 8 fit into 59?","es":"¿Cuántas veces cabe 8 en 59?"},"options":["8","7","6"],"correctIdx":1,"calc":{"expr":"56 ÷ 8","value":"7"},"feedback":[{"en":"8 × 8 = 64, which is more than 59. Try one less.","es":"8 × 8 = 64, que pasa de 59. Prueba con uno menos."},{"en":"Yes. 8 × 7 = 56, and 3 is left over.","es":"Sí. 8 × 7 = 56, y sobran 3."},{"en":"8 × 6 = 48 leaves 11. That is more than 8, so one more 8 fits.","es":"8 × 6 = 48 y sobran 11. Eso es más que 8, así que cabe otro 8."}]}},{"name":{"en":"Check division with multiplication","es":"Comprobar una división con multiplicación"},"why":{"en":"After you divide tonight, multiplying back shows whether the quotient and remainder are right.","es":"Después de dividir hoy, multiplicar al revés te muestra si el cociente y el residuo están bien."},"steps":[{"en":"Multiply the quotient by the divisor.","es":"Multiplica el cociente por el divisor."},{"en":"Add the remainder.","es":"Suma el residuo."},{"en":"You should get the dividend back.","es":"Debes obtener otra vez el dividendo."}],"example":{"en":"45 ÷ 7 = 6 R3. Check: 6 × 7 = 42, then 42 + 3 = 45.","es":"45 ÷ 7 = 6 R3. Comprueba: 6 × 7 = 42, luego 42 + 3 = 45."},"model":{"kind":"balance","data":{"left":["42","3"],"right":["45"]},"alt":{"en":"A level balance: 42 (that is 6 × 7) and the remainder 3 equal 45.","es":"Una balanza nivelada: 42 (o sea 6 × 7) y el residuo 3 pesan lo mismo que 45."}},"check":{"q":{"en":"Mia got 83 ÷ 6 = 13 R5. What is 13 × 6 + 5?","es":"Mia obtuvo 83 ÷ 6 = 13 R5. ¿Cuánto es 13 × 6 + 5?"},"options":["78","73","83"],"correctIdx":2,"calc":{"expr":"13 × 6 + 5","value":"83"},"feedback":[{"en":"78 is only 13 × 6. Add the remainder, 5.","es":"78 es solo 13 × 6. Suma el residuo, 5."},{"en":"73 subtracts the remainder. Add it: 78 + 5.","es":"73 resta el residuo. Súmalo: 78 + 5."},{"en":"Yes. 78 + 5 = 83, the dividend, so Mia is right.","es":"Sí. 78 + 5 = 83, el dividendo, así que Mia tiene razón."}]}}]},"2-7":{"skills":[{"name":{"en":"Multiply a decimal by 10 or 100","es":"Multiplicar un decimal por 10 o por 100"},"why":{"en":"Tonight you slide both decimal points right to make the divisor whole, which is multiplying by 10 or 100.","es":"Hoy deslizas los dos puntos decimales a la derecha para que el divisor sea entero; eso es multiplicar por 10 o 100."},"steps":[{"en":"Times 10 moves the decimal point one place right.","es":"Por 10, el punto decimal se mueve un lugar a la derecha."},{"en":"Times 100 moves it two places right.","es":"Por 100, se mueve dos lugares a la derecha."},{"en":"Write zeros if you run out of digits.","es":"Escribe ceros si te faltan dígitos."}],"example":{"en":"2.1 × 10 = 21, and 0.45 × 100 = 45.","es":"2.1 × 10 = 21, y 0.45 × 100 = 45."},"model":{"kind":"grid","data":{"rows":10,"cols":10,"filled":45,"groupSize":10,"label":"0.45 × 100 = 45"},"alt":{"en":"A hundred grid with 45 squares filled: 0.45 of the grid is 45 hundredths, so times 100 gives 45.","es":"Una cuadrícula de cien con 45 cuadros llenos: 0.45 son 45 centésimas, así que por 100 da 45."}},"check":{"q":{"en":"What is 3.6 × 100?","es":"¿Cuánto es 3.6 × 100?"},"options":["36","360","0.036"],"correctIdx":1,"calc":{"expr":"3.6 × 100","value":"360"},"feedback":[{"en":"36 moves the point only one place. Times 100 moves it two places.","es":"36 mueve el punto solo un lugar. Por 100 se mueve dos lugares."},{"en":"Yes. Two places right, with a 0 added: 360.","es":"Sí. Dos lugares a la derecha, con un 0 de más: 360."},{"en":"0.036 moves the point left, which is dividing. Multiplying moves it right.","es":"0.036 mueve el punto a la izquierda, y eso es dividir. Al multiplicar se mueve a la derecha."}]}},{"name":{"en":"Divide a decimal by a whole number","es":"Dividir un decimal entre un número entero"},"why":{"en":"Once the divisor is a whole number, you divide and bring the decimal point straight up.","es":"Cuando el divisor ya es un número entero, divides y subes el punto decimal en línea recta."},"steps":[{"en":"Divide as if there were no decimal point.","es":"Divide como si no hubiera punto decimal."},{"en":"Put the point in the quotient right above the point in the dividend.","es":"Pon el punto en el cociente justo arriba del punto del dividendo."}],"example":{"en":"8.4 ÷ 4: 84 ÷ 4 = 21, and the point goes straight up, so 2.1.","es":"8.4 ÷ 4: 84 ÷ 4 = 21, y el punto sube en línea recta, así que 2.1."},"model":{"kind":"tape","data":{"parts":4,"highlight":1,"blockLabel":"2.1","wholeLabel":"8.4","unknown":null},"alt":{"en":"A tape of 8.4 split into 4 equal blocks, each block 2.1.","es":"Una cinta de 8.4 dividida en 4 bloques iguales; cada bloque vale 2.1."}},"check":{"q":{"en":"What is 9.6 ÷ 3?","es":"¿Cuánto es 9.6 ÷ 3?"},"options":["32","0.32","3.2"],"correctIdx":2,"calc":{"expr":"9.6 ÷ 3","value":"3.2"},"feedback":[{"en":"32 forgets the decimal point. Bring it straight up from 9.6.","es":"32 olvida el punto decimal. Súbelo en línea recta desde 9.6."},{"en":"0.32 puts the point one place too far left. 9.6 ÷ 3 is about 3.","es":"0.32 pone el punto un lugar muy a la izquierda. 9.6 ÷ 3 es cerca de 3."},{"en":"Yes. 96 ÷ 3 = 32, and the point goes up: 3.2.","es":"Sí. 96 ÷ 3 = 32, y el punto sube: 3.2."}]}}]},"2-8":{"skills":[{"name":{"en":"Add a list of numbers","es":"Sumar una lista de números"},"why":{"en":"Finding the mean starts with the total of all the data values.","es":"Para hallar la media, primero hallas el total de todos los valores."},"steps":[{"en":"Add two numbers at a time.","es":"Suma de dos números a la vez."},{"en":"Look for pairs that make 10 or 20 first.","es":"Busca primero parejas que sumen 10 o 20."},{"en":"Check that you used every number once.","es":"Revisa que usaste cada número una vez."}],"example":{"en":"6 + 9 + 4 + 11: (6 + 4) + (9 + 11) = 10 + 20 = 30.","es":"6 + 9 + 4 + 11: junta (6 + 4) y (9 + 11). Queda 10 + 20 = 30."},"model":{"kind":"balance","data":{"left":["6","9","4","11"],"right":["10","20"]},"alt":{"en":"A level balance: 6, 9, 4, and 11 on one side equal 10 and 20 on the other.","es":"Una balanza nivelada: 6, 9, 4 y 11 de un lado pesan lo mismo que 10 y 20 del otro."}},"check":{"q":{"en":"Add 7, 12, 3, and 8.","es":"Suma 7, 12, 3 y 8."},"options":["30","22","27"],"correctIdx":0,"calc":{"expr":"7 + 12 + 3 + 8","value":"30"},"feedback":[{"en":"Yes. (7 + 3) + (12 + 8) = 10 + 20 = 30.","es":"Sí. (7 + 3) + (12 + 8) = 10 + 20 = 30."},{"en":"22 leaves out the 8. Add every number once.","es":"22 deja fuera el 8. Suma cada número una vez."},{"en":"27 leaves out the 3. Add every number once.","es":"27 deja fuera el 3. Suma cada número una vez."}]}},{"name":{"en":"Share a total equally","es":"Repartir un total en partes iguales"},"why":{"en":"The mean is a fair share: the total split equally among all the values.","es":"La media es un reparto justo: el total repartido en partes iguales entre todos los valores."},"steps":[{"en":"Count how many shares there are.","es":"Cuenta cuántas partes hay."},{"en":"Divide the total by that number.","es":"Divide el total entre ese número."}],"example":{"en":"3 friends share 12 stickers: 12 ÷ 3 = 4 stickers each.","es":"3 amigos se reparten 12 calcomanías: 12 ÷ 3 = 4 para cada uno."},"model":{"kind":"tape","data":{"parts":3,"highlight":1,"blockLabel":"4","wholeLabel":{"en":"12 stickers","es":"12 calcomanías"},"unknown":null},"alt":{"en":"A tape of 12 stickers split into 3 equal shares of 4.","es":"Una cinta de 12 calcomanías dividida en 3 partes iguales de 4."}},"check":{"q":{"en":"5 friends share 35 cards equally. How many does each friend get?","es":"5 amigos se reparten 35 tarjetas en partes iguales. ¿Cuántas recibe cada uno?"},"options":["30","7","175"],"correctIdx":1,"calc":{"expr":"35 ÷ 5","value":"7"},"feedback":[{"en":"30 subtracts 5. Sharing equally means divide: 35 ÷ 5.","es":"30 resta 5. Repartir en partes iguales es dividir: 35 ÷ 5."},{"en":"Yes. 35 ÷ 5 = 7 cards each.","es":"Sí. 35 ÷ 5 = 7 tarjetas para cada uno."},{"en":"175 multiplies. Each share should be smaller than the total, so divide.","es":"175 multiplica. Cada parte debe ser menor que el total, así que divide."}]}}]},"2-9":{"skills":[{"name":{"en":"Find the mean","es":"Hallar la media"},"why":{"en":"Tonight you find the mean first, then measure how far each value is from it.","es":"Hoy primero hallas la media y luego mides qué tan lejos está cada valor de ella."},"steps":[{"en":"Add all the values.","es":"Suma todos los valores."},{"en":"Divide the total by how many values there are.","es":"Divide el total entre la cantidad de valores."}],"example":{"en":"4, 6, 11: 4 + 6 + 11 = 21, then 21 ÷ 3 = 7.","es":"4, 6, 11: 4 + 6 + 11 = 21, luego 21 ÷ 3 = 7."},"model":{"kind":"balance","data":{"left":["4","6","11"],"right":["7","7","7"]},"alt":{"en":"A level balance: 4, 6, and 11 on one side equal three 7s on the other, so the mean is 7.","es":"Una balanza nivelada: 4, 6 y 11 de un lado pesan lo mismo que tres 7 del otro; la media es 7."}},"check":{"q":{"en":"Find the mean of 3, 5, 6, and 10.","es":"Halla la media de 3, 5, 6 y 10."},"options":["6","24","8"],"correctIdx":0,"calc":{"expr":"(3 + 5 + 6 + 10) ÷ 4","value":"6"},"feedback":[{"en":"Yes. The total is 24, and 24 ÷ 4 = 6.","es":"Sí. El total es 24, y 24 ÷ 4 = 6."},{"en":"24 is the total. Now divide by 4, the number of values.","es":"24 es el total. Ahora divide entre 4, la cantidad de valores."},{"en":"8 divides by 3. There are 4 values, so use 24 ÷ 4.","es":"8 divide entre 3. Hay 4 valores, así que usa 24 ÷ 4."}]}},{"name":{"en":"Find the distance between two numbers","es":"Hallar la distancia entre dos números"},"why":{"en":"Mean absolute deviation adds up how far each value is from the mean, and a distance is never negative.","es":"La desviación media absoluta usa qué tan lejos está cada valor de la media, y una distancia nunca es negativa."},"steps":[{"en":"Take the bigger of the two numbers.","es":"Toma el mayor de los dos números."},{"en":"Subtract the smaller one. The answer is the distance, on either side.","es":"Resta el menor. El resultado es la distancia, de cualquier lado."}],"example":{"en":"Mean 10, value 6: 10 − 6 = 4. Value 14: 14 − 10 = 4. Both are 4 away.","es":"Media 10, valor 6: 10 − 6 = 4. Valor 14: 14 − 10 = 4. Los dos están a 4."},"model":{"kind":"numberline","data":{"min":0,"max":16,"step":1,"points":[{"value":6,"kind":"given","label":"6"},{"value":10,"kind":"answer","label":{"en":"mean 10","es":"media 10"}},{"value":14,"kind":"given","label":"14"}]},"alt":{"en":"A number line with the mean at 10 and values at 6 and 14, each 4 away.","es":"Una recta numérica con la media en 10 y valores en 6 y 14, cada uno a 4 de distancia."}},"check":{"q":{"en":"The mean is 12. A value is 7. How far is the value from the mean?","es":"La media es 12. Un valor es 7. ¿Qué tan lejos está el valor de la media?"},"options":["19","7","5"],"correctIdx":2,"calc":{"expr":"12 − 7","value":"5"},"feedback":[{"en":"19 adds the numbers. A distance subtracts: 12 − 7.","es":"19 suma los números. Una distancia se resta: 12 − 7."},{"en":"7 is the value itself. Find the gap between 7 and 12.","es":"7 es el valor mismo. Halla el espacio entre 7 y 12."},{"en":"Yes. 12 − 7 = 5, so the value is 5 away.","es":"Sí. 12 − 7 = 5, así que el valor está a 5 de distancia."}]}}]},"3-1":{"skills":[{"name":{"en":"Find a missing part of a group","es":"Hallar la parte que falta de un grupo"},"why":{"en":"A ratio compares two amounts, and often you must find one amount from the total first.","es":"Una razón compara dos cantidades, y muchas veces primero debes hallar una cantidad a partir del total."},"steps":[{"en":"Sort the items into two groups and count one group.","es":"Separa los objetos en dos grupos y cuenta un grupo."},{"en":"Subtract that count from the total to get the other group.","es":"Resta esa cantidad del total para hallar el otro grupo."},{"en":"Check: the two groups add up to the total.","es":"Comprueba: los dos grupos suman el total."}],"example":{"en":"A bag has 9 marbles. 4 are red, so 9 − 4 = 5 are blue. 4 + 5 = 9.","es":"Una bolsa tiene 9 canicas. 4 son rojas, así que 9 − 4 = 5 son azules. 4 + 5 = 9."},"model":{"kind":"tape","data":{"parts":9,"highlight":4,"partLabel":{"en":"4 red","es":"4 rojas"},"wholeLabel":{"en":"9 marbles","es":"9 canicas"},"unknown":null},"alt":{"en":"A tape of 9 marbles with 4 red blocks; the other 5 blocks are blue.","es":"Una cinta de 9 canicas con 4 bloques rojos; los otros 5 bloques son azules."}},"check":{"q":{"en":"A class has 26 students. 14 are girls. How many are boys?","es":"Una clase tiene 26 estudiantes. 14 son niñas. ¿Cuántos son niños?"},"options":["40","12","14"],"correctIdx":1,"calc":{"expr":"26 − 14","value":"12"},"feedback":[{"en":"40 adds the numbers. The girls are part of the 26, so subtract.","es":"40 suma los números. Las niñas son parte de los 26, así que resta."},{"en":"Yes. 26 − 14 = 12 boys, and 14 + 12 = 26.","es":"Sí. 26 − 14 = 12 niños, y 14 + 12 = 26."},{"en":"14 is the number of girls. Subtract it from the total, 26.","es":"14 es la cantidad de niñas. Réstala del total, 26."}]}},{"name":{"en":"Compare with times as many","es":"Comparar con veces más"},"why":{"en":"Ratios compare by multiplying, so you need to say how many times as big one amount is.","es":"Las razones comparan con multiplicación, así que necesitas decir cuántas veces más grande es una cantidad."},"steps":[{"en":"Divide the bigger amount by the smaller amount.","es":"Divide la cantidad mayor entre la menor."},{"en":"The quotient tells how many times as many.","es":"El cociente dice cuántas veces más hay."}],"example":{"en":"12 dogs and 4 cats: 12 ÷ 4 = 3, so there are 3 times as many dogs as cats.","es":"12 perros y 4 gatos: 12 ÷ 4 = 3, así que hay 3 veces más perros que gatos."},"model":{"kind":"barplot","data":{"categories":[{"label":{"en":"Dogs","es":"Perros"},"value":12},{"label":{"en":"Cats","es":"Gatos"},"value":4}]},"alt":{"en":"A bar graph: the dogs bar, 12, is 3 times as long as the cats bar, 4.","es":"Una gráfica de barras: la barra de perros, 12, es 3 veces más larga que la de gatos, 4."}},"check":{"q":{"en":"There are 18 apples and 6 pears. How many times as many apples as pears?","es":"Hay 18 manzanas y 6 peras. ¿Cuántas veces más manzanas que peras hay?"},"options":["12","24","3"],"correctIdx":2,"calc":{"expr":"18 ÷ 6","value":"3"},"feedback":[{"en":"12 tells how many more apples. Times as many means divide: 18 ÷ 6.","es":"12 dice cuántas manzanas más hay. Veces más significa dividir: 18 ÷ 6."},{"en":"24 adds the fruit. Divide the apples by the pears instead.","es":"24 suma las frutas. Mejor divide las manzanas entre las peras."},{"en":"Yes. 18 ÷ 6 = 3, so 3 times as many apples.","es":"Sí. 18 ÷ 6 = 3, así que hay 3 veces más manzanas."}]}}]},"3-10":{"skills":[{"name":{"en":"Multiply and divide by 10, 100, and 1,000","es":"Multiplicar y dividir con 10, 100 y 1,000"},"why":{"en":"Metric units change by 10, 100, or 1,000, like 100 cm = 1 m.","es":"Las unidades métricas cambian por 10, 100 o 1,000, como 100 cm = 1 m."},"steps":[{"en":"To multiply, move the decimal point right one place for each zero.","es":"Al multiplicar, mueve el punto decimal a la derecha un lugar por cada cero."},{"en":"To divide, move the decimal point left one place for each zero.","es":"Al dividir, mueve el punto decimal a la izquierda un lugar por cada cero."}],"example":{"en":"2.5 × 100 = 250 (2 places right). 250 ÷ 1,000 = 0.25 (3 places left).","es":"2.5 × 100 = 250 (2 lugares a la derecha). 250 ÷ 1,000 = 0.25 (3 lugares a la izquierda)."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Meters","es":"Metros"},{"en":"Centimeters","es":"Centímetros"}],"rows":[[1,100],[2.5,250]],"arrows":[{"from":0,"to":1,"label":"×2.5"}]},"alt":{"en":"A table shows 1 meter is 100 cm, so 2.5 meters is 250 cm.","es":"Una tabla muestra que 1 metro son 100 cm, así que 2.5 metros son 250 cm."}},"check":{"q":{"en":"What is 3.5 × 100?","es":"¿Cuánto es 3.5 × 100?"},"options":["35","350","0.035"],"correctIdx":1,"calc":{"expr":"3.5 × 100","value":"350"},"feedback":[{"en":"35 moves the point only 1 place. 100 has 2 zeros, so move 2.","es":"35 mueve el punto solo 1 lugar. 100 tiene 2 ceros, así que muévelo 2."},{"en":"Yes. 2 places right: 3.5 becomes 350.","es":"Sí. 2 lugares a la derecha: 3.5 se convierte en 350."},{"en":"0.035 moves the point left, which divides. Multiplying moves it right.","es":"0.035 mueve el punto a la izquierda, y eso es dividir. Al multiplicar, se mueve a la derecha."}]}},{"name":{"en":"Smaller unit: multiply. Bigger unit: divide.","es":"Unidad más pequeña: multiplica. Unidad más grande: divide."},"why":{"en":"Each conversion tonight starts by deciding whether to multiply or divide by the conversion factor.","es":"Cada conversión de hoy empieza al decidir si multiplicas por el factor de conversión o divides entre él."},"steps":[{"en":"Know the fact, like 12 inches = 1 foot.","es":"Recuerda la equivalencia, como 12 pulgadas = 1 pie."},{"en":"To a smaller unit, you need more of them, so multiply.","es":"Para pasar a una unidad más pequeña, necesitas más, así que multiplica."},{"en":"To a bigger unit, you need fewer, so divide.","es":"Para pasar a una unidad más grande, necesitas menos, así que divide."}],"example":{"en":"3 feet to inches: 3 × 12 = 36 inches. 200 cm to meters: 200 ÷ 100 = 2 meters.","es":"3 pies a pulgadas: 3 × 12 = 36 pulgadas. 200 cm a metros: 200 ÷ 100 = 2 metros."},"model":{"kind":"doubleline","data":{"top":{"label":{"en":"Feet","es":"Pies"},"ticks":["0","1","3"]},"bottom":{"label":{"en":"Inches","es":"Pulgadas"},"ticks":["0","12","36"]}},"alt":{"en":"A double number line lines up 1 foot with 12 inches and 3 feet with 36 inches.","es":"Una recta numérica doble alinea 1 pie con 12 pulgadas y 3 pies con 36 pulgadas."}},"check":{"q":{"en":"How many feet is 48 inches?","es":"¿Cuántos pies son 48 pulgadas?"},"options":["4","576","36"],"correctIdx":0,"calc":{"expr":"48 ÷ 12","value":"4"},"feedback":[{"en":"Yes. Feet are bigger, so divide: 48 ÷ 12 = 4.","es":"Sí. El pie es más grande, así que divide: 48 ÷ 12 = 4."},{"en":"576 multiplies. Feet are a bigger unit, so you need fewer: divide by 12.","es":"576 viene de multiplicar. El pie es más grande, así que necesitas menos: divide entre 12."},{"en":"36 subtracts 12 once. Divide to see how many 12s fit in 48.","es":"36 resta 12 una sola vez. Divide para ver cuántos grupos de 12 caben en 48."}]}}]},"3-2":{"skills":[{"name":{"en":"Divide to find the amount for one","es":"Dividir para hallar la cantidad para uno"},"why":{"en":"A unit rate is the amount for exactly 1, and you find it by dividing.","es":"Una tasa unitaria es la cantidad para exactamente 1, y la hallas dividiendo."},"steps":[{"en":"Find the total amount and how many groups share it.","es":"Busca la cantidad total y cuántos grupos se la reparten."},{"en":"Divide the total by the number of groups.","es":"Divide el total entre la cantidad de grupos."}],"example":{"en":"$6 for 3 pens: 6 ÷ 3 = 2, so 1 pen costs $2.","es":"$6 por 3 bolígrafos: 6 ÷ 3 = 2, así que 1 bolígrafo cuesta $2."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Pens","es":"Bolígrafos"},{"en":"Dollars","es":"Dólares"}],"rows":[[3,6],[1,2]],"arrows":[{"from":0,"to":1,"label":"÷ 3"}]},"alt":{"en":"A table: 3 pens cost $6; dividing both by 3 gives 1 pen for $2.","es":"Una tabla: 3 bolígrafos cuestan $6; al dividir ambos entre 3, 1 bolígrafo cuesta $2."}},"check":{"q":{"en":"4 tickets cost $28. How many dollars does 1 ticket cost?","es":"4 boletos cuestan $28. ¿Cuántos dólares cuesta 1 boleto?"},"options":["24","7","112"],"correctIdx":1,"calc":{"expr":"28 ÷ 4","value":"7"},"feedback":[{"en":"24 subtracts 4. To find the cost of 1, divide: 28 ÷ 4.","es":"24 resta 4. Para hallar el precio de 1, divide: 28 ÷ 4."},{"en":"Yes. 28 ÷ 4 = 7, so 1 ticket costs $7.","es":"Sí. 28 ÷ 4 = 7, así que 1 boleto cuesta $7."},{"en":"112 multiplies. One ticket costs less than four, so divide.","es":"112 multiplica. Un boleto cuesta menos que cuatro, así que divide."}]}},{"name":{"en":"Divide with a decimal answer","es":"Dividir con una respuesta decimal"},"why":{"en":"Unit prices often do not divide evenly, so you keep dividing into tenths and hundredths.","es":"Los precios unitarios muchas veces no salen exactos, así que sigues dividiendo en décimas y centésimas."},"steps":[{"en":"Divide as usual until you have a remainder.","es":"Divide como siempre hasta que quede un residuo."},{"en":"Write a decimal point and a 0, then keep dividing.","es":"Escribe un punto decimal y un 0, y sigue dividiendo."},{"en":"Stop when nothing is left, or at hundredths for money.","es":"Para cuando no sobre nada, o en las centésimas si es dinero."}],"example":{"en":"$5 for 2 pounds: 5 ÷ 2 is 2 with 1 left. 10 ÷ 2 = 5, so $2.50 per pound.","es":"$5 por 2 libras: 5 ÷ 2 da 2 y sobra 1. 10 ÷ 2 = 5, así que $2.50 por libra."},"model":{"kind":"doubleline","data":{"top":{"label":{"en":"Dollars","es":"Dólares"},"ticks":["$0","$2.50","$5"]},"bottom":{"label":{"en":"Pounds","es":"Libras"},"ticks":[0,1,2]}},"alt":{"en":"A double number line: $5 lines up with 2 pounds and $2.50 lines up with 1 pound.","es":"Una recta numérica doble: $5 va con 2 libras y $2.50 va con 1 libra."}},"check":{"q":{"en":"What is 9 ÷ 4?","es":"¿Cuánto es 9 ÷ 4?"},"options":["2.25","2.1","36"],"correctIdx":0,"calc":{"expr":"9 ÷ 4","value":"2.25"},"feedback":[{"en":"Yes. 9 ÷ 4 = 2 with 1 left, and 1 ÷ 4 = 0.25.","es":"Sí. 9 ÷ 4 da 2 y sobra 1, y 1 ÷ 4 = 0.25."},{"en":"2.1 writes the remainder 1 as a decimal digit. Keep dividing: 10 ÷ 4, then 20 ÷ 4.","es":"2.1 escribe el residuo 1 como dígito decimal. Sigue dividiendo: 10 ÷ 4, luego 20 ÷ 4."},{"en":"36 multiplies. The answer to 9 ÷ 4 is between 2 and 3.","es":"36 multiplica. El resultado de 9 ÷ 4 está entre 2 y 3."}]}}]},"3-3":{"skills":[{"name":{"en":"Make equivalent fractions by multiplying","es":"Formar fracciones equivalentes multiplicando"},"why":{"en":"Each column of a ratio table multiplies both numbers by the same number, just like equivalent fractions.","es":"Cada columna de una tabla de razones multiplica los dos números por el mismo número, como en las fracciones equivalentes."},"steps":[{"en":"Find what the denominator was multiplied by.","es":"Halla por cuánto se multiplicó el denominador."},{"en":"Multiply the numerator by that same number.","es":"Multiplica el numerador por ese mismo número."}],"example":{"en":"2/3 = ?/12: 3 × 4 = 12, so 2 × 4 = 8. The answer is 8/12.","es":"2/3 = ?/12: 3 × 4 = 12, así que 2 × 4 = 8. La respuesta es 8/12."},"model":{"kind":"fraction","data":{"parts":12,"shaded":8,"label":"2/3 = 8/12"},"alt":{"en":"A bar cut into 12 equal parts with 8 shaded, the same amount as 2/3.","es":"Una barra cortada en 12 partes iguales con 8 sombreadas, la misma cantidad que 2/3."}},"check":{"q":{"en":"Fill in the blank: 2/5 = ?/20.","es":"Completa: 2/5 = ?/20."},"options":["17","4","8"],"correctIdx":2,"calc":{"expr":"20 ÷ 5 × 2","value":"8"},"feedback":[{"en":"17 adds 15 to the top. Equivalent fractions multiply both numbers by the same number.","es":"17 suma 15 arriba. Las fracciones equivalentes multiplican los dos números por el mismo número."},{"en":"4 is what you multiply by. Now multiply the top: 2 × 4.","es":"4 es el número por el que multiplicas. Ahora multiplica arriba: 2 × 4."},{"en":"Yes. 5 × 4 = 20, so 2 × 4 = 8.","es":"Sí. 5 × 4 = 20, así que 2 × 4 = 8."}]}},{"name":{"en":"Find the missing factor","es":"Hallar el factor que falta"},"why":{"en":"To fill a ratio table, you find the number that turns one value into another.","es":"Para completar una tabla de razones, hallas el número que convierte un valor en otro."},"steps":[{"en":"Ask: the old number times what gives the new number?","es":"Pregúntate: ¿el número de antes por cuánto da el número nuevo?"},{"en":"Divide the new number by the old number to find it.","es":"Divide el número nuevo entre el de antes para hallarlo."}],"example":{"en":"3 becomes 15: 15 ÷ 3 = 5, so multiply by 5.","es":"3 se vuelve 15: 15 ÷ 3 = 5, así que multiplica por 5."},"model":{"kind":"numberline","data":{"min":0,"max":15,"step":3,"points":[{"value":3,"kind":"given","label":"3"},{"value":15,"kind":"answer","label":"15"}]},"alt":{"en":"A number line counting by 3s: five jumps of 3 reach 15, so 3 × 5 = 15.","es":"Una recta numérica que cuenta de 3 en 3: cinco saltos de 3 llegan a 15, así que 3 × 5 = 15."}},"check":{"q":{"en":"What number times 6 gives 42?","es":"¿Qué número por 6 da 42?"},"options":["36","7","48"],"correctIdx":1,"calc":{"expr":"42 ÷ 6","value":"7"},"feedback":[{"en":"36 is 42 − 6. The question asks times what, so divide: 42 ÷ 6.","es":"36 es 42 − 6. La pregunta es por cuánto, así que divide: 42 ÷ 6."},{"en":"Yes. 6 × 7 = 42.","es":"Sí. 6 × 7 = 42."},{"en":"48 adds 6. Divide 42 by 6 to find the factor.","es":"48 suma 6. Divide 42 entre 6 para hallar el factor."}]}}]},"3-4":{"skills":[{"name":{"en":"Plot a point (x, y)","es":"Ubicar un punto (x, y)"},"why":{"en":"Each row of tonight's ratio table becomes an ordered pair you plot on the coordinate plane.","es":"Cada fila de la tabla de razones de hoy se vuelve un par ordenado que ubicas en el plano cartesiano."},"steps":[{"en":"Start at the origin, (0, 0).","es":"Empieza en el origen, (0, 0)."},{"en":"Move right the first number, x.","es":"Muévete a la derecha el primer número, x."},{"en":"Then move up the other number, y.","es":"Luego sube el otro número, y."}],"example":{"en":"(2, 6): from (0, 0), go right 2, then up 6.","es":"(2, 6): desde (0, 0), ve 2 a la derecha y luego sube 6."},"model":{"kind":"coord","data":{"xmax":8,"ymax":8,"points":[{"x":2,"y":6}]},"alt":{"en":"A grid with the point (2, 6): 2 to the right of the origin and 6 up.","es":"Una cuadrícula con el punto (2, 6): 2 a la derecha del origen y 6 hacia arriba."}},"check":{"q":{"en":"A point is 4 units right and 9 units up from (0, 0). What is its x-coordinate?","es":"Un punto está 4 unidades a la derecha y 9 hacia arriba de (0, 0). ¿Cuál es su coordenada x?"},"options":["9","4","13"],"correctIdx":1,"calc":{"expr":"4","value":"4"},"feedback":[{"en":"9 is how far up, which is y. The x-coordinate is how far right.","es":"9 es cuánto sube, o sea y. La coordenada x es cuánto va a la derecha."},{"en":"Yes. Right 4 means x = 4, so the point is (4, 9).","es":"Sí. 4 a la derecha significa x = 4, así que el punto es (4, 9)."},{"en":"13 adds the moves. Each number stays separate: x = 4, y = 9.","es":"13 suma los movimientos. Cada número va por separado: x = 4, y = 9."}]}},{"name":{"en":"Read the scale on an axis","es":"Leer la escala de un eje"},"why":{"en":"Ratio graphs often count by 2s, 5s, or 10s, so each grid line may be worth more than 1.","es":"Las gráficas de razones muchas veces cuentan de 2 en 2, de 5 en 5 o de 10 en 10, así que cada línea puede valer más de 1."},"steps":[{"en":"Look at two labels next to each other on the axis.","es":"Mira dos números seguidos escritos en el eje."},{"en":"Subtract them to find what each grid line is worth.","es":"Réstalos para saber cuánto vale cada línea."},{"en":"Count the lines by that amount.","es":"Cuenta las líneas sumando esa cantidad cada vez."}],"example":{"en":"Labels 0, 5, 10: each line is worth 5. Three lines up is 15.","es":"Números 0, 5, 10: cada línea vale 5. Tres líneas hacia arriba es 15."},"model":{"kind":"numberline","data":{"min":0,"max":20,"step":5,"points":[{"value":15,"kind":"answer","label":"15"}]},"alt":{"en":"An axis labeled 0, 5, 10, 15, 20; three lines up from 0 is 15.","es":"Un eje con 0, 5, 10, 15, 20; tres líneas desde 0 es 15."}},"check":{"q":{"en":"The y-axis counts by 4s. A point sits 6 lines up. What is its y-coordinate?","es":"El eje y cuenta de 4 en 4. Un punto está 6 líneas arriba. ¿Cuál es su coordenada y?"},"options":["6","10","24"],"correctIdx":2,"calc":{"expr":"6 × 4","value":"24"},"feedback":[{"en":"6 counts each line as 1. Each line is worth 4.","es":"6 cuenta cada línea como 1. Cada línea vale 4."},{"en":"10 adds 6 + 4. Six lines of 4 each is 6 × 4.","es":"10 suma 6 + 4. Seis líneas de 4 cada una es 6 × 4."},{"en":"Yes. 4, 8, 12, 16, 20, 24.","es":"Sí. 4, 8, 12, 16, 20, 24."}]}}]},"3-5":{"skills":[{"name":{"en":"Find the least common multiple","es":"Hallar el mínimo común múltiplo"},"why":{"en":"To compare two ratios, you scale them so one part matches, using a common multiple.","es":"Para comparar dos razones, las amplías hasta que una parte coincida, usando un múltiplo común."},"steps":[{"en":"List the multiples of each number.","es":"Escribe los múltiplos de cada número."},{"en":"The first number on both lists is the least common multiple.","es":"El primer número que está en las dos listas es el mínimo común múltiplo."}],"example":{"en":"Multiples of 4: 4, 8, 12. Multiples of 6: 6, 12. The least common multiple is 12.","es":"Múltiplos de 4: 4, 8, 12. Múltiplos de 6: 6, 12. El mínimo común múltiplo es 12."},"model":{"kind":"numberline","data":{"min":0,"max":12,"step":1,"points":[{"value":4,"kind":"given","label":"4"},{"value":6,"kind":"given","label":"6"},{"value":8,"kind":"given","label":"8"},{"value":12,"kind":"answer","label":"12"}]},"alt":{"en":"A number line with multiples of 4 (4, 8, 12) and of 6 (6, 12); both reach 12.","es":"Una recta numérica con múltiplos de 4 (4, 8, 12) y de 6 (6, 12); los dos llegan a 12."}},"check":{"q":{"en":"What is the least common multiple of 6 and 8?","es":"¿Cuál es el mínimo común múltiplo de 6 y 8?"},"options":["48","24","14"],"correctIdx":1,"calc":{"expr":"24","value":"24"},"feedback":[{"en":"48 is a common multiple, but not the least. 24 is on both lists first.","es":"48 es un múltiplo común, pero no el mínimo. 24 aparece antes en las dos listas."},{"en":"Yes. 6, 12, 18, 24 and 8, 16, 24 meet at 24.","es":"Sí. 6, 12, 18, 24 y 8, 16, 24 coinciden en 24."},{"en":"14 adds the numbers. A multiple comes from skip counting: 6, 12, 18, 24.","es":"14 suma los números. Un múltiplo sale de contar de 6 en 6: 6, 12, 18, 24."}]}},{"name":{"en":"Compare decimals","es":"Comparar decimales"},"why":{"en":"Unit rates are often decimals, so comparing ratios can mean deciding which decimal is greater.","es":"Las tasas unitarias muchas veces son decimales, así que comparar razones puede ser decidir qué decimal es mayor."},"steps":[{"en":"Line up the decimal points.","es":"Alinea los puntos decimales."},{"en":"Compare digits from left to right: ones, then tenths, then hundredths.","es":"Compara los dígitos de izquierda a derecha: unidades, luego décimas, luego centésimas."},{"en":"The first place that differs decides.","es":"El primer lugar que es diferente decide."}],"example":{"en":"2.5 and 2.45: the ones match. Tenths: 5 is more than 4, so 2.5 is greater.","es":"2.5 y 2.45: las unidades son iguales. Décimas: 5 es más que 4, así que 2.5 es mayor."},"model":{"kind":"numberline","data":{"min":2.3,"max":2.6,"step":0.05,"points":[{"value":2.45,"kind":"given","label":"2.45"},{"value":2.5,"kind":"answer","label":"2.5"}]},"alt":{"en":"A number line where 2.5 sits to the right of 2.45, so 2.5 is greater.","es":"Una recta numérica donde 2.5 queda a la derecha de 2.45, así que 2.5 es mayor."}},"check":{"q":{"en":"Which is greatest: 3.6, 3.45, or 3.09?","es":"¿Cuál es el mayor: 3.6, 3.45 o 3.09?"},"options":["3.6","3.45","3.09"],"correctIdx":0,"calc":{"expr":"3.6","value":"3.6"},"feedback":[{"en":"Yes. The ones match, and 6 tenths beats 4 tenths and 0 tenths.","es":"Sí. Las unidades son iguales, y 6 décimas es más que 4 décimas y 0 décimas."},{"en":"More digits does not mean bigger. Compare tenths: 6 is more than 4.","es":"Tener más dígitos no lo hace mayor. Compara las décimas: 6 es más que 4."},{"en":"3.09 has 0 tenths, the fewest. Compare the tenths digit first.","es":"3.09 tiene 0 décimas, la menor cantidad. Compara primero las décimas."}]}}]},"3-6":{"skills":[{"name":{"en":"Know common unit facts","es":"Conocer equivalencias comunes de unidades"},"why":{"en":"To convert tonight, you need the conversion factor, like 1 foot = 12 inches.","es":"Para convertir hoy, necesitas el factor de conversión, como 1 pie = 12 pulgadas."},"steps":[{"en":"Length: 1 foot = 12 inches, and 1 yard = 3 feet.","es":"Longitud: 1 pie = 12 pulgadas, y 1 yarda = 3 pies."},{"en":"Weight: 1 pound = 16 ounces. Metric: 1 meter = 100 centimeters.","es":"Peso: 1 libra = 16 onzas. Sistema métrico: 1 metro = 100 centímetros."}],"example":{"en":"A yardstick is 3 feet long. Each foot is 12 inches, so it is 3 × 12 = 36 inches.","es":"Una regla de una yarda mide 3 pies. Cada pie tiene 12 pulgadas, así que mide 3 × 12 = 36 pulgadas."},"model":{"kind":"doubleline","data":{"top":{"label":{"en":"Feet","es":"Pies"},"ticks":[0,1,2,3]},"bottom":{"label":{"en":"Inches","es":"Pulgadas"},"ticks":[0,12,24,36]}},"alt":{"en":"A double number line: 1, 2, and 3 feet line up with 12, 24, and 36 inches.","es":"Una recta numérica doble: 1, 2 y 3 pies van con 12, 24 y 36 pulgadas."}},"check":{"q":{"en":"How many inches are in 2 yards?","es":"¿Cuántas pulgadas hay en 2 yardas?"},"options":["72","24","6"],"correctIdx":0,"calc":{"expr":"2 × 3 × 12","value":"72"},"feedback":[{"en":"Yes. 2 yards = 6 feet, and 6 × 12 = 72 inches.","es":"Sí. 2 yardas = 6 pies, y 6 × 12 = 72 pulgadas."},{"en":"24 treats each yard as 1 foot. A yard is 3 feet: 2 × 3 = 6 feet first.","es":"24 trata cada yarda como 1 pie. Una yarda tiene 3 pies: primero 2 × 3 = 6 pies."},{"en":"6 is the number of feet. Now change feet to inches: 6 × 12.","es":"6 es la cantidad de pies. Ahora cambia los pies a pulgadas: 6 × 12."}]}},{"name":{"en":"Scale both numbers of a ratio","es":"Ampliar los dos números de una razón"},"why":{"en":"Ratio reasoning converts units: multiply both numbers of a known pair by the same amount.","es":"El razonamiento con razones convierte unidades: multiplica los dos números de una pareja conocida por la misma cantidad."},"steps":[{"en":"Write the pair you know, like 2 apples for $1.","es":"Escribe la pareja que conoces, como 2 manzanas por $1."},{"en":"Find what turns the known amount into the new amount.","es":"Halla qué convierte la cantidad conocida en la nueva."},{"en":"Multiply both numbers by it.","es":"Multiplica los dos números por ese número."}],"example":{"en":"2 apples cost $1. For 6 apples, 2 × 3 = 6, so the cost is 1 × 3 = $3.","es":"2 manzanas cuestan $1. Para 6 manzanas, 2 × 3 = 6, así que cuestan 1 × 3 = $3."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Apples","es":"Manzanas"},{"en":"Dollars","es":"Dólares"}],"rows":[[2,1],[6,3]],"arrows":[{"from":0,"to":1,"label":"× 3"}]},"alt":{"en":"A table: 2 apples for $1; multiplying both by 3 gives 6 apples for $3.","es":"Una tabla: 2 manzanas por $1; al multiplicar ambos por 3 quedan 6 manzanas por $3."}},"check":{"q":{"en":"A recipe uses 3 cups of flour for 2 cakes. How many cups for 8 cakes?","es":"Una receta usa 3 tazas de harina para 2 pasteles. ¿Cuántas tazas para 8 pasteles?"},"options":["9","12","24"],"correctIdx":1,"calc":{"expr":"3 × (8 ÷ 2)","value":"12"},"feedback":[{"en":"9 adds 6 cups for 6 more cakes. Scale by multiplying: 2 × 4 = 8, so 3 × 4.","es":"9 suma 6 tazas porque hay 6 pasteles más. Amplía multiplicando: 2 × 4 = 8, así que 3 × 4."},{"en":"Yes. 2 × 4 = 8 cakes, so 3 × 4 = 12 cups.","es":"Sí. 2 × 4 = 8 pasteles, así que 3 × 4 = 12 tazas."},{"en":"24 multiplies 3 by 8, but the 3 cups make 2 cakes, not 1. Multiply by 4.","es":"24 multiplica 3 por 8, pero las 3 tazas son para 2 pasteles, no 1. Multiplica por 4."}]}}]},"3-7":{"skills":[{"name":{"en":"Multiply a whole number by a decimal","es":"Multiplicar un número entero por un decimal"},"why":{"en":"Conversion factors like 1 km ≈ 0.6 mile are decimals, so tonight you multiply by them.","es":"Los factores de conversión, como 1 km ≈ 0.6 milla, son decimales, así que hoy multiplicas por ellos."},"steps":[{"en":"Multiply as if there were no decimal point.","es":"Multiplica como si no hubiera punto decimal."},{"en":"Count the digits after the point in the decimal.","es":"Cuenta las cifras que hay después del punto en el decimal."},{"en":"Place the point so the answer has that many digits after it.","es":"Coloca el punto para que la respuesta tenga esa misma cantidad de cifras después de él."}],"example":{"en":"4 × 2.54: 4 × 254 = 1016. 2.54 has 2 digits after the point, so 10.16.","es":"4 × 2.54: 4 × 254 = 1016. 2.54 tiene 2 cifras después del punto, así que da 10.16."},"model":{"kind":"doubleline","data":{"top":{"label":{"en":"Inches","es":"Pulgadas"},"ticks":["0","1","4"]},"bottom":{"label":{"en":"Centimeters","es":"Centímetros"},"ticks":["0","2.54","10.16"]}},"alt":{"en":"A double number line shows 1 inch = 2.54 cm, so 4 inches = 10.16 cm.","es":"Una recta numérica doble muestra que 1 pulgada son 2.54 cm, así que 4 pulgadas son 10.16 cm."}},"check":{"q":{"en":"What is 5 × 0.6?","es":"¿Cuánto es 5 × 0.6?"},"options":["30","3","0.3"],"correctIdx":1,"calc":{"expr":"5 × 0.6","value":"3"},"feedback":[{"en":"30 forgets the decimal point. 0.6 has 1 digit after the point, so 30 becomes 3.","es":"30 olvida el punto decimal. 0.6 tiene 1 cifra después del punto, así que 30 se convierte en 3."},{"en":"Yes. 5 × 6 = 30, and one digit after the point gives 3.","es":"Sí. 5 × 6 = 30, y una cifra después del punto da 3."},{"en":"0.3 moves the point too far. Move only 1 place: 30 becomes 3.","es":"0.3 mueve el punto demasiado. Muévelo solo 1 lugar: 30 se convierte en 3."}]}},{"name":{"en":"Find the amount for one, then scale","es":"Hallar la cantidad para uno y luego escalar"},"why":{"en":"Tonight you scale a conversion factor in a ratio table to change any amount.","es":"Hoy escalas un factor de conversión en una tabla de razones para cambiar cualquier cantidad."},"steps":[{"en":"Divide both amounts to find the amount for 1.","es":"Divide ambas cantidades para hallar la cantidad para 1."},{"en":"Multiply that amount for 1 by the number you need.","es":"Multiplica esa cantidad para 1 por el número que necesitas."}],"example":{"en":"10 cm ≈ 4 inches. Divide both by 10: 1 cm ≈ 0.4 inch. So 6 cm ≈ 2.4 inches.","es":"10 cm ≈ 4 pulgadas. Divide ambas entre 10: 1 cm ≈ 0.4 pulgada. Entonces 6 cm ≈ 2.4 pulgadas."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Centimeters","es":"Centímetros"},{"en":"Inches (about)","es":"Pulgadas (aprox.)"}],"rows":[[10,4],[1,0.4],[6,2.4]],"arrows":[{"from":0,"to":1,"label":"÷10"},{"from":1,"to":2,"label":"×6"}]},"alt":{"en":"A ratio table goes from 10 cm to 1 cm by dividing, then to 6 cm by multiplying.","es":"Una tabla de razones baja de 10 cm a 1 cm al dividir y luego sube a 6 cm al multiplicar."}},"check":{"q":{"en":"8 km ≈ 5 miles. About how many km is 1 mile?","es":"8 km ≈ 5 millas. ¿Aproximadamente cuántos km hay en 1 milla?"},"options":["40","0.625","1.6"],"correctIdx":2,"calc":{"expr":"8 ÷ 5","value":"1.6"},"feedback":[{"en":"40 multiplies 8 × 5. For 1 mile, divide the km by 5.","es":"40 viene de multiplicar 8 × 5. Para 1 milla, divide los km entre 5."},{"en":"0.625 is 5 ÷ 8, the miles in 1 km. Divide km by miles: 8 ÷ 5.","es":"0.625 es 5 ÷ 8, las millas que hay en 1 km. Divide los km entre las millas: 8 ÷ 5."},{"en":"Yes. 8 ÷ 5 = 1.6, so 1 mile ≈ 1.6 km.","es":"Sí. 8 ÷ 5 = 1.6, así que 1 milla ≈ 1.6 km."}]}}]},"3-8":{"skills":[{"name":{"en":"Find a unit rate by dividing","es":"Hallar una tasa unitaria al dividir"},"why":{"en":"Tonight you compare deals, and unit rates let you compare each one for just 1 item.","es":"Hoy comparas ofertas, y las tasas unitarias te dejan comparar cada una por 1 artículo."},"steps":[{"en":"Divide the total cost by the number of items.","es":"Divide el costo total entre el número de artículos."},{"en":"Write the answer with its unit, like $3 per pen.","es":"Escribe la respuesta con su unidad, como $3 por bolígrafo."},{"en":"Multiply the unit rate to find the cost of any amount.","es":"Multiplica la tasa unitaria para hallar el costo de cualquier cantidad."}],"example":{"en":"$12 for 4 tickets: 12 ÷ 4 = $3 per ticket. Then 7 tickets cost 7 × 3 = $21.","es":"$12 por 4 boletos: 12 ÷ 4 = $3 por boleto. Luego 7 boletos cuestan 7 × 3 = $21."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Tickets","es":"Boletos"},{"en":"Cost ($)","es":"Costo ($)"}],"rows":[[4,12],[1,3],[7,21]],"arrows":[{"from":0,"to":1,"label":"÷4"},{"from":1,"to":2,"label":"×7"}]},"alt":{"en":"A ratio table finds $3 for 1 ticket, then $21 for 7 tickets.","es":"Una tabla de razones halla $3 por 1 boleto y luego $21 por 7 boletos."}},"check":{"q":{"en":"6 notebooks cost $30. What is the cost per notebook?","es":"6 cuadernos cuestan $30. ¿Cuánto cuesta cada cuaderno?"},"options":["24","5","180"],"correctIdx":1,"calc":{"expr":"30 ÷ 6","value":"5"},"feedback":[{"en":"24 is 30 − 6. A unit rate divides: 30 ÷ 6.","es":"24 es la resta 30 − 6. Una tasa unitaria divide: 30 ÷ 6."},{"en":"Yes. 30 ÷ 6 = 5, so it is $5 per notebook.","es":"Sí. 30 ÷ 6 = 5, así que cada cuaderno cuesta $5."},{"en":"180 multiplies 30 × 6. To find the cost for 1, divide instead.","es":"180 viene de multiplicar 30 × 6. Para hallar el costo de 1, divide."}]}},{"name":{"en":"Compare decimals to find the lower price","es":"Comparar decimales para hallar el precio menor"},"why":{"en":"The better buy has the lower unit rate, and unit rates are often decimals.","es":"La mejor compra tiene la tasa unitaria menor, y las tasas unitarias muchas veces son decimales."},"steps":[{"en":"Line up the decimal points.","es":"Alinea los puntos decimales."},{"en":"Compare digits from left to right: ones, then tenths, then hundredths.","es":"Compara las cifras de izquierda a derecha: unidades, décimos y luego centésimos."},{"en":"The first place that is different decides which is less.","es":"El primer lugar donde las cifras cambian decide cuál es menor."}],"example":{"en":"$0.45 or $0.50 per ounce? The ones match. Tenths: 4 is less than 5, so $0.45 is lower.","es":"¿$0.45 o $0.50 por onza? Las unidades son iguales. Décimos: 4 es menor que 5, así que $0.45 es menor."},"model":{"kind":"barplot","data":{"categories":[{"label":{"en":"Store A","es":"Tienda A"},"value":0.45},{"label":{"en":"Store B","es":"Tienda B"},"value":0.5}],"unit":{"en":"dollars per ounce","es":"dólares por onza"}},"alt":{"en":"Two bars compare $0.45 and $0.50 per ounce; the shorter bar is the lower price.","es":"Dos barras comparan $0.45 y $0.50 por onza; la barra más corta es el precio menor."}},"check":{"q":{"en":"Which price per pound is the lowest?","es":"¿Qué precio por libra es el más bajo?"},"options":["2.40","2.04","2.14"],"correctIdx":1,"calc":{"expr":"2.04","value":"2.04"},"feedback":[{"en":"2.40 has 4 tenths. 2.04 has 0 tenths, so 2.04 is less.","es":"2.40 tiene 4 décimos. 2.04 tiene 0 décimos, así que 2.04 es menor."},{"en":"Yes. All have 2 ones, and 0 tenths is the fewest.","es":"Sí. Todos tienen 2 unidades, y 0 décimos es lo menor."},{"en":"2.14 has 1 tenth. 2.04 has 0 tenths, so 2.04 is lower.","es":"2.14 tiene 1 décimo. 2.04 tiene 0 décimos, así que 2.04 es más bajo."}]}}]},"3-9":{"skills":[{"name":{"en":"Make an equivalent fraction","es":"Formar una fracción equivalente"},"why":{"en":"Equivalent ratios work like equivalent fractions: multiply both numbers by the same value.","es":"Las razones equivalentes funcionan igual que las fracciones equivalentes: multiplica ambos números por el mismo valor."},"steps":[{"en":"Ask: what times the old denominator gives the new one?","es":"Pregúntate: ¿por cuánto multiplico el denominador para llegar al nuevo?"},{"en":"Multiply the numerator by that same number.","es":"Multiplica el numerador por ese mismo número."}],"example":{"en":"2/3 = ?/12. 3 × 4 = 12, so 2 × 4 = 8. That means 2/3 = 8/12.","es":"2/3 = ?/12. 3 × 4 = 12, así que 2 × 4 = 8. Entonces 2/3 = 8/12."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Numerator","es":"Numerador"},{"en":"Denominator","es":"Denominador"}],"rows":[[2,3],[8,12]],"arrows":[{"from":0,"to":1,"label":"×4"}]},"alt":{"en":"A table multiplies both 2 and 3 by 4 to get 8 and 12.","es":"Una tabla multiplica el 2 y el 3 por 4 para obtener 8 y 12."}},"check":{"q":{"en":"3/4 = ?/12. What is the missing number?","es":"3/4 = ?/12. ¿Cuál es el número que falta?"},"options":["11","9","3"],"correctIdx":1,"calc":{"expr":"3 × 3","value":"9"},"feedback":[{"en":"11 adds 8 to both. Multiply instead: 4 × 3 = 12, so 3 × 3.","es":"11 suma 8 a los dos. Mejor multiplica: 4 × 3 = 12, así que 3 × 3."},{"en":"Yes. 4 × 3 = 12, so 3 × 3 = 9.","es":"Sí. 4 × 3 = 12, así que 3 × 3 = 9."},{"en":"3 is the number you multiply by. Now multiply the numerator: 3 × 3.","es":"3 es el número por el que multiplicas. Ahora multiplica el numerador: 3 × 3."}]}},{"name":{"en":"Simplify by dividing both numbers","es":"Simplificar al dividir ambos números"},"why":{"en":"Tonight you check whether ratios are equivalent, often by scaling them down.","es":"Hoy compruebas si dos razones son equivalentes, muchas veces al reducirlas."},"steps":[{"en":"Find a number that divides both the numerator and denominator.","es":"Busca un número que divida al numerador y al denominador."},{"en":"Divide both by that number.","es":"Divide ambos entre ese número."},{"en":"Repeat until only 1 divides both.","es":"Repite hasta que solo el 1 divida a los dos."}],"example":{"en":"6/9: 3 divides both. 6 ÷ 3 = 2 and 9 ÷ 3 = 3, so 6/9 = 2/3.","es":"6/9: el 3 divide a ambos. 6 ÷ 3 = 2 y 9 ÷ 3 = 3, así que 6/9 = 2/3."},"model":{"kind":"fraction","data":{"parts":9,"shaded":6,"label":"6/9 = 2/3"},"alt":{"en":"A bar cut into 9 equal parts has 6 shaded, the same amount as 2/3.","es":"Una barra con 9 partes iguales tiene 6 sombreadas, igual cantidad que 2/3."}},"check":{"q":{"en":"Simplify 12/16.","es":"Simplifica 12/16."},"options":["8/12","4/3","3/4"],"correctIdx":2,"calc":{"expr":"12/16","value":"3/4"},"feedback":[{"en":"8/12 subtracts 4 from both. Divide both by 4 instead.","es":"8/12 resta 4 a los dos. Mejor divide ambos entre 4."},{"en":"4/3 is upside down. 12 ÷ 4 = 3 stays on top.","es":"4/3 está al revés. 12 ÷ 4 = 3 va arriba."},{"en":"Yes. Divide both by 4: 12/16 = 3/4.","es":"Sí. Divide ambos entre 4: 12/16 = 3/4."}]}}]},"4-1":{"skills":[{"name":{"en":"Percent means out of 100","es":"Porcentaje significa de cada 100"},"why":{"en":"Tonight you model percents on a 100-square grid, so each square is 1%.","es":"Hoy representas porcentajes en una cuadrícula de 100 cuadros, así que cada cuadro es 1%."},"steps":[{"en":"Count the parts out of 100.","es":"Cuenta las partes de cada 100."},{"en":"Write that number with a % sign.","es":"Escribe ese número con el signo %."},{"en":"100 out of 100 is 100%, the whole.","es":"100 de 100 es 100%: el total."}],"example":{"en":"35 of 100 squares are shaded, so 35/100 = 35% is shaded.","es":"Hay 35 de 100 cuadros sombreados, así que 35/100 = 35% está sombreado."},"model":{"kind":"grid","data":{"rows":10,"cols":10,"filled":35,"groupSize":10,"label":{"en":"35 out of 100 squares = 35%","es":"35 de 100 cuadros = 35%"}},"alt":{"en":"A 100-square grid with 35 squares shaded.","es":"Una cuadrícula de 100 cuadros con 35 sombreados."}},"check":{"q":{"en":"7 of 100 squares are shaded. What percent is shaded?","es":"7 de 100 cuadros están sombreados. ¿Qué porcentaje está sombreado?"},"options":["70%","0.7%","7%"],"correctIdx":2,"calc":{"expr":"7/100 × 100","value":"7"},"feedback":[{"en":"70% would be 70 squares. Only 7 of the 100 are shaded.","es":"70% serían 70 cuadros. Solo hay 7 de los 100 sombreados."},{"en":"0.7% is less than one square. Count: 7 squares out of 100 is 7%.","es":"0.7% es menos de un cuadro. Cuenta: 7 cuadros de 100 es 7%."},{"en":"Yes. 7 out of 100 is 7%.","es":"Sí. 7 de cada 100 es 7%."}]}},{"name":{"en":"Change a percent to a decimal","es":"Convertir un porcentaje en decimal"},"why":{"en":"Percents over 100% and under 1% make sense once you write them as decimals.","es":"Los porcentajes mayores que 100% y menores que 1% se entienden mejor escritos como decimales."},"steps":[{"en":"Divide the percent by 100.","es":"Divide el porcentaje entre 100."},{"en":"That moves the decimal point 2 places left.","es":"Eso mueve el punto decimal 2 lugares a la izquierda."},{"en":"1 is one whole, so 1.5 is one and a half wholes.","es":"1 equivale al total, así que 1.5 es una vez y media el total."}],"example":{"en":"150% = 1.5, more than one whole. 0.5% = 0.005, less than 1%.","es":"150% = 1.5, más que el total. 0.5% = 0.005, menos de 1%."},"model":{"kind":"numberline","data":{"min":0,"max":2,"step":0.25,"points":[{"value":1,"label":"100% = 1","kind":"given"},{"value":1.5,"label":"150% = 1.5","kind":"answer"}]},"alt":{"en":"A number line marks 100% at 1 and 150% at 1.5, past one whole.","es":"Una recta numérica marca 100% en 1 y 150% en 1.5, después del total."}},"check":{"q":{"en":"Write 250% as a decimal.","es":"Escribe 250% como decimal."},"options":["25","2.5","0.25"],"correctIdx":1,"calc":{"expr":"250 ÷ 100","value":"2.5"},"feedback":[{"en":"25 moves the point only 1 place. Move it 2 places left.","es":"25 mueve el punto solo 1 lugar. Muévelo 2 lugares a la izquierda."},{"en":"Yes. 250 ÷ 100 = 2.5, two and a half wholes.","es":"Sí. 250 ÷ 100 = 2.5, dos veces y media el total."},{"en":"0.25 is 25%. 250% is more than one whole, so it is above 1.","es":"0.25 es 25%. 250% es más que el total, así que es mayor que 1."}]}}]},"4-2":{"skills":[{"name":{"en":"Read tenths and hundredths","es":"Leer décimos y centésimos"},"why":{"en":"Tonight you write one amount as a fraction, decimal, and percent, and place value connects them.","es":"Hoy escribes una misma cantidad como fracción, decimal y porcentaje, y el valor posicional las conecta."},"steps":[{"en":"The first digit after the point is tenths.","es":"La primera cifra después del punto son los décimos."},{"en":"The second digit after the point is hundredths.","es":"La segunda cifra después del punto son los centésimos."},{"en":"0.35 reads as 35 hundredths, or 35/100.","es":"0.35 se lee 35 centésimos, o 35/100."}],"example":{"en":"0.4 is 4/10, which equals 40/100. And 0.07 is 7/100.","es":"0.4 es 4/10, que es igual a 40/100. Y 0.07 es 7/100."},"model":{"kind":"grid","data":{"rows":10,"cols":10,"filled":40,"groupSize":10,"label":"0.4 = 4/10 = 40/100"},"alt":{"en":"A 100-square grid with 4 full columns shaded, which is 40 squares.","es":"Una cuadrícula de 100 cuadros con 4 columnas completas sombreadas, o sea 40 cuadros."}},"check":{"q":{"en":"Write 3/10 as a decimal.","es":"Escribe 3/10 como decimal."},"options":["0.3","0.03","3.10"],"correctIdx":0,"calc":{"expr":"3/10","value":"0.3"},"feedback":[{"en":"Yes. 3 tenths goes in the first place after the point.","es":"Sí. 3 décimos va en el primer lugar después del punto."},{"en":"0.03 is 3 hundredths. Tenths go right after the point: 0.3.","es":"0.03 son 3 centésimos. Los décimos van justo después del punto: 0.3."},{"en":"3.10 just joins the numbers with a dot. 3/10 is less than 1: 0.3.","es":"3.10 solo junta los números con un punto. 3/10 es menor que 1: 0.3."}]}},{"name":{"en":"Write a fraction with denominator 100","es":"Escribir una fracción con denominador 100"},"why":{"en":"A fraction out of 100 turns straight into a percent: 40/100 = 40%.","es":"Una fracción con denominador 100 se convierte directo en porcentaje: 40/100 = 40%."},"steps":[{"en":"Ask: what times the denominator makes 100?","es":"Pregúntate: ¿por cuánto multiplico el denominador para llegar a 100?"},{"en":"Multiply the numerator and denominator by that number.","es":"Multiplica el numerador y el denominador por ese número."}],"example":{"en":"3/4: 4 × 25 = 100, so 3 × 25 = 75. 3/4 = 75/100 = 75%.","es":"3/4: 4 × 25 = 100, así que 3 × 25 = 75. Entonces 3/4 = 75/100 = 75%."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Part","es":"Parte"},{"en":"Total","es":"Total"}],"rows":[[3,4],[75,100]],"arrows":[{"from":0,"to":1,"label":"×25"}]},"alt":{"en":"A table multiplies 3 and 4 by 25 to get 75 out of 100.","es":"Una tabla multiplica el 3 y el 4 por 25 para llegar a 75 de 100."}},"check":{"q":{"en":"Write 2/5 as a fraction out of 100.","es":"Escribe 2/5 como fracción con denominador 100."},"options":["2/100","20/100","40/100"],"correctIdx":2,"calc":{"expr":"2/5","value":"40/100"},"feedback":[{"en":"2/100 changes only the denominator. Multiply the numerator by 20 too.","es":"2/100 cambia solo el denominador. Multiplica también el numerador por 20."},{"en":"20/100 multiplies the numerator by 10. 5 × 20 = 100, so use 20: 2 × 20.","es":"20/100 multiplica el numerador por 10. Como 5 × 20 = 100, usa 20: 2 × 20."},{"en":"Yes. 5 × 20 = 100, and 2 × 20 = 40.","es":"Sí. 5 × 20 = 100, y 2 × 20 = 40."}]}}]},"4-3":{"skills":[{"name":{"en":"Know the benchmark percents as fractions","es":"Conocer los porcentajes de referencia como fracciones"},"why":{"en":"Tonight's estimates start by swapping a percent for an easy fraction.","es":"Las estimaciones de hoy empiezan al cambiar un porcentaje por una fracción fácil."},"steps":[{"en":"Remember: 50% = 1/2, 25% = 1/4, 75% = 3/4, and 10% = 1/10.","es":"Recuerda: 50% = 1/2, 25% = 1/4, 75% = 3/4 y 10% = 1/10."},{"en":"To use one, divide the whole by the denominator.","es":"Para usarlo, divide el total entre el denominador."},{"en":"For 3/4, find 1/4, then multiply by 3.","es":"Para 3/4, halla 1/4 y luego multiplica por 3."}],"example":{"en":"25% of 80 is 1/4 of 80: 80 ÷ 4 = 20.","es":"25% de 80 es 1/4 de 80: 80 ÷ 4 = 20."},"model":{"kind":"tape","data":{"parts":4,"highlight":1,"partLabel":"25% = 20","wholeLabel":"100% = 80","blockLabel":"1/4","unknown":null},"alt":{"en":"A tape of 80 split into 4 equal blocks; one block, 25%, is 20.","es":"Una cinta de 80 dividida en 4 bloques iguales; un bloque, 25%, es 20."}},"check":{"q":{"en":"Which fraction equals 75%?","es":"¿Qué fracción es igual a 75%?"},"options":["1/4","3/4","7/5"],"correctIdx":1,"calc":{"expr":"75/100","value":"3/4"},"feedback":[{"en":"1/4 is 25%. 75% is three of those quarters.","es":"1/4 es 25%. 75% son tres de esos cuartos."},{"en":"Yes. 75/100 simplifies to 3/4.","es":"Sí. 75/100 se simplifica a 3/4."},{"en":"7/5 just uses the digits 7 and 5. Write 75/100, then simplify.","es":"7/5 solo usa las cifras 7 y 5. Escribe 75/100 y luego simplifica."}]}},{"name":{"en":"Round to a compatible number","es":"Redondear a un número compatible"},"why":{"en":"To estimate, you swap a hard whole for a nearby number that divides easily.","es":"Para estimar, cambias un total difícil por un número cercano que se divide fácilmente."},"steps":[{"en":"Look at the fraction's denominator.","es":"Mira el denominador de la fracción."},{"en":"Round the whole to a nearby number that the denominator divides evenly.","es":"Redondea el total a un número cercano que se divida exacto entre el denominador."},{"en":"Use ≈ to show the answer is an estimate.","es":"Usa ≈ para mostrar que la respuesta es una estimación."}],"example":{"en":"50% of 61: 61 is close to 60, and 60 ÷ 2 = 30. So about 30.","es":"50% de 61: 61 está cerca de 60, y 60 ÷ 2 = 30. Entonces es aproximadamente 30."},"model":{"kind":"doubleline","data":{"top":{"label":{"en":"Percent","es":"Porcentaje"},"ticks":["0%","50%","100%"]},"bottom":{"label":{"en":"Amount (61 rounded to 60)","es":"Cantidad (61 redondeado a 60)"},"ticks":["0","30","60"]}},"alt":{"en":"A double number line lines up 50% with 30 when 61 is rounded to 60.","es":"Una recta numérica doble alinea 50% con 30 al redondear 61 a 60."}},"check":{"q":{"en":"Estimate 25% of 39. Round 39 first.","es":"Estima 25% de 39. Primero redondea 39."},"options":["30","10","4"],"correctIdx":1,"calc":{"expr":"40 ÷ 4","value":"10"},"feedback":[{"en":"30 is 3/4 of 40. 25% is 1/4, so divide 40 by 4.","es":"30 es 3/4 de 40. 25% es 1/4, así que divide 40 entre 4."},{"en":"Yes. 39 ≈ 40, and 40 ÷ 4 = 10.","es":"Sí. 39 ≈ 40, y 40 ÷ 4 = 10."},{"en":"4 is 10% of 40. 25% is 1/4, so divide by 4.","es":"4 es 10% de 40. 25% es 1/4, así que divide entre 4."}]}}]},"4-4":{"skills":[{"name":{"en":"Find 10% by dividing by 10","es":"Hallar 10% al dividir entre 10"},"why":{"en":"Tonight you find percents of numbers, and 10% is the easiest building block.","es":"Hoy hallas porcentajes de números, y 10% es la pieza más fácil para empezar."},"steps":[{"en":"10% is 1/10, so divide the number by 10.","es":"10% es 1/10, así que divide el número entre 10."},{"en":"Build other percents from it: 30% is 3 × 10%.","es":"Forma otros porcentajes con él: 30% es 3 × 10%."}],"example":{"en":"10% of 80 is 80 ÷ 10 = 8. So 30% of 80 is 3 × 8 = 24.","es":"10% de 80 es 80 ÷ 10 = 8. Entonces 30% de 80 es 3 × 8 = 24."},"model":{"kind":"tape","data":{"parts":10,"highlight":3,"partLabel":"30% = 24","wholeLabel":"100% = 80","blockLabel":"10% = 8","unknown":null},"alt":{"en":"A tape of 80 in 10 blocks of 8; three blocks make 30%, which is 24.","es":"Una cinta de 80 en 10 bloques de 8; tres bloques forman 30%, que es 24."}},"check":{"q":{"en":"What is 10% of 250?","es":"¿Cuánto es 10% de 250?"},"options":["240","25","2.5"],"correctIdx":1,"calc":{"expr":"250 ÷ 10","value":"25"},"feedback":[{"en":"240 subtracts 10. 10% means divide by 10.","es":"240 resta 10. 10% significa dividir entre 10."},{"en":"Yes. 250 ÷ 10 = 25.","es":"Sí. 250 entre 10 es 25."},{"en":"2.5 divides by 100, which is 1%. For 10%, divide by 10.","es":"2.5 divide entre 100, y eso es 1%. Para 10%, divide entre 10."}]}},{"name":{"en":"Find a fraction of a number","es":"Hallar una fracción de un número"},"why":{"en":"A percent becomes an equivalent fraction, then you take that fraction of the number.","es":"Un porcentaje se vuelve una fracción equivalente, y luego hallas esa fracción del número."},"steps":[{"en":"Divide the number by the denominator.","es":"Divide el número entre el denominador."},{"en":"Multiply that result by the numerator.","es":"Multiplica ese resultado por el numerador."}],"example":{"en":"3/4 of 20: 20 ÷ 4 = 5, then 5 × 3 = 15.","es":"3/4 de 20: 20 ÷ 4 = 5, luego 5 × 3 = 15."},"model":{"kind":"tape","data":{"parts":4,"highlight":3,"partLabel":"3/4 = 15","wholeLabel":"20","blockLabel":"20 ÷ 4 = 5","unknown":null},"alt":{"en":"A tape of 20 in 4 blocks of 5; three blocks are 15.","es":"Una cinta de 20 en 4 bloques de 5; tres bloques suman 15."}},"check":{"q":{"en":"Find 2/5 of 30.","es":"Halla 2/5 de 30."},"options":["6","75","12"],"correctIdx":2,"calc":{"expr":"2/5 × 30","value":"12"},"feedback":[{"en":"6 is only 1/5 of 30. Multiply by 2 for 2/5.","es":"6 es solo 1/5 de 30. Multiplica por 2 para tener 2/5."},{"en":"75 divides by 2 and multiplies by 5. Divide by the denominator, 5, first.","es":"75 divide entre 2 y multiplica por 5. Primero divide entre el denominador, 5."},{"en":"Yes. 30 ÷ 5 = 6, and 6 × 2 = 12.","es":"Sí. 30 ÷ 5 = 6, y 6 × 2 = 12."}]}}]},"4-5":{"skills":[{"name":{"en":"Scale a ratio table down, then up","es":"Reducir y luego ampliar una tabla de razones"},"why":{"en":"Tonight you know a part and its percent, and a ratio table walks you up to 100%.","es":"Hoy conoces una parte y su porcentaje, y una tabla de razones te lleva hasta 100%."},"steps":[{"en":"Divide both numbers to reach an easy percent like 10%.","es":"Divide ambos números para llegar a un porcentaje fácil, como 10%."},{"en":"Multiply both numbers to reach 100%, the whole.","es":"Multiplica ambos números para llegar a 100%: el total."}],"example":{"en":"20% is 8. Divide both by 2: 10% is 4. Multiply by 10: 100% is 40.","es":"20% es 8. Divide ambos entre 2: 10% es 4. Multiplica por 10: 100% es 40."},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Percent","es":"Porcentaje"},{"en":"Amount","es":"Cantidad"}],"rows":[["20%",8],["10%",4],["100%",40]],"arrows":[{"from":0,"to":1,"label":"÷2"},{"from":1,"to":2,"label":"×10"}]},"alt":{"en":"A ratio table goes from 20% = 8 down to 10% = 4, then up to 100% = 40.","es":"Una tabla de razones baja de 20% = 8 a 10% = 4 y luego sube a 100% = 40."}},"check":{"q":{"en":"40% of a number is 12. What is 10% of it?","es":"40% de un número es 12. ¿Cuánto es 10% de ese número?"},"options":["48","4.8","3"],"correctIdx":2,"calc":{"expr":"12 ÷ 4","value":"3"},"feedback":[{"en":"48 multiplies by 4. Going from 40% down to 10% means divide by 4.","es":"48 multiplica por 4. Bajar de 40% a 10% significa dividir entre 4."},{"en":"4.8 is 40% of 12. Here 12 is already the 40% part, so divide it by 4.","es":"4.8 es 40% de 12. Aquí 12 ya es la parte de 40%, así que divídela entre 4."},{"en":"Yes. 40% ÷ 4 = 10%, and 12 ÷ 4 = 3.","es":"Sí. 40% ÷ 4 = 10%, y 12 ÷ 4 = 3."}]}},{"name":{"en":"Undo multiplying with division","es":"Deshacer una multiplicación con una división"},"why":{"en":"To find the whole with an equation, you use the inverse operation of multiplying.","es":"Para hallar el total con una ecuación, usas la operación inversa de multiplicar."},"steps":[{"en":"In ? × 5 = 35, the missing number was multiplied by 5.","es":"En ? × 5 = 35, el número que falta se multiplicó por 5."},{"en":"Divide to undo it: 35 ÷ 5 = 7.","es":"Divide para deshacerlo: 35 ÷ 5 = 7."},{"en":"Check by multiplying: 7 × 5 = 35.","es":"Comprueba al multiplicar: 7 × 5 = 35."}],"example":{"en":"? × 0.25 = 6. Undo it: 6 ÷ 0.25 = 24. Check: 24 × 0.25 = 6.","es":"? × 0.25 = 6. Deshazlo: 6 ÷ 0.25 = 24. Comprueba: 24 × 0.25 = 6."},"model":{"kind":"tape","data":{"parts":4,"highlight":1,"partLabel":{"en":"0.25 of the number = 6","es":"0.25 del número = 6"},"wholeLabel":"6 ÷ 0.25 = 24","unknown":null},"alt":{"en":"A tape in 4 blocks: one block is 6, and dividing 6 by 0.25 gives the whole, 24.","es":"Una cinta de 4 bloques: un bloque es 6, y 6 ÷ 0.25 da el total, 24."}},"check":{"q":{"en":"Find the missing number: ? × 4 = 52.","es":"Halla el número que falta: ? × 4 = 52."},"options":["13","208","48"],"correctIdx":0,"calc":{"expr":"52 ÷ 4","value":"13"},"feedback":[{"en":"Yes. 52 ÷ 4 = 13, and 13 × 4 = 52.","es":"Sí. 52 ÷ 4 = 13, y 13 × 4 = 52."},{"en":"208 multiplies again. Undo times 4 by dividing: 52 ÷ 4.","es":"208 vuelve a multiplicar. Deshaz el × 4 al dividir: 52 ÷ 4."},{"en":"48 subtracts 4. Subtracting undoes adding, not multiplying. Divide instead.","es":"48 resta 4. La resta deshace la suma, no la multiplicación. Mejor divide."}]}}]},"5-1":{"skills":[{"name":{"en":"Area of a rectangle: length × width","es":"Área de un rectángulo: largo × ancho"},"why":{"en":"A parallelogram can be cut and moved into a rectangle, so its area works the same way.","es":"Un paralelogramo se puede cortar y reacomodar en un rectángulo, así que su área se halla igual."},"steps":[{"en":"Multiply the length by the width.","es":"Multiplica el largo por el ancho."},{"en":"Write the answer in square units.","es":"Escribe la respuesta en unidades cuadradas."}],"example":{"en":"A rectangle 6 units by 4 units: 6 × 4 = 24 square units.","es":"Un rectángulo de 6 por 4 unidades: 6 × 4 = 24 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":6,"height":4},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A rectangle 6 units long and 4 units tall.","es":"Un rectángulo de 6 unidades de largo y 4 de alto."}},"check":{"q":{"en":"What is the area of a rectangle 9 cm long and 7 cm wide?","es":"¿Cuál es el área de un rectángulo de 9 cm de largo y 7 cm de ancho?"},"options":["16","63","32"],"correctIdx":1,"calc":{"expr":"9 × 7","value":"63"},"feedback":[{"en":"16 adds 9 + 7. Area multiplies: 9 × 7.","es":"16 suma 9 + 7. El área multiplica: 9 × 7."},{"en":"Yes. 9 × 7 = 63 square centimeters.","es":"Sí. 9 × 7 = 63 centímetros cuadrados."},{"en":"32 is the perimeter, the distance around. Area multiplies 9 × 7.","es":"32 es el perímetro, la distancia alrededor. El área multiplica 9 × 7."}]}},{"name":{"en":"Find the height: straight up, not slanted","es":"Hallar la altura: recta, no inclinada"},"why":{"en":"Tonight's formula is base × height, and the height is easy to mix up with the slanted side.","es":"La fórmula de hoy es base × altura, y es fácil confundir la altura con el lado inclinado."},"steps":[{"en":"The base is the side the shape sits on.","es":"La base es el lado sobre el que se apoya la figura."},{"en":"The height goes straight up from the base, making a square corner.","es":"La altura sube en línea recta desde la base y forma una esquina cuadrada."},{"en":"A slanted side is not the height.","es":"El lado inclinado no es la altura."}],"example":{"en":"A parallelogram with base 8, slanted side 5, and height 4 uses 8 and 4.","es":"Un paralelogramo con base 8, lado inclinado 5 y altura 4 usa el 8 y el 4."},"model":{"kind":"area","data":{"shape":"parallelogram","dims":{"base":8,"height":4,"slant":5},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A parallelogram with base 8, a dashed height of 4, and a slanted side of 5.","es":"Un paralelogramo con base 8, una altura punteada de 4 y un lado inclinado de 5."}},"check":{"q":{"en":"Base 10, slanted side 7, and a dashed line 6 that meets the base at a square corner. Which is the height?","es":"Base 10, lado inclinado 7 y una línea punteada de 6 que forma una esquina cuadrada con la base. ¿Cuál es la altura?"},"options":["10","7","6"],"correctIdx":2,"calc":{"expr":"6","value":"6"},"feedback":[{"en":"10 is the base. The height stands straight up from it.","es":"10 es la base. La altura sube en línea recta desde ella."},{"en":"7 is the slanted side. It leans, so it is not the height.","es":"7 es el lado inclinado. Se inclina, así que no es la altura."},{"en":"Yes. The dashed line makes a square corner with the base.","es":"Sí. La línea punteada forma una esquina cuadrada con la base."}]}}]},"5-10":{"skills":[{"name":{"en":"Find volume by multiplying three edges","es":"Hallar el volumen multiplicando tres aristas"},"why":{"en":"Tonight's boxes use the same rule, length × width × height, even when an edge is a fraction or decimal.","es":"Las cajas de hoy usan la misma regla, largo × ancho × alto, aunque una arista sea fracción o decimal."},"steps":[{"en":"Find the length, the width, and the height.","es":"Encuentra el largo, el ancho y el alto."},{"en":"Multiply two of them, then multiply by the third.","es":"Multiplica dos de ellos y luego multiplica por el tercero."},{"en":"Write the answer in cubic units.","es":"Escribe la respuesta en unidades cúbicas."}],"example":{"en":"A box 4 by 3 by 2: 4 × 3 = 12, then 12 × 2 = 24 cubic units.","es":"Una caja de 4 por 3 por 2: 4 × 3 = 12, luego 12 × 2 = 24 unidades cúbicas."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":4,"height":3}},"alt":{"en":"The base of the box: a rectangle 4 long and 3 wide, so its base area is 12. The box is 2 tall.","es":"La base de la caja: un rectángulo de 4 de largo y 3 de ancho, con área de 12. La caja mide 2 de alto."}},"check":{"q":{"en":"A box is 5 cm long, 2 cm wide, and 3 cm tall. What is its volume in cubic cm?","es":"Una caja mide 5 cm de largo, 2 cm de ancho y 3 cm de alto. ¿Cuál es su volumen en cm cúbicos?"},"options":["10","15","30"],"correctIdx":2,"calc":{"expr":"5 × 2 × 3","value":"30"},"feedback":[{"en":"10 comes from adding 5 + 2 + 3. Volume multiplies the edges instead.","es":"10 sale de sumar 5 + 2 + 3. El volumen multiplica las aristas."},{"en":"15 uses only two edges, 5 × 3. Multiply by the width, 2, too.","es":"15 usa solo dos aristas, 5 × 3. Multiplica también por el ancho, 2."},{"en":"Yes. 5 × 2 = 10, and 10 × 3 = 30 cubic cm.","es":"Sí. 5 × 2 = 10, y 10 × 3 = 30 cm cúbicos."}]}},{"name":{"en":"Multiply a whole number by a decimal","es":"Multiplicar un número entero por un decimal"},"why":{"en":"One edge tonight may be a decimal like 1.5, so you multiply it like any other edge.","es":"Hoy una arista puede ser un decimal como 1.5, y la multiplicas igual que las demás."},"steps":[{"en":"Multiply as if the decimal point were not there.","es":"Multiplica como si no hubiera punto decimal."},{"en":"Count the digits after the point in the decimal.","es":"Cuenta las cifras que hay después del punto en el decimal."},{"en":"Put the point back so the answer has that many decimal digits.","es":"Vuelve a poner el punto para que la respuesta tenga esa cantidad de cifras decimales."}],"example":{"en":"2 × 1.5: 2 × 15 = 30. One digit after the point, so 3.0, which is 3.","es":"2 × 1.5: 2 × 15 = 30. Hay una cifra después del punto, así que 3.0, o sea 3."},"model":{"kind":"numberline","data":{"min":0,"max":3,"step":0.5,"points":[{"value":1.5,"label":"1.5","kind":"given"},{"value":3,"label":"2 × 1.5 = 3","kind":"answer"}]},"alt":{"en":"A number line from 0 to 3. Two jumps of 1.5 land on 3.","es":"Una recta numérica de 0 a 3. Dos saltos de 1.5 llegan a 3."}},"check":{"q":{"en":"What is 4 × 2.5?","es":"¿Cuánto es 4 × 2.5?"},"options":["6.5","10","100"],"correctIdx":1,"calc":{"expr":"4 × 2.5","value":"10"},"feedback":[{"en":"6.5 adds 4 + 2.5. The × sign means multiply: four groups of 2.5.","es":"6.5 es la suma 4 + 2.5. El signo × pide multiplicar: cuatro grupos de 2.5."},{"en":"Yes. 4 × 25 = 100, then one decimal digit gives 10.0, which is 10.","es":"Sí. 4 × 25 = 100; con una cifra decimal queda 10.0, o sea 10."},{"en":"100 forgot the decimal point. 2.5 has one digit after the point, so the answer is 10.","es":"100 olvida el punto decimal. 2.5 tiene una cifra después del punto, así que la respuesta es 10."}]}}]},"5-2":{"skills":[{"name":{"en":"Area of a parallelogram: base × height","es":"Área de un paralelogramo: base × altura"},"why":{"en":"Two equal triangles make a parallelogram, so a triangle's area is half of base × height.","es":"Dos triángulos iguales forman un paralelogramo, así que el área de un triángulo es la mitad de base × altura."},"steps":[{"en":"Find the base and the straight-up height.","es":"Halla la base y la altura en línea recta."},{"en":"Multiply them. Skip the slanted side.","es":"Multiplícalas. No uses el lado inclinado."}],"example":{"en":"Base 6, height 4, slanted side 5: area = 6 × 4 = 24 square units.","es":"Base 6, altura 4, lado inclinado 5: área = 6 × 4 = 24 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"parallelogram","dims":{"base":6,"height":4,"slant":5},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A parallelogram with base 6, height 4, and slanted side 5.","es":"Un paralelogramo con base 6, altura 4 y lado inclinado 5."}},"check":{"q":{"en":"A parallelogram has base 12, height 5, and slanted side 6. What is its area?","es":"Un paralelogramo tiene base 12, altura 5 y lado inclinado 6. ¿Cuál es su área?"},"options":["60","72","30"],"correctIdx":0,"calc":{"expr":"12 × 5","value":"60"},"feedback":[{"en":"Yes. 12 × 5 = 60 square units.","es":"Sí. 12 × 5 = 60 unidades cuadradas."},{"en":"72 uses the slanted side, 6. Use the straight-up height, 5.","es":"72 usa el lado inclinado, 6. Usa la altura en línea recta, 5."},{"en":"30 takes half. A parallelogram is the full shape, so do not halve it.","es":"30 toma la mitad. El paralelogramo es la figura completa, así que no la divides entre 2."}]}},{"name":{"en":"Take half of a number","es":"Sacar la mitad de un número"},"why":{"en":"Every triangle area ends with a half: 1/2 × base × height.","es":"Toda área de triángulo termina con una mitad: 1/2 × base × altura."},"steps":[{"en":"Half means multiply by 1/2 or divide by 2.","es":"La mitad es multiplicar por 1/2 o dividir entre 2."},{"en":"For an odd number, the half ends in .5.","es":"Si el número es impar, la mitad termina en .5."}],"example":{"en":"Half of 24 is 12. Half of 15 is 7.5.","es":"La mitad de 24 es 12. La mitad de 15 es 7.5."},"model":{"kind":"tape","data":{"parts":2,"highlight":1,"partLabel":{"en":"half = 12","es":"mitad = 12"},"wholeLabel":"24","unknown":null},"alt":{"en":"A tape of 24 cut into 2 equal halves; one half is 12.","es":"Una cinta de 24 cortada en 2 mitades iguales; una mitad es 12."}},"check":{"q":{"en":"What is 1/2 × 27?","es":"¿Cuánto es 1/2 × 27?"},"options":["13","54","13.5"],"correctIdx":2,"calc":{"expr":"1/2 × 27","value":"13.5"},"feedback":[{"en":"13 drops the leftover half. 27 is odd, so the half ends in .5.","es":"13 deja fuera la mitad que sobra. 27 es impar, así que la mitad termina en .5."},{"en":"54 doubles 27. Half means divide by 2.","es":"54 es el doble de 27. La mitad es dividir entre 2."},{"en":"Yes. Half of 26 is 13, plus half of 1, so 13.5.","es":"Sí. La mitad de 26 es 13, más la mitad de 1: 13.5."}]}}]},"5-3":{"skills":[{"name":{"en":"Do the parentheses first","es":"Resolver primero los paréntesis"},"why":{"en":"The trapezoid formula adds the two bases inside parentheses before multiplying by the height.","es":"La fórmula del trapecio suma las dos bases dentro de los paréntesis antes de multiplicar por la altura."},"steps":[{"en":"Work inside the parentheses first.","es":"Primero resuelve lo que está dentro de los paréntesis."},{"en":"Then multiply the result.","es":"Luego multiplica el resultado."}],"example":{"en":"(6 + 4) × 3: first 6 + 4 = 10, then 10 × 3 = 30.","es":"(6 + 4) × 3: primero 6 + 4 = 10, luego 10 × 3 = 30."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"(6 + 4) × 3"},{"rule":"P","expr":"10 × 3"},{"rule":"MD","expr":"30"}]},"alt":{"en":"Steps for (6 + 4) × 3: parentheses first give 10, then 10 × 3 = 30.","es":"Pasos de (6 + 4) × 3: primero los paréntesis dan 10, luego 10 × 3 = 30."}},"check":{"q":{"en":"What is (5 + 7) × 4?","es":"¿Cuánto es (5 + 7) × 4?"},"options":["33","48","16"],"correctIdx":1,"calc":{"expr":"(5 + 7) × 4","value":"48"},"feedback":[{"en":"33 multiplies 7 × 4 first. Add inside the parentheses first: 5 + 7 = 12.","es":"33 multiplica 7 × 4 primero. Suma primero dentro de los paréntesis: 5 + 7 = 12."},{"en":"Yes. 5 + 7 = 12, then 12 × 4 = 48.","es":"Sí. 5 + 7 = 12, luego 12 × 4 = 48."},{"en":"16 adds all three numbers. After 5 + 7 = 12, multiply by 4.","es":"16 suma los tres números. Después de 5 + 7 = 12, multiplica por 4."}]}},{"name":{"en":"Area of a triangle: half of base × height","es":"Área de un triángulo: la mitad de base × altura"},"why":{"en":"A trapezoid splits into two triangles, and its formula also takes half.","es":"Un trapecio se divide en dos triángulos, y su fórmula también toma la mitad."},"steps":[{"en":"Multiply the base by the straight-up height.","es":"Multiplica la base por la altura en línea recta."},{"en":"Take half of that product.","es":"Toma la mitad de ese producto."}],"example":{"en":"Base 6, height 4: 6 × 4 = 24, and half of 24 is 12 square units.","es":"Base 6, altura 4: 6 × 4 = 24, y la mitad de 24 es 12 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"triangle","dims":{"base":6,"height":4},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A triangle with base 6 and height 4.","es":"Un triángulo de base 6 y altura 4."}},"check":{"q":{"en":"A triangle has base 10 and height 7. What is its area?","es":"Un triángulo tiene base 10 y altura 7. ¿Cuál es su área?"},"options":["70","17","35"],"correctIdx":2,"calc":{"expr":"1/2 × 10 × 7","value":"35"},"feedback":[{"en":"70 is base × height. A triangle is half of that.","es":"70 es base × altura. Un triángulo es la mitad de eso."},{"en":"17 adds 10 + 7. Multiply them, then take half.","es":"17 suma 10 + 7. Multiplícalos y luego toma la mitad."},{"en":"Yes. 10 × 7 = 70, and half is 35 square units.","es":"Sí. 10 × 7 = 70, y la mitad es 35 unidades cuadradas."}]}}]},"5-4":{"skills":[{"name":{"en":"Find a missing side length","es":"Hallar la longitud de un lado que falta"},"why":{"en":"When you decompose a composite figure, some piece lengths are not labeled and must be found.","es":"Al descomponer una figura compuesta, algunas longitudes no están marcadas y hay que hallarlas."},"steps":[{"en":"Find a full side that the pieces share.","es":"Busca un lado completo que comparten las piezas."},{"en":"Subtract the known part from the full length.","es":"Resta la parte conocida de la longitud completa."}],"example":{"en":"The bottom side is 10 m. The top side above it is 4 m. The missing piece is 10 − 4 = 6 m.","es":"El lado de abajo mide 10 m. El de arriba mide 4 m. El tramo que falta mide 10 − 4 = 6 m."},"model":{"kind":"tape","data":{"parts":10,"highlight":4,"partLabel":"4 m","wholeLabel":{"en":"full side = 10 m","es":"lado completo = 10 m"},"blockLabel":"1 m","unknown":null},"alt":{"en":"A 10 m side in 1 m blocks; 4 m is the top part and the rest is the missing piece.","es":"Un lado de 10 m en bloques de 1 m; 4 m es la parte de arriba y el resto es el tramo que falta."}},"check":{"q":{"en":"A full side is 15 m. One part is 9 m. How long is the other part?","es":"Un lado completo mide 15 m. Una parte mide 9 m. ¿Cuánto mide la otra parte?"},"options":["24","6","135"],"correctIdx":1,"calc":{"expr":"15 − 9","value":"6"},"feedback":[{"en":"24 adds the lengths. The part is shorter than the full side, so subtract.","es":"24 suma las longitudes. La parte es más corta que el lado completo, así que resta."},{"en":"Yes. 15 − 9 = 6 m.","es":"Sí. 15 − 9 = 6 metros."},{"en":"135 multiplies. To find the leftover part, subtract: 15 − 9.","es":"135 multiplica. Para hallar la parte que queda, resta: 15 − 9."}]}},{"name":{"en":"Add or subtract areas","es":"Sumar o restar áreas"},"why":{"en":"A composite figure's area is its pieces added, or a big shape minus a cut-out.","es":"El área de una figura compuesta es la suma de sus piezas, o una figura grande menos un recorte."},"steps":[{"en":"Find the area of each simple shape.","es":"Halla el área de cada figura sencilla."},{"en":"Add pieces that are joined together.","es":"Suma las piezas que están unidas."},{"en":"Subtract a piece that is cut out.","es":"Resta una pieza que está recortada."}],"example":{"en":"A 10 × 8 rectangle with a 3 × 2 hole: 80 − 6 = 74 square units.","es":"Un rectángulo de 10 × 8 con un hueco de 3 × 2: 80 − 6 = 74 unidades cuadradas."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"10 × 8 − 3 × 2"},{"rule":"MD","expr":"80 − 6"},{"rule":"AS","expr":"74"}]},"alt":{"en":"Steps: find both areas, 80 and 6, then subtract the hole to get 74.","es":"Pasos: halla las dos áreas, 80 y 6, y luego resta el hueco para obtener 74."}},"check":{"q":{"en":"A 9 by 6 rectangle has a 2 by 2 square cut out. What area is left?","es":"A un rectángulo de 9 por 6 le recortan un cuadrado de 2 por 2. ¿Qué área queda?"},"options":["58","52","50"],"correctIdx":2,"calc":{"expr":"9 × 6 − 2 × 2","value":"50"},"feedback":[{"en":"58 adds the square. It is cut out, so subtract: 54 − 4.","es":"58 suma el cuadrado. Está recortado, así que resta: 54 − 4."},{"en":"52 subtracts the side, 2. Subtract the square's area: 2 × 2 = 4.","es":"52 resta el lado, 2. Resta el área del cuadrado: 2 × 2 = 4."},{"en":"Yes. 9 × 6 = 54, and 54 − 4 = 50.","es":"Sí. 9 × 6 = 54, y 54 − 4 = 50."}]}}]},"5-5":{"skills":[{"name":{"en":"Multiply three numbers, two at a time","es":"Multiplicar tres números de dos en dos"},"why":{"en":"Tonight's volume is length × width × height, three numbers multiplied together.","es":"El volumen de hoy es largo × ancho × altura: tres números multiplicados."},"steps":[{"en":"Multiply any two of the numbers.","es":"Multiplica dos de los números."},{"en":"Multiply that answer by the third number.","es":"Multiplica ese resultado por el tercer número."},{"en":"Any order gives the same answer.","es":"Cualquier orden da el mismo resultado."}],"example":{"en":"2 × 3 × 4: first 2 × 3 = 6, then 6 × 4 = 24.","es":"2 × 3 × 4: primero 2 × 3 = 6, luego 6 × 4 = 24."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"2 × 3 × 4"},{"rule":"MD","expr":"6 × 4"},{"rule":"MD","expr":"24"}]},"alt":{"en":"Steps: 2 × 3 = 6 first, then 6 × 4 = 24.","es":"Pasos: primero 2 × 3 = 6, luego 6 × 4 = 24."}},"check":{"q":{"en":"What is 3 × 4 × 5?","es":"¿Cuánto es 3 × 4 × 5?"},"options":["60","12","20"],"correctIdx":0,"calc":{"expr":"3 × 4 × 5","value":"60"},"feedback":[{"en":"Yes. 3 × 4 = 12, and 12 × 5 = 60.","es":"Sí. 3 × 4 = 12, y 12 × 5 = 60."},{"en":"12 adds 3 + 4 + 5, or stops at 3 × 4. Multiply all three.","es":"12 suma 3 + 4 + 5, o se queda en 3 × 4. Multiplica los tres."},{"en":"20 is only 4 × 5. Multiply that by 3 too.","es":"20 es solo 4 × 5. Multiplícalo también por 3."}]}},{"name":{"en":"Count unit cubes by layers","es":"Contar cubos unitarios por capas"},"why":{"en":"Volume counts the unit cubes that fill a box, one layer at a time.","es":"El volumen cuenta los cubos unitarios que llenan una caja, capa por capa."},"steps":[{"en":"Count one layer: rows × cubes in each row.","es":"Cuenta una capa: filas × cubos en cada fila."},{"en":"Multiply by the number of layers.","es":"Multiplica por el número de capas."},{"en":"Write the answer in cubic units.","es":"Escribe la respuesta en unidades cúbicas."}],"example":{"en":"A layer of 4 rows of 3 cubes has 12. Two layers hold 24 cubic units.","es":"Una capa de 4 filas de 3 cubos tiene 12. Dos capas tienen 24 unidades cúbicas."},"model":{"kind":"grid","data":{"rows":4,"cols":3,"filled":12,"groupSize":5,"label":{"en":"1 layer = 12 cubes; 2 layers = 24","es":"1 capa = 12 cubos; 2 capas = 24"}},"alt":{"en":"One layer of cubes: 4 rows of 3, which is 12 cubes.","es":"Una capa de cubos: 4 filas de 3, o sea 12 cubos."}},"check":{"q":{"en":"One layer has 5 rows of 2 cubes. There are 3 layers. How many cubes?","es":"Una capa tiene 5 filas de 2 cubos. Hay 3 capas. ¿Cuántos cubos hay?"},"options":["10","15","30"],"correctIdx":2,"calc":{"expr":"5 × 2 × 3","value":"30"},"feedback":[{"en":"10 is just one layer. Multiply by the 3 layers.","es":"10 es solo una capa. Multiplica por las 3 capas."},{"en":"15 is 5 × 3 and skips the 2 cubes in each row. Multiply by 2 too.","es":"15 es 5 × 3 y no cuenta los 2 cubos de cada fila. Multiplica también por 2."},{"en":"Yes. 5 × 2 = 10 per layer, and 10 × 3 = 30.","es":"Sí. 5 × 2 = 10 por capa, y 10 × 3 = 30."}]}}]},"5-6":{"skills":[{"name":{"en":"Find the area of each face","es":"Hallar el área de cada cara"},"why":{"en":"Every face of a net is a flat shape, and surface area needs each one's area.","es":"Cada cara de una plantilla es una figura plana, y el área de superficie necesita el área de cada una."},"steps":[{"en":"For a rectangle face, multiply length × width.","es":"Para una cara rectangular, multiplica largo × ancho."},{"en":"For a triangle face, take half of base × height.","es":"Para una cara triangular, toma la mitad de base × altura."},{"en":"Label the area in square units.","es":"Escribe el área en unidades cuadradas."}],"example":{"en":"A 5 by 2 rectangle face has area 5 × 2 = 10 square units.","es":"Una cara rectangular de 5 por 2 tiene un área de 5 × 2 = 10 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":5,"height":2},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A rectangle face 5 units by 2 units.","es":"Una cara rectangular de 5 por 2 unidades."}},"check":{"q":{"en":"A face is a rectangle 7 cm by 4 cm. What is its area?","es":"Una cara es un rectángulo de 7 cm por 4 cm. ¿Cuál es su área?"},"options":["22","11","28"],"correctIdx":2,"calc":{"expr":"7 × 4","value":"28"},"feedback":[{"en":"22 is the perimeter, the distance around. Area multiplies: 7 × 4.","es":"22 es el perímetro, la distancia alrededor. El área multiplica: 7 × 4."},{"en":"11 adds 7 + 4. Area multiplies the sides.","es":"11 suma 7 + 4. El área multiplica los lados."},{"en":"Yes. 7 × 4 = 28 square centimeters.","es":"Sí. 7 × 4 = 28 centímetros cuadrados."}]}},{"name":{"en":"Add many areas without missing one","es":"Sumar muchas áreas sin olvidar ninguna"},"why":{"en":"Surface area is every face of the net added together.","es":"El área de superficie es la suma de todas las caras de la plantilla."},"steps":[{"en":"List each face's area, one number per face.","es":"Haz una lista con el área de cada cara, un número por cara."},{"en":"Cross off each area as you add it.","es":"Tacha cada área cuando la sumes."},{"en":"A box has 6 faces, so check for 6 numbers.","es":"Una caja tiene 6 caras, así que revisa que haya 6 números."}],"example":{"en":"Faces 10, 10, 6, 6, 15, 15: the total is 62 square units.","es":"Caras de 10, 10, 6, 6, 15 y 15: en total suman 62 unidades cuadradas."},"model":{"kind":"barplot","data":{"categories":[{"label":{"en":"Front","es":"Frente"},"value":10},{"label":{"en":"Back","es":"Atrás"},"value":10},{"label":{"en":"Top","es":"Arriba"},"value":6},{"label":{"en":"Bottom","es":"Abajo"},"value":6},{"label":{"en":"Left","es":"Izquierda"},"value":15},{"label":{"en":"Right","es":"Derecha"},"value":15}],"unit":{"en":"square units","es":"unidades cuadradas"}},"alt":{"en":"One bar per face of the box: 10, 10, 6, 6, 15, and 15.","es":"Una barra por cada cara de la caja: 10, 10, 6, 6, 15 y 15."}},"check":{"q":{"en":"A box's faces are 12, 12, 8, 8, 6, and 6. What is the total?","es":"Las caras de una caja miden 12, 12, 8, 8, 6 y 6. ¿Cuánto suman en total?"},"options":["26","52","40"],"correctIdx":1,"calc":{"expr":"12 + 12 + 8 + 8 + 6 + 6","value":"52"},"feedback":[{"en":"26 adds only 12, 8, and 6. Each face has a match, so add all 6.","es":"26 suma solo 12, 8 y 6. Cada cara tiene una pareja, así que suma las 6."},{"en":"Yes. 24 + 16 + 12 = 52 square units.","es":"Sí. 24 + 16 + 12 = 52 unidades cuadradas."},{"en":"40 leaves out the two 6s. Check that you added all 6 faces.","es":"40 deja fuera los dos 6. Revisa que sumaste las 6 caras."}]}}]},"5-7":{"skills":[{"name":{"en":"Area of a triangle face","es":"Área de una cara triangular"},"why":{"en":"A triangular prism has two triangle faces, and you need each one's area.","es":"Un prisma triangular tiene dos caras triangulares, y necesitas el área de cada una."},"steps":[{"en":"Multiply the triangle's base by its height.","es":"Multiplica la base del triángulo por su altura."},{"en":"Take half of that product.","es":"Toma la mitad de ese producto."}],"example":{"en":"Base 8, height 3: 8 × 3 = 24, and half is 12 square units.","es":"Base 8, altura 3: 8 × 3 = 24, y la mitad es 12 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"triangle","dims":{"base":8,"height":3},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A triangle face with base 8 and height 3.","es":"Una cara triangular de base 8 y altura 3."}},"check":{"q":{"en":"A triangle face has base 6 cm and height 4 cm. What is its area?","es":"Una cara triangular tiene base de 6 cm y altura de 4 cm. ¿Cuál es su área?"},"options":["24","12","10"],"correctIdx":1,"calc":{"expr":"1/2 × 6 × 4","value":"12"},"feedback":[{"en":"24 is base × height. A triangle is half of that.","es":"24 es base × altura. Un triángulo es la mitad de eso."},{"en":"Yes. 6 × 4 = 24, and half is 12 square centimeters.","es":"Sí. 6 × 4 = 24, y la mitad es 12 centímetros cuadrados."},{"en":"10 adds 6 + 4. Multiply, then take half.","es":"10 suma 6 + 4. Multiplica y luego toma la mitad."}]}},{"name":{"en":"Double a matching face","es":"Duplicar una cara que tiene pareja"},"why":{"en":"A rectangular prism has 3 pairs of matching faces, so you find one and double it.","es":"Un prisma rectangular tiene 3 pares de caras congruentes, así que hallas una y la duplicas."},"steps":[{"en":"Opposite faces match: top and bottom, front and back, left and right.","es":"Las caras opuestas son iguales: arriba y abajo, frente y atrás, izquierda y derecha."},{"en":"Find one face's area, then multiply by 2.","es":"Halla el área de una cara y multiplícala por 2."}],"example":{"en":"The front is 4 × 3 = 12. Front and back together: 2 × 12 = 24 square units.","es":"El frente mide 4 × 3 = 12. Frente y atrás juntos: 2 × 12 = 24 unidades cuadradas."},"model":{"kind":"tape","data":{"parts":2,"highlight":1,"partLabel":{"en":"front = 4 × 3 = 12","es":"frente = 4 × 3 = 12"},"wholeLabel":{"en":"front + back = 24","es":"frente + atrás = 24"},"unknown":null},"alt":{"en":"Two equal blocks, front and back, each 12, together 24.","es":"Dos bloques iguales, frente y atrás, de 12 cada uno, juntos suman 24."}},"check":{"q":{"en":"A box's front face is 5 by 3. What is the area of the front and back together?","es":"La cara de frente de una caja mide 5 por 3. ¿Cuánto suman las áreas del frente y de atrás?"},"options":["30","15","16"],"correctIdx":0,"calc":{"expr":"2 × 5 × 3","value":"30"},"feedback":[{"en":"Yes. 5 × 3 = 15, and two matching faces make 30.","es":"Sí. 5 × 3 = 15, y dos caras iguales dan 30."},{"en":"15 is only the front. The back matches it, so double it.","es":"15 es solo el frente. La cara de atrás es igual, así que duplícala."},{"en":"16 is the perimeter of the front. Multiply 5 × 3, then double.","es":"16 es el perímetro del frente. Multiplica 5 × 3 y luego duplica."}]}}]},"5-8":{"skills":[{"name":{"en":"Area of a square: side × side","es":"Área de un cuadrado: lado × lado"},"why":{"en":"A square pyramid's base is a square, so the base area is side × side.","es":"La base de una pirámide cuadrada es un cuadrado, así que su área es lado × lado."},"steps":[{"en":"Multiply the side length by itself.","es":"Multiplica la longitud del lado por sí misma."},{"en":"Side × 4 is the perimeter, not the area.","es":"Lado × 4 es el perímetro, no el área."}],"example":{"en":"A square base with side 4: 4 × 4 = 16 square units.","es":"Una base cuadrada de lado 4: 4 × 4 = 16 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":4,"height":4},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A square base 4 units on each side.","es":"Una base cuadrada de 4 unidades por lado."}},"check":{"q":{"en":"A square base has sides of 7 inches. What is its area?","es":"Una base cuadrada tiene lados de 7 pulgadas. ¿Cuál es su área?"},"options":["28","14","49"],"correctIdx":2,"calc":{"expr":"7 × 7","value":"49"},"feedback":[{"en":"28 is 7 × 4, the perimeter. Area is 7 × 7.","es":"28 es 7 × 4, el perímetro. El área es 7 × 7."},{"en":"14 is 7 × 2. The area of a square multiplies 7 by 7.","es":"14 es 7 × 2. El área de un cuadrado multiplica 7 por 7."},{"en":"Yes. 7 × 7 = 49 square inches.","es":"Sí. 7 × 7 = 49 pulgadas cuadradas."}]}},{"name":{"en":"Area of a triangle: half of base × height","es":"Área de un triángulo: la mitad de base × altura"},"why":{"en":"Each lateral face is a triangle, and its height is the pyramid's slant height.","es":"Cada cara lateral es un triángulo, y su altura es la altura inclinada de la pirámide."},"steps":[{"en":"Multiply the triangle's base by its height.","es":"Multiplica la base del triángulo por su altura."},{"en":"Take half of the product.","es":"Toma la mitad del producto."}],"example":{"en":"Base 6, height 4: 6 × 4 = 24, half is 12. Four faces: 4 × 12 = 48.","es":"Base 6, altura 4: 6 × 4 = 24, la mitad es 12. Cuatro caras: 4 × 12 = 48."},"model":{"kind":"area","data":{"shape":"triangle","dims":{"base":6,"height":4},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A triangle face with base 6 and height 4.","es":"Una cara triangular de base 6 y altura 4."}},"check":{"q":{"en":"A triangle face has base 6 and slant height 5. What is its area?","es":"Una cara triangular tiene base 6 y altura inclinada 5. ¿Cuál es su área?"},"options":["30","15","11"],"correctIdx":1,"calc":{"expr":"1/2 × 6 × 5","value":"15"},"feedback":[{"en":"30 is base × height. Take half for a triangle.","es":"30 es base × altura. Para un triángulo, toma la mitad."},{"en":"Yes. 6 × 5 = 30, and half is 15 square units.","es":"Sí. 6 × 5 = 30, y la mitad es 15 unidades cuadradas."},{"en":"11 adds 6 + 5. Multiply them, then take half.","es":"11 suma 6 + 5. Multiplícalos y luego toma la mitad."}]}}]},"5-9":{"skills":[{"name":{"en":"Area of a triangle: half of base × height","es":"Área de un triángulo: la mitad de base × altura"},"why":{"en":"A regular polygon splits into equal triangles, so you start with one triangle's area.","es":"Un polígono regular se divide en triángulos iguales, así que empiezas con el área de un triángulo."},"steps":[{"en":"Multiply the base by the height.","es":"Multiplica la base por la altura."},{"en":"Take half of the product.","es":"Toma la mitad del producto."}],"example":{"en":"Base 10, height 3: 10 × 3 = 30, and half of 30 is 15 square units.","es":"Base 10, altura 3: 10 × 3 = 30, y la mitad de 30 es 15 unidades cuadradas."},"model":{"kind":"area","data":{"shape":"triangle","dims":{"base":10,"height":3},"unit":{"en":"units","es":"unidades"}},"alt":{"en":"A triangle with base 10 and height 3.","es":"Un triángulo de base 10 y altura 3."}},"check":{"q":{"en":"A triangle has base 8 cm and height 5 cm. What is its area?","es":"Un triángulo tiene base de 8 cm y altura de 5 cm. ¿Cuál es su área?"},"options":["20","40","13"],"correctIdx":0,"calc":{"expr":"1/2 × 8 × 5","value":"20"},"feedback":[{"en":"Yes. 8 × 5 = 40, and half is 20 square centimeters.","es":"Sí. 8 × 5 = 40, y la mitad es 20 centímetros cuadrados."},{"en":"40 is base × height. A triangle is half of that.","es":"40 es base × altura. Un triángulo es la mitad de eso."},{"en":"13 adds 8 + 5. Multiply, then take half.","es":"13 suma 8 + 5. Multiplica y luego toma la mitad."}]}},{"name":{"en":"Count the sides of a polygon","es":"Contar los lados de un polígono"},"why":{"en":"A regular polygon splits into one triangle per side, so the sides tell how many triangles.","es":"Un polígono regular se divide en un triángulo por cada lado, así que los lados dicen cuántos triángulos hay."},"steps":[{"en":"Pentagon: 5 sides. Hexagon: 6 sides. Octagon: 8 sides.","es":"Pentágono: 5 lados. Hexágono: 6 lados. Octágono: 8 lados."},{"en":"Lines from the center to each corner make that many triangles.","es":"Las líneas del centro a cada vértice forman esa misma cantidad de triángulos."},{"en":"Multiply one triangle's area by that number.","es":"Multiplica el área de un triángulo por ese número."}],"example":{"en":"A regular hexagon makes 6 equal triangles. If each is 5 square units, the area is 6 × 5 = 30.","es":"Un hexágono regular forma 6 triángulos iguales. Si cada uno mide 5 unidades cuadradas, el área es 6 × 5 = 30."},"model":{"kind":"tape","data":{"parts":6,"highlight":0,"wholeLabel":{"en":"hexagon = 6 × 5 = 30","es":"hexágono = 6 × 5 = 30"},"blockLabel":{"en":"1 triangle = 5","es":"1 triángulo = 5"},"unknown":null},"alt":{"en":"Six equal blocks for the 6 triangles of a hexagon, 5 square units each.","es":"Seis bloques iguales para los 6 triángulos de un hexágono, de 5 unidades cuadradas cada uno."}},"check":{"q":{"en":"A regular octagon splits into equal triangles of 10 square units each. What is its area?","es":"Un octágono regular se divide en triángulos iguales de 10 unidades cuadradas cada uno. ¿Cuál es su área?"},"options":["60","18","80"],"correctIdx":2,"calc":{"expr":"8 × 10","value":"80"},"feedback":[{"en":"60 uses 6 triangles, like a hexagon. An octagon has 8 sides, so 8 triangles.","es":"60 usa 6 triángulos, como un hexágono. Un octágono tiene 8 lados, así que 8 triángulos."},{"en":"18 adds 8 + 10. Multiply the number of triangles by each area.","es":"18 suma 8 + 10. Multiplica el número de triángulos por el área de cada uno."},{"en":"Yes. 8 triangles × 10 = 80 square units.","es":"Sí. 8 triángulos × 10 = 80 unidades cuadradas."}]}}]},"6-1":{"skills":[{"name":{"en":"Division asks how many groups fit","es":"La división pregunta cuántos grupos caben"},"why":{"en":"Tonight's fraction division asks the same question: how many pieces of one size fit in an amount.","es":"La división con fracciones de hoy hace la misma pregunta: cuántas partes de un tamaño caben en una cantidad."},"steps":[{"en":"Read 12 ÷ 3 as: how many 3s are in 12?","es":"Lee 12 ÷ 3 así: ¿cuántos 3 caben en 12?"},{"en":"Count groups of 3 until you reach 12.","es":"Cuenta grupos de 3 hasta llegar a 12."},{"en":"Check by multiplying: groups × size = the amount.","es":"Comprueba con una multiplicación: grupos × tamaño = la cantidad."}],"example":{"en":"12 ÷ 3: 3, 6, 9, 12 is four groups. So 12 ÷ 3 = 4, and 4 × 3 = 12.","es":"12 ÷ 3: 3, 6, 9, 12 son cuatro grupos. Entonces 12 ÷ 3 = 4, y 4 × 3 = 12."},"model":{"kind":"tape","data":{"parts":4,"highlight":4,"partLabel":{"en":"4 groups of 3","es":"4 grupos de 3"},"wholeLabel":"12","blockLabel":"3","unknown":null},"alt":{"en":"A bar of 12 split into blocks of 3. There are 4 blocks.","es":"Una barra de 12 dividida en bloques de 3. Hay 4 bloques."}},"check":{"q":{"en":"How many 4s are in 20?","es":"¿Cuántos 4 caben en 20?"},"options":["5","80","16"],"correctIdx":0,"calc":{"expr":"20 ÷ 4","value":"5"},"feedback":[{"en":"Yes. 4, 8, 12, 16, 20 is five groups, and 5 × 4 = 20.","es":"Sí. 4, 8, 12, 16, 20 son cinco grupos, y 5 × 4 = 20."},{"en":"80 multiplies 20 × 4. The question asks how many 4s fit, so divide.","es":"80 es 20 × 4. La pregunta es cuántos 4 caben, así que divide."},{"en":"16 subtracts one 4 from 20. Keep counting groups of 4 until you reach 20.","es":"16 es 20 menos un solo 4. Sigue contando grupos de 4 hasta llegar a 20."}]}},{"name":{"en":"How many unit fractions make one whole","es":"Cuántas fracciones unitarias forman 1 entero"},"why":{"en":"Tonight you count how many unit fractions, like 1/3, fit into whole numbers.","es":"Hoy cuentas cuántas fracciones unitarias, como 1/3, caben en números enteros."},"steps":[{"en":"A unit fraction has 1 on top, like 1/4.","es":"Una fracción unitaria tiene 1 arriba, como 1/4."},{"en":"The bottom number says how many equal pieces fill 1 whole.","es":"El número de abajo dice cuántas partes iguales llenan 1 entero."}],"example":{"en":"1/4: four pieces of 1/4 fill 1 whole, because 1/4 + 1/4 + 1/4 + 1/4 = 1.","es":"1/4: cuatro partes de 1/4 llenan 1 entero, porque 1/4 + 1/4 + 1/4 + 1/4 = 1."},"model":{"kind":"fraction","data":{"parts":4,"shaded":4,"label":"4/4 = 1"},"alt":{"en":"One whole bar cut into 4 equal pieces. All 4 fourths are shaded, so 4/4 = 1.","es":"Una barra entera cortada en 4 partes iguales. Los 4 cuartos están sombreados: 4/4 = 1."}},"check":{"q":{"en":"How many 1/5 pieces make 1 whole?","es":"¿Cuántas partes de 1/5 forman 1 entero?"},"options":["1/5","1","5"],"correctIdx":2,"calc":{"expr":"1 ÷ (1/5)","value":"5"},"feedback":[{"en":"1/5 is the size of one piece. The question asks how many pieces.","es":"1/5 es el tamaño de una parte. La pregunta es cuántas partes hay."},{"en":"One piece of 1/5 is too small to fill the whole. Count fifths up to 5/5.","es":"Una parte de 1/5 no llena el entero. Cuenta quintos hasta llegar a 5/5."},{"en":"Yes. Five fifths fill the whole: 5/5 = 1.","es":"Sí. Cinco quintos llenan el entero: 5/5 = 1."}]}}]},"6-10":{"skills":[{"name":{"en":"Write a mixed number as one fraction","es":"Escribir un número mixto como una fracción"},"why":{"en":"Tonight's division starts by rewriting each mixed number as one fraction.","es":"La división de hoy empieza al escribir cada número mixto como una sola fracción."},"steps":[{"en":"Multiply the whole number by the denominator.","es":"Multiplica el número entero por el denominador."},{"en":"Add the numerator.","es":"Suma el numerador."},{"en":"Keep the same denominator.","es":"Mantén el mismo denominador."}],"example":{"en":"2 1/3: 2 × 3 = 6, then 6 + 1 = 7, so 2 1/3 = 7/3.","es":"2 1/3: 2 × 3 = 6, luego 6 + 1 = 7, entonces 2 1/3 = 7/3."},"check":{"q":{"en":"Write 1 3/4 as one fraction.","es":"Escribe 1 3/4 como una sola fracción."},"options":["7/4","4/4","13/4"],"correctIdx":0,"calc":{"expr":"1 + 3/4","value":"7/4"},"feedback":[{"en":"Yes. 1 × 4 = 4, and 4 + 3 = 7 fourths.","es":"Sí. 1 × 4 = 4, y 4 + 3 = 7 cuartos."},{"en":"4/4 is only the 1 whole. Add the 3 fourths too.","es":"4/4 es solo el 1 entero. Suma también los 3 cuartos."},{"en":"13/4 puts the digits side by side. Multiply 1 × 4, then add 3.","es":"13/4 pone los dígitos lado a lado. Multiplica 1 × 4 y luego suma 3."}]},"model":{"kind":"numberline","data":{"min":0,"max":3,"step":1,"points":[{"value":2.3333333333333335,"label":"2 1/3 = 7/3","kind":"answer"}]},"alt":{"en":"A number line from 0 to 3 with a point a third of the way from 2 to 3, marked 2 1/3 = 7/3.","es":"Una recta numérica de 0 a 3 con un punto a un tercio del camino entre 2 y 3, marcado 2 1/3 = 7/3."}}},{"name":{"en":"Flip a fraction (the reciprocal)","es":"Invertir una fracción (el recíproco)"},"why":{"en":"To divide by a fraction, you multiply by its flip.","es":"Para dividir entre una fracción, multiplicas por su fracción invertida."},"steps":[{"en":"Swap the numerator and the denominator.","es":"Intercambia el numerador y el denominador."},{"en":"A whole number like 3 is 3/1, so its flip is 1/3.","es":"Un número entero como 3 es 3/1, así que al invertirlo queda 1/3."}],"example":{"en":"The flip of 2/5 is 5/2.","es":"Al invertir 2/5 queda 5/2."},"check":{"q":{"en":"What is the flip of 3/8?","es":"¿Qué queda al invertir 3/8?"},"options":["3/8","8/3","5/8"],"correctIdx":1,"calc":{"expr":"1 ÷ (3/8)","value":"8/3"},"feedback":[{"en":"That is the same fraction. Swap the top and the bottom.","es":"Es la misma fracción. Intercambia el número de arriba y el de abajo."},{"en":"Yes. The 3 and the 8 trade places: 8/3.","es":"Sí. El 3 y el 8 cambian de lugar: 8/3."},{"en":"Flipping does not subtract. Swap 3 and 8.","es":"Invertir no es restar. Intercambia el 3 y el 8."}]},"model":{"kind":"kcf","data":{"dividend":"1","divisor":"2/5"},"alt":{"en":"Keep, Change, Flip for 1 ÷ 2/5: the 2/5 flips to 5/2.","es":"Mantener, Cambiar, Invertir para 1 ÷ 2/5: el 2/5 se invierte a 5/2."}}}]},"6-11":{"skills":[{"name":{"en":"Divide by a fraction: multiply by the reciprocal","es":"Dividir entre una fracción: multiplicar por el recíproco"},"why":{"en":"Tonight's word problems become fraction division equations that you solve this way.","es":"Los problemas de hoy se convierten en ecuaciones de división con fracciones que resuelves así."},"steps":[{"en":"Keep the first number.","es":"Deja igual el primer número."},{"en":"Change ÷ to ×.","es":"Cambia ÷ por ×."},{"en":"Flip the fraction you divide by, then multiply.","es":"Invierte la fracción entre la que divides y luego multiplica."}],"example":{"en":"3/4 ÷ 1/8 = 3/4 × 8 = 24/4 = 6. Six eighths fit.","es":"3/4 ÷ 1/8 = 3/4 × 8 = 24/4 = 6. Caben seis octavos."},"model":{"kind":"kcf","data":{"dividend":"3/4","divisor":"1/8"},"alt":{"en":"Keep, Change, Flip for 3/4 ÷ 1/8: keep 3/4, change ÷ to ×, flip 1/8 to 8/1, then multiply.","es":"Mantener, Cambiar, Invertir para 3/4 ÷ 1/8: mantén 3/4, cambia ÷ por ×, invierte 1/8 a 8/1 y multiplica."}},"check":{"q":{"en":"What is 2/3 ÷ 1/6?","es":"¿Cuánto es 2/3 ÷ 1/6?"},"options":["2/18","1/4","4"],"correctIdx":2,"calc":{"expr":"2/3 × 6","value":"4"},"feedback":[{"en":"2/18 multiplies without flipping. Flip 1/6 to 6, then multiply.","es":"2/18 multiplica sin invertir. Invierte 1/6 para obtener 6 y luego multiplica."},{"en":"1/4 flips the first fraction. Keep 2/3 and flip 1/6 instead.","es":"1/4 invierte la primera fracción. Deja 2/3 igual e invierte 1/6."},{"en":"Yes. 2/3 × 6 = 12/3 = 4. Four sixths fit in 2/3.","es":"Sí. 2/3 × 6 = 12/3 = 4. En 2/3 caben cuatro sextos."}]}},{"name":{"en":"Check a division by multiplying","es":"Comprobar una división con una multiplicación"},"why":{"en":"Tonight you check each solution by multiplying the quotient by the divisor.","es":"Hoy compruebas cada solución multiplicando el cociente por el divisor."},"steps":[{"en":"Multiply the quotient by the divisor.","es":"Multiplica el cociente por el divisor."},{"en":"If you get the dividend back, the answer is right.","es":"Si obtienes el dividendo, la respuesta es correcta."}],"example":{"en":"6 ÷ 1/2 = 12. Check: 12 × 1/2 = 6. It matches.","es":"6 ÷ 1/2 = 12. Comprobación: 12 × 1/2 = 6. Coincide."},"model":{"kind":"numberline","data":{"min":0,"max":6,"step":0.5,"points":[{"value":6,"label":{"en":"12 halves = 6","es":"12 medios = 6"},"kind":"answer"}]},"alt":{"en":"A number line from 0 to 6 marked in halves. Twelve half-jumps reach 6, so 12 × 1/2 = 6.","es":"Una recta numérica de 0 a 6 marcada en medios. Doce saltos de un medio llegan a 6: 12 × 1/2 = 6."}},"check":{"q":{"en":"To check 2 ÷ 1/4 = 8, find 8 × 1/4.","es":"Para comprobar 2 ÷ 1/4 = 8, calcula 8 × 1/4."},"options":["32","2","8 1/4"],"correctIdx":1,"calc":{"expr":"8 × 1/4","value":"2"},"feedback":[{"en":"32 multiplies 8 × 4. Times 1/4 means one fourth of 8.","es":"32 es 8 × 4. Por 1/4 significa la cuarta parte de 8."},{"en":"Yes. One fourth of 8 is 2, the dividend, so 8 is right.","es":"Sí. La cuarta parte de 8 es 2, el dividendo, así que 8 es correcto."},{"en":"8 1/4 adds 8 + 1/4. The × sign means multiply.","es":"8 1/4 es la suma 8 + 1/4. El signo × pide multiplicar."}]}}]},"6-12":{"skills":[{"name":{"en":"Skip-count to list multiples","es":"Contar de tanto en tanto para hacer la lista de múltiplos"},"why":{"en":"Tonight you find the least common multiple by listing multiples of two numbers.","es":"Hoy hallas el mínimo común múltiplo haciendo listas de múltiplos de dos números."},"steps":[{"en":"Start with the number itself.","es":"Empieza con el mismo número."},{"en":"Add the number again for each new multiple.","es":"Suma el número otra vez para cada nuevo múltiplo."}],"example":{"en":"Multiples of 6: 6, 12, 18, 24, 30.","es":"Múltiplos de 6: 6, 12, 18, 24 y 30."},"model":{"kind":"numberline","data":{"min":0,"max":30,"step":6,"points":[{"value":6,"label":"6","kind":"given"},{"value":12,"label":"12","kind":"given"},{"value":18,"label":"18","kind":"given"},{"value":24,"label":"24","kind":"given"},{"value":30,"label":"30","kind":"given"}]},"alt":{"en":"A number line from 0 to 30 with jumps of 6. Dots sit on 6, 12, 18, 24 and 30.","es":"Una recta numérica de 0 a 30 con saltos de 6. Hay puntos en 6, 12, 18, 24 y 30."}},"check":{"q":{"en":"Skip-count by 7: 7, 14, 21, ... What comes next?","es":"Cuenta de 7 en 7: 7, 14, 21, ... ¿Qué número sigue?"},"options":["22","28","35"],"correctIdx":1,"calc":{"expr":"7 × 4","value":"28"},"feedback":[{"en":"22 adds only 1. Each step adds 7: 21 + 7.","es":"22 suma solo 1. Cada paso suma 7: 21 + 7."},{"en":"Yes. 21 + 7 = 28, and 28 = 7 × 4.","es":"Sí. 21 + 7 = 28, y 28 = 7 × 4."},{"en":"35 skips a number. 21 + 7 = 28 comes first.","es":"35 se salta un número. Primero viene 21 + 7 = 28."}]}},{"name":{"en":"Tell a multiple from a factor","es":"Distinguir un múltiplo de un factor"},"why":{"en":"Tonight's least common multiple is a multiple, so mixing it up with a factor gives the wrong number.","es":"El mínimo común múltiplo de hoy es un múltiplo; si lo confundes con un factor, el número sale mal."},"steps":[{"en":"A factor divides the number evenly, so it is never bigger than the number.","es":"Un factor divide al número exactamente, así que nunca es mayor que él."},{"en":"A multiple is the number times 1, 2, 3, and so on, so it is never smaller.","es":"Un múltiplo es el número por 1, 2, 3, etc., así que nunca es menor que él."}],"example":{"en":"For 6: 2 and 3 are factors. 12 and 24 are multiples.","es":"Para el 6: 2 y 3 son factores. 12 y 24 son múltiplos."},"model":{"kind":"numberline","data":{"min":0,"max":24,"step":1,"points":[{"value":2,"label":{"en":"factor","es":"factor"},"kind":"given"},{"value":3,"label":{"en":"factor","es":"factor"},"kind":"given"},{"value":6,"label":"6","kind":"given"},{"value":12,"label":{"en":"multiple","es":"múltiplo"},"kind":"answer"},{"value":24,"label":{"en":"multiple","es":"múltiplo"},"kind":"answer"}]},"alt":{"en":"A number line from 0 to 24. The factors 2 and 3 sit left of 6. The multiples 12 and 24 sit right of it.","es":"Una recta numérica de 0 a 24. Los factores 2 y 3 están a la izquierda del 6. Los múltiplos 12 y 24, a la derecha."}},"check":{"q":{"en":"Which number is a multiple of 6?","es":"¿Qué número es múltiplo de 6?"},"options":["3","2","18"],"correctIdx":2,"calc":{"expr":"6 × 3","value":"18"},"feedback":[{"en":"3 is a factor of 6, since 6 ÷ 3 = 2. Multiples are 6, 12, 18, and more.","es":"3 es factor de 6, porque 6 ÷ 3 = 2. Los múltiplos son 6, 12, 18 y más."},{"en":"2 is a factor of 6. A multiple comes from 6 × 1, 6 × 2, 6 × 3, and so on.","es":"2 es factor de 6. Un múltiplo sale de 6 × 1, 6 × 2, 6 × 3, etc."},{"en":"Yes. 6 × 3 = 18, so 18 is a multiple of 6.","es":"Sí. 6 × 3 = 18, así que 18 es múltiplo de 6."}]}}]},"6-13":{"skills":[{"name":{"en":"Tell prime numbers from composite numbers","es":"Distinguir números primos de números compuestos"},"why":{"en":"Tonight's factor trees keep splitting until every branch ends in a prime number.","es":"Los árboles de factores de hoy se dividen hasta que cada rama termina en un número primo."},"steps":[{"en":"A prime number has exactly two factors: 1 and itself.","es":"Un número primo tiene exactamente dos factores: 1 y él mismo."},{"en":"A composite number has more factors, so you can split it.","es":"Un número compuesto tiene más factores, así que puedes descomponerlo."}],"example":{"en":"5 is prime: only 1 × 5. 6 is composite: 2 × 3.","es":"5 es primo: solo 1 × 5. 6 es compuesto: 2 × 3."},"model":{"kind":"grid","data":{"rows":2,"cols":3,"filled":6,"groupSize":10,"label":{"en":"6 = 2 × 3: composite","es":"6 = 2 × 3: compuesto"}},"alt":{"en":"An array of 2 rows of 3. Six splits into 2 × 3, so 6 is composite.","es":"Un arreglo de 2 filas de 3. El 6 se descompone en 2 × 3, así que es compuesto."}},"check":{"q":{"en":"Which number is prime?","es":"¿Qué número es primo?"},"options":["9","7","15"],"correctIdx":1,"calc":{"expr":"14 ÷ 2","value":"7"},"feedback":[{"en":"9 is 3 × 3, so it is composite. Look for a number with only 1 and itself.","es":"9 es 3 × 3, así que es compuesto. Busca un número cuyos únicos factores sean 1 y él mismo."},{"en":"Yes. 7 has only two factors, 1 and 7.","es":"Sí. 7 tiene solo dos factores, 1 y 7."},{"en":"15 is 3 × 5, so it is composite. Odd numbers are not always prime.","es":"15 es 3 × 5, así que es compuesto. Los números impares no siempre son primos."}]}},{"name":{"en":"Split a number into a factor pair","es":"Descomponer un número en un par de factores"},"why":{"en":"Each branch of tonight's factor tree splits a number into two factors.","es":"Cada rama del árbol de factores de hoy descompone un número en dos factores."},"steps":[{"en":"Pick a small number that divides evenly, like 2 or 3.","es":"Elige un número pequeño que divida exacto, como 2 o 3."},{"en":"Divide to find its partner.","es":"Divide para hallar su pareja."}],"example":{"en":"36 = 4 × 9, because 36 ÷ 4 = 9.","es":"36 = 4 × 9, porque 36 ÷ 4 = 9."},"model":{"kind":"grid","data":{"rows":4,"cols":9,"filled":36,"groupSize":10,"label":"36 = 4 × 9"},"alt":{"en":"An array of 4 rows of 9 squares, 36 in all. It shows the factor pair 4 × 9.","es":"Un arreglo de 4 filas de 9 cuadros, 36 en total. Muestra el par de factores 4 × 9."}},"check":{"q":{"en":"Fill in the blank: 48 = 6 × ?","es":"Completa: 48 = 6 × ?"},"options":["8","42","9"],"correctIdx":0,"calc":{"expr":"48 ÷ 6","value":"8"},"feedback":[{"en":"Yes. 6 × 8 = 48, so 6 and 8 are a factor pair.","es":"Sí. 6 × 8 = 48, así que 6 y 8 son un par de factores."},{"en":"42 subtracts 48 − 6. Divide instead: 48 ÷ 6.","es":"42 es la resta 48 − 6. Mejor divide: 48 ÷ 6."},{"en":"6 × 9 is 54, too big. Try 6 × 8.","es":"6 × 9 da 54, es demasiado. Prueba 6 × 8."}]}}]},"6-14":{"skills":[{"name":{"en":"Work inside parentheses first","es":"Resolver primero lo que está entre paréntesis"},"why":{"en":"Tonight 3(4 + 2) and 3 × 4 + 3 × 2 must give the same value, so you evaluate parentheses correctly.","es":"Hoy 3(4 + 2) y 3 × 4 + 3 × 2 deben dar el mismo valor, así que resuelves bien los paréntesis."},"steps":[{"en":"Find the value inside the parentheses first.","es":"Primero halla el valor dentro de los paréntesis."},{"en":"A number right before parentheses means multiply.","es":"Un número justo antes de un paréntesis significa multiplicar."}],"example":{"en":"3(4 + 2): add first, 4 + 2 = 6, then 3 × 6 = 18.","es":"3(4 + 2): primero suma, 4 + 2 = 6, y luego 3 × 6 = 18."},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":6,"height":3,"split":[4,2]}},"alt":{"en":"A rectangle 3 tall and 4 + 2 wide. It is 3 × 6 = 18, or 3 × 4 plus 3 × 2.","es":"Un rectángulo de 3 de alto y 4 + 2 de ancho. Mide 3 × 6 = 18, o 3 × 4 más 3 × 2."}},"check":{"q":{"en":"What is 5(2 + 6)?","es":"¿Cuánto es 5(2 + 6)?"},"options":["16","13","40"],"correctIdx":2,"calc":{"expr":"5 × (2 + 6)","value":"40"},"feedback":[{"en":"16 does 5 × 2 + 6 and skips the parentheses. Add 2 + 6 first.","es":"16 hace 5 × 2 + 6 y olvida el paréntesis. Suma 2 + 6 primero."},{"en":"13 adds 5 + 2 + 6. A number before parentheses means multiply.","es":"13 suma 5 + 2 + 6. Un número antes de un paréntesis significa multiplicar."},{"en":"Yes. 2 + 6 = 8, and 5 × 8 = 40.","es":"Sí. 2 + 6 = 8, y 5 × 8 = 40."}]}},{"name":{"en":"Find the greatest common factor (GCF)","es":"Hallar el máximo común divisor (MCD)"},"why":{"en":"Tonight you factor expressions like 12 + 18 by pulling out the greatest common factor.","es":"Hoy factorizas expresiones como 12 + 18 sacando el máximo común divisor."},"steps":[{"en":"List the factors of each number.","es":"Haz la lista de los factores de cada número."},{"en":"Circle the factors both lists share.","es":"Encierra los factores que están en las dos listas."},{"en":"The biggest shared factor is the GCF.","es":"El mayor factor que comparten es el máximo común divisor."}],"example":{"en":"8: 1, 2, 4, 8. 12: 1, 2, 3, 4, 6, 12. The GCF is 4.","es":"8: 1, 2, 4, 8. 12: 1, 2, 3, 4, 6, 12. El máximo común divisor es 4."},"model":{"kind":"numberline","data":{"min":0,"max":12,"step":1,"points":[{"value":1,"label":{"en":"common","es":"común"},"kind":"given"},{"value":2,"label":{"en":"common","es":"común"},"kind":"given"},{"value":4,"label":{"en":"GCF","es":"MCD"},"kind":"answer"},{"value":8,"label":"8","kind":"given"},{"value":12,"label":"12","kind":"given"}]},"alt":{"en":"A number line from 0 to 12. The common factors of 8 and 12 are 1, 2 and 4; the greatest is 4.","es":"Una recta numérica de 0 a 12. Los factores comunes de 8 y 12 son 1, 2 y 4; el mayor es 4."}},"check":{"q":{"en":"What is the GCF of 12 and 18?","es":"¿Cuál es el máximo común divisor de 12 y 18?"},"options":["3","6","36"],"correctIdx":1,"calc":{"expr":"18 ÷ 3","value":"6"},"feedback":[{"en":"3 is a common factor, but not the greatest. 6 also divides both.","es":"3 es un factor común, pero no el mayor. El 6 también divide a los dos."},{"en":"Yes. 6 divides 12 and 18, and no bigger number does.","es":"Sí. 6 divide a 12 y a 18, y ningún número mayor lo hace."},{"en":"36 is a common multiple, not a factor. A factor cannot be bigger than 12.","es":"36 es un múltiplo común, no un factor. Un factor no puede ser mayor que 12."}]}}]},"6-15":{"skills":[{"name":{"en":"Read a term like 7y","es":"Leer un término como 7y"},"why":{"en":"Tonight you combine like terms, so you need to see that 7y means 7 groups of y.","es":"Hoy combinas términos semejantes, así que necesitas ver que 7y significa 7 grupos de y."},"steps":[{"en":"The number in front is the coefficient. It counts the groups.","es":"El número de adelante es el coeficiente. Cuenta los grupos."},{"en":"7y means 7 × y. A plain y means 1y.","es":"7y significa 7 × y. Una y sola significa 1y."}],"example":{"en":"If y = 2, then 7y = 7 × 2 = 14, and y alone is 1 × 2 = 2.","es":"Si y = 2, entonces 7y = 7 × 2 = 14. Además, la y sola vale 1 × 2 = 2."},"model":{"kind":"tape","data":{"parts":7,"highlight":7,"partLabel":{"en":"7 groups of y","es":"7 grupos de y"},"wholeLabel":"7y = 14","blockLabel":"y = 2","unknown":null},"alt":{"en":"A bar of 7 equal blocks, each y = 2. Together they make 7y = 14.","es":"Una barra de 7 bloques iguales, cada uno y = 2. Juntos forman 7y = 14."}},"check":{"q":{"en":"What is 7y when y = 3?","es":"¿Cuánto vale 7y cuando y = 3?"},"options":["21","73","10"],"correctIdx":0,"calc":{"expr":"7 × 3","value":"21"},"feedback":[{"en":"Yes. 7y means 7 × y, and 7 × 3 = 21.","es":"Sí. 7y significa 7 × y, y 7 × 3 = 21."},{"en":"73 writes the digits side by side. 7y means 7 × 3.","es":"73 pone las cifras una al lado de la otra. 7y significa 7 × 3."},{"en":"10 adds 7 + 3. A coefficient multiplies the variable.","es":"10 suma 7 + 3. El coeficiente multiplica a la variable."}]}},{"name":{"en":"Use the distributive property","es":"Usar la propiedad distributiva"},"why":{"en":"Some of tonight's expressions have parentheses, so you distribute before combining like terms.","es":"Algunas expresiones de hoy tienen paréntesis, así que aplicas la propiedad distributiva antes de combinar términos semejantes."},"steps":[{"en":"Multiply the number outside by each term inside.","es":"Multiplica el número de afuera por cada término de adentro."},{"en":"Keep the + or − sign between the new terms.","es":"Conserva el signo + o − entre los nuevos términos."}],"example":{"en":"2(x + 3): 2 × x = 2x and 2 × 3 = 6, so 2x + 6.","es":"2(x + 3): 2 × x = 2x y 2 × 3 = 6, así que queda 2x + 6."},"model":{"kind":"balance","data":{"left":["2(x + 3)"],"right":["2x","6"],"unknown":null},"alt":{"en":"A level balance. 2(x + 3) on the left weighs the same as 2x and 6 on the right.","es":"Una balanza en equilibrio. 2(x + 3) a la izquierda pesa lo mismo que 2x y 6 a la derecha."}},"check":{"q":{"en":"Fill in the blank: 3(y + 4) = 3y + ?","es":"Completa: 3(y + 4) = 3y + ?"},"options":["4","12","7"],"correctIdx":1,"calc":{"expr":"3 × 4","value":"12"},"feedback":[{"en":"4 forgot to multiply. The 3 multiplies the 4 too: 3 × 4.","es":"4 olvida multiplicar. El 3 también multiplica al 4: 3 × 4."},{"en":"Yes. 3 × y = 3y and 3 × 4 = 12.","es":"Sí. 3 × y = 3y, y 3 × 4 = 12."},{"en":"7 adds 3 + 4. Distributing means multiply each term by 3.","es":"7 suma 3 + 4. Distribuir significa multiplicar cada término por 3."}]}}]},"6-2":{"skills":[{"name":{"en":"Multiply two fractions","es":"Multiplicar dos fracciones"},"why":{"en":"Tonight you divide fractions by multiplying by the reciprocal, so fraction multiplication must feel easy.","es":"Hoy divides fracciones multiplicando por el recíproco, así que multiplicar fracciones debe resultarte fácil."},"steps":[{"en":"Multiply the numerators to get the new numerator.","es":"Multiplica los numeradores para obtener el nuevo numerador."},{"en":"Multiply the denominators to get the new denominator.","es":"Multiplica los denominadores para obtener el nuevo denominador."},{"en":"Simplify if you can.","es":"Simplifica si se puede."}],"example":{"en":"2/3 × 1/2 = (2 × 1)/(3 × 2) = 2/6, which simplifies to 1/3.","es":"2/3 × 1/2 = (2 × 1)/(3 × 2) = 2/6, que se simplifica a 1/3."},"model":{"kind":"fraction","data":{"parts":6,"shaded":2,"label":"2/3 × 1/2 = 2/6 = 1/3"},"alt":{"en":"A bar cut into 6 equal pieces with 2 shaded: 2/3 × 1/2 = 2/6, which is 1/3.","es":"Una barra cortada en 6 partes iguales con 2 sombreadas: 2/3 × 1/2 = 2/6, o sea 1/3."}},"check":{"q":{"en":"What is 3/4 × 2/5?","es":"¿Cuánto es 3/4 × 2/5?"},"options":["5/9","3/10","15/8"],"correctIdx":1,"calc":{"expr":"3/4 × 2/5","value":"3/10"},"feedback":[{"en":"5/9 adds the tops and the bottoms. Multiply them instead: 3 × 2 and 4 × 5.","es":"5/9 suma los números de arriba y los de abajo. Multiplícalos: 3 × 2 y 4 × 5."},{"en":"Yes. 3 × 2 = 6 and 4 × 5 = 20, and 6/20 simplifies to 3/10.","es":"Sí. 3 × 2 = 6 y 4 × 5 = 20, y 6/20 se simplifica a 3/10."},{"en":"15/8 multiplies across in an X. Multiply straight across: top × top, bottom × bottom.","es":"15/8 multiplica en cruz. Multiplica en línea recta: arriba por arriba y abajo por abajo."}]}},{"name":{"en":"Make equivalent fractions with a common denominator","es":"Hacer fracciones equivalentes con un denominador común"},"why":{"en":"One way to divide tonight is to give both fractions the same denominator first.","es":"Una forma de dividir hoy es darles primero el mismo denominador a las dos fracciones."},"steps":[{"en":"Choose the new denominator you need.","es":"Elige el nuevo denominador que necesitas."},{"en":"Find what you multiply the old denominator by to get it.","es":"Busca por cuánto multiplicas el denominador anterior para llegar a él."},{"en":"Multiply the numerator by that same number.","es":"Multiplica el numerador por ese mismo número."}],"example":{"en":"1/2 as fourths: 2 × 2 = 4, so 1 × 2 = 2. 1/2 = 2/4.","es":"1/2 en cuartos: 2 × 2 = 4, así que 1 × 2 = 2. 1/2 = 2/4."},"model":{"kind":"fraction","data":{"parts":4,"shaded":2,"label":"1/2 = 2/4"},"alt":{"en":"A bar cut into 4 equal pieces with 2 shaded. Two fourths fill the same space as one half.","es":"Una barra cortada en 4 partes iguales con 2 sombreadas. Dos cuartos ocupan lo mismo que un medio."}},"check":{"q":{"en":"2/3 = ?/12. Which fraction is equal to 2/3?","es":"2/3 = ?/12. ¿Qué fracción es igual a 2/3?"},"options":["8/12","2/12","11/12"],"correctIdx":0,"calc":{"expr":"(2 × 4)/(3 × 4)","value":"8/12"},"feedback":[{"en":"Yes. 3 × 4 = 12, so 2 × 4 = 8. 2/3 = 8/12.","es":"Sí. 3 × 4 = 12, así que 2 × 4 = 8. 2/3 = 8/12."},{"en":"2/12 changes only the bottom. Multiply the top by 4 as well.","es":"2/12 cambia solo el número de abajo. Multiplica también el de arriba por 4."},{"en":"11/12 adds 9 to the top and bottom. Multiply both by 4 instead.","es":"11/12 suma 9 arriba y abajo. Mejor multiplica los dos por 4."}]}}]},"6-3":{"skills":[{"name":{"en":"Repeated multiplication is not repeated addition","es":"Multiplicar varias veces no es sumar varias veces"},"why":{"en":"Tonight's exponents mean multiplying the same number again and again, not adding it.","es":"Los exponentes de hoy significan multiplicar el mismo número una y otra vez, no sumarlo."},"steps":[{"en":"Write the number as many times as you are told.","es":"Escribe el número tantas veces como se indica."},{"en":"Put × signs between them, not + signs.","es":"Pon signos × entre ellos, no signos +."},{"en":"Multiply two at a time, left to right.","es":"Multiplica de dos en dos, de izquierda a derecha."}],"example":{"en":"Three 5s: 5 + 5 + 5 = 15, but 5 × 5 × 5 = 25 × 5 = 125.","es":"Tres cincos: 5 + 5 + 5 = 15, pero 5 × 5 × 5 = 25 × 5 = 125."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"5 × 5 × 5"},{"rule":"MD","expr":"25 × 5"},{"rule":"MD","expr":"125"}]},"alt":{"en":"Three 5s multiplied: 5 × 5 × 5 becomes 25 × 5, then 125.","es":"Tres 5 multiplicados: 5 × 5 × 5 se vuelve 25 × 5 y luego 125."}},"check":{"q":{"en":"What is 2 × 2 × 2 × 2?","es":"¿Cuánto es 2 × 2 × 2 × 2?"},"options":["8","32","16"],"correctIdx":2,"calc":{"expr":"2 × 2 × 2 × 2","value":"16"},"feedback":[{"en":"8 is 2 + 2 + 2 + 2, or 2 × 4. Multiply the 2s: 2 × 2 × 2 × 2.","es":"8 es 2 + 2 + 2 + 2, o 2 × 4. Multiplica los 2: 2 × 2 × 2 × 2."},{"en":"32 uses five 2s. Count the 2s: there are only four.","es":"32 usa cinco 2. Cuenta los 2: solo hay cuatro."},{"en":"Yes. 2 × 2 = 4, 4 × 2 = 8, and 8 × 2 = 16.","es":"Sí. 2 × 2 = 4, 4 × 2 = 8 y 8 × 2 = 16."}]}},{"name":{"en":"Multiply by 10 again and again","es":"Multiplicar por 10 una y otra vez"},"why":{"en":"Tonight's powers of 10, like 10³, are 10s multiplied together.","es":"Las potencias de 10 de hoy, como 10³, son varios 10 multiplicados entre sí."},"steps":[{"en":"Each time you multiply by 10, write one more zero.","es":"Cada vez que multiplicas por 10, escribe un cero más."},{"en":"Count the 10s to know how many zeros to write.","es":"Cuenta los 10 para saber cuántos ceros escribir."}],"example":{"en":"10 × 10 = 100 has two zeros, one for each 10.","es":"10 × 10 = 100 tiene dos ceros, uno por cada 10."},"model":{"kind":"grid","data":{"rows":10,"cols":10,"filled":100,"groupSize":10,"label":"10 × 10 = 100"},"alt":{"en":"A grid of 10 rows of 10 squares. All 100 squares are shaded.","es":"Una cuadrícula de 10 filas de 10 cuadros. Los 100 cuadros están sombreados."}},"check":{"q":{"en":"What is 10 × 10 × 10?","es":"¿Cuánto es 10 × 10 × 10?"},"options":["1000","30","100"],"correctIdx":0,"calc":{"expr":"10 × 10 × 10","value":"1000"},"feedback":[{"en":"Yes. Three 10s give three zeros: 1000.","es":"Sí. Tres 10 dan tres ceros: 1000."},{"en":"30 adds 10 + 10 + 10. Multiply the 10s instead.","es":"30 es la suma 10 + 10 + 10. Mejor multiplica los 10."},{"en":"100 uses only two 10s. Multiply by the third 10 too.","es":"100 usa solo dos 10. Multiplica también por el tercer 10."}]}}]},"6-4":{"skills":[{"name":{"en":"Find the value of a power","es":"Hallar el valor de una potencia"},"why":{"en":"Tonight's expressions include powers, and you find each power's value first.","es":"Las expresiones de hoy tienen potencias, y primero hallas el valor de cada potencia."},"steps":[{"en":"The exponent tells how many times the base is a factor.","es":"El exponente dice cuántas veces la base es factor."},{"en":"Write it as repeated multiplication, then multiply.","es":"Escríbela como una multiplicación repetida y luego multiplica."}],"example":{"en":"3² = 3 × 3 = 9, not 3 × 2 = 6.","es":"3² = 3 × 3 = 9, y no 3 × 2 = 6."},"model":{"kind":"grid","data":{"rows":3,"cols":3,"filled":9,"groupSize":10,"label":"3² = 3 × 3 = 9"},"alt":{"en":"A square of 3 rows of 3 squares. It has 9 squares, so 3² = 9.","es":"Un cuadrado de 3 filas de 3 cuadros. Tiene 9 cuadros, así que 3² = 9."}},"check":{"q":{"en":"What is 5³?","es":"¿Cuánto es 5³?"},"options":["15","125","25"],"correctIdx":1,"calc":{"expr":"5 × 5 × 5","value":"125"},"feedback":[{"en":"15 is 5 × 3. The 3 means use 5 as a factor three times.","es":"15 es 5 × 3. El 3 indica usar el 5 como factor tres veces."},{"en":"Yes. 5 × 5 = 25, and 25 × 5 = 125.","es":"Sí. 5 × 5 = 25, y 25 × 5 = 125."},{"en":"25 is 5 × 5, only two factors. Multiply by one more 5.","es":"25 es 5 × 5, solo dos factores. Multiplica por otro 5."}]}},{"name":{"en":"Multiply before you add or subtract","es":"Multiplicar antes de sumar o restar"},"why":{"en":"Tonight you evaluate expressions with the order of operations, where × and ÷ come before + and −.","es":"Hoy evalúas expresiones con el orden de las operaciones, donde × y ÷ van antes que + y −."},"steps":[{"en":"Do anything inside parentheses first.","es":"Primero resuelve lo que está entre paréntesis."},{"en":"Next, multiply and divide from left to right.","es":"Después, multiplica y divide de izquierda a derecha."},{"en":"Last, add and subtract from left to right.","es":"Al final, suma y resta de izquierda a derecha."}],"example":{"en":"2 + 3 × 4: multiply first, 3 × 4 = 12, then 2 + 12 = 14.","es":"2 + 3 × 4: primero multiplica, 3 × 4 = 12, y luego 2 + 12 = 14."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"2 + 3 × 4"},{"rule":"MD","expr":"2 + 12"},{"rule":"AS","expr":"14"}]},"alt":{"en":"The order of operations ladder. 2 + 3 × 4 becomes 2 + 12 after multiplying, then 14 after adding.","es":"La escalera del orden de las operaciones. 2 + 3 × 4 se vuelve 2 + 12 al multiplicar y luego 14 al sumar."}},"check":{"q":{"en":"What is 10 − 2 × 3?","es":"¿Cuánto es 10 − 2 × 3?"},"options":["4","24","8"],"correctIdx":0,"calc":{"expr":"10 - 2 × 3","value":"4"},"feedback":[{"en":"Yes. 2 × 3 = 6 first, then 10 − 6 = 4.","es":"Sí. Primero 2 × 3 = 6, y luego 10 − 6 = 4."},{"en":"24 subtracts first: 10 − 2 = 8, then 8 × 3. Multiply 2 × 3 first.","es":"24 resta primero: 10 − 2 = 8, y luego 8 × 3. Multiplica 2 × 3 primero."},{"en":"8 stops after 10 − 2 and skips the × 3. Multiply 2 × 3, then subtract.","es":"8 se queda en 10 − 2 y olvida el × 3. Multiplica 2 × 3 y luego resta."}]}}]},"6-5":{"skills":[{"name":{"en":"Math words that name an operation","es":"Palabras que indican una operación"},"why":{"en":"Tonight you turn word phrases into expressions, so each word must point to the right operation.","es":"Hoy conviertes frases en expresiones, así que cada palabra debe indicar la operación correcta."},"steps":[{"en":"Sum means add (+). Difference means subtract (−).","es":"Suma indica sumar (+). Diferencia indica restar (−)."},{"en":"Product means multiply (×). Quotient means divide (÷).","es":"Producto indica multiplicar (×). Cociente indica dividir (÷)."}],"example":{"en":"The difference of 9 and 4 is 9 − 4 = 5. The quotient of 9 and 3 is 9 ÷ 3 = 3.","es":"La diferencia de 9 y 4 es 9 − 4 = 5. El cociente de 9 y 3 es 9 ÷ 3 = 3."},"model":{"kind":"numberline","data":{"min":0,"max":10,"step":1,"points":[{"value":4,"label":"4","kind":"given"},{"value":9,"label":"9 − 4 = 5","kind":"answer"}]},"alt":{"en":"A number line from 0 to 10 with dots at 4 and 9. The gap between them is the difference, 5.","es":"Una recta numérica de 0 a 10 con puntos en 4 y 9. El espacio entre ellos es la diferencia, 5."}},"check":{"q":{"en":"What is the product of 6 and 4?","es":"¿Cuál es el producto de 6 y 4?"},"options":["10","24","2"],"correctIdx":1,"calc":{"expr":"6 × 4","value":"24"},"feedback":[{"en":"10 is the sum, 6 + 4. Product means multiply: 6 × 4.","es":"10 es la suma, 6 + 4. Producto significa multiplicar: 6 × 4."},{"en":"Yes. Product means multiply, and 6 × 4 = 24.","es":"Sí. Producto significa multiplicar, y 6 × 4 = 24."},{"en":"2 is the difference, 6 − 4. Product means multiply instead.","es":"2 es la diferencia, 6 − 4. Producto significa multiplicar."}]}},{"name":{"en":"Put a number in for a letter","es":"Sustituir una letra por un número"},"why":{"en":"Tonight you evaluate expressions by putting the given number in for the variable.","es":"Hoy evalúas expresiones sustituyendo la variable por el número dado."},"steps":[{"en":"Rewrite the expression with the number in place of the letter.","es":"Vuelve a escribir la expresión con el número en lugar de la letra."},{"en":"A number next to a letter, like 4n, means multiply: 4 × n.","es":"Un número junto a una letra, como 4n, significa multiplicar: 4 × n."},{"en":"Then do the math.","es":"Después haz las operaciones."}],"example":{"en":"If n = 3, then 2n + 1 = 2 × 3 + 1 = 7.","es":"Si n = 3, entonces 2n + 1 = 2 × 3 + 1 = 7."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"2 × 3 + 1"},{"rule":"MD","expr":"6 + 1"},{"rule":"AS","expr":"7"}]},"alt":{"en":"With n = 3, 2n + 1 is written 2 × 3 + 1, then 6 + 1, then 7.","es":"Con n = 3, 2n + 1 se escribe 2 × 3 + 1, luego 6 + 1 y luego 7."}},"check":{"q":{"en":"What is 4n when n = 6?","es":"¿Cuánto vale 4n cuando n = 6?"},"options":["46","10","24"],"correctIdx":2,"calc":{"expr":"4 × 6","value":"24"},"feedback":[{"en":"46 writes the digits side by side. 4n means 4 × n, so 4 × 6.","es":"46 pone las cifras una al lado de la otra. 4n significa 4 × n, o sea 4 × 6."},{"en":"10 adds 4 + 6. A number next to a letter means multiply.","es":"10 suma 4 + 6. Un número junto a una letra significa multiplicar."},{"en":"Yes. 4n means 4 × n, and 4 × 6 = 24.","es":"Sí. 4n significa 4 × n, y 4 × 6 = 24."}]}}]},"6-6":{"skills":[{"name":{"en":"Test an expression with a number","es":"Probar una expresión con un número"},"why":{"en":"Tonight you check whether two expressions are equivalent, and testing a number in each is a quick check.","es":"Hoy compruebas si dos expresiones son equivalentes, y probar un número en cada una es una revisión rápida."},"steps":[{"en":"Pick a number for the letter.","es":"Elige un número para la letra."},{"en":"Put it into each expression and find both values.","es":"Sustitúyelo en cada expresión y halla los dos valores."},{"en":"Different values mean the expressions are not equivalent.","es":"Si los valores son distintos, las expresiones no son equivalentes."}],"example":{"en":"x + x and 2x with x = 3: 3 + 3 = 6 and 2 × 3 = 6. They match.","es":"x + x y 2x con x = 3: 3 + 3 = 6 y 2 × 3 = 6. Coinciden."},"model":{"kind":"balance","data":{"left":["3","3"],"right":["2 × 3"],"unknown":null},"alt":{"en":"A level balance. The left pan holds 3 and 3, for x + x. The right pan holds 2 × 3, for 2x.","es":"Una balanza en equilibrio. El platillo izquierdo tiene 3 y 3, por x + x. El derecho tiene 2 × 3, por 2x."}},"check":{"q":{"en":"What is 3x + 2 when x = 4?","es":"¿Cuánto vale 3x + 2 cuando x = 4?"},"options":["14","9","36"],"correctIdx":0,"calc":{"expr":"3 × 4 + 2","value":"14"},"feedback":[{"en":"Yes. 3 × 4 = 12, then 12 + 2 = 14.","es":"Sí. 3 × 4 = 12, y luego 12 + 2 = 14."},{"en":"9 adds 3 + 4 + 2. 3x means 3 × x, so multiply 3 × 4 first.","es":"9 suma 3 + 4 + 2. 3x significa 3 × x, así que primero multiplica 3 × 4."},{"en":"36 reads 3x as 34. 3x means 3 × 4 = 12, then add 2.","es":"36 lee 3x como 34. 3x significa 3 × 4 = 12; luego suma 2."}]}},{"name":{"en":"Order does not change a sum or product","es":"El orden no cambia una suma ni un producto"},"why":{"en":"Tonight's equivalent expressions often just swap the order, like x + 2 and 2 + x.","es":"Las expresiones equivalentes de hoy muchas veces solo cambian el orden, como x + 2 y 2 + x."},"steps":[{"en":"When you add, swap the numbers and the total stays the same.","es":"Al sumar, cambia el orden de los números y el total no cambia."},{"en":"When you multiply, swap the numbers and the product stays the same.","es":"Al multiplicar, cambia el orden y el producto no cambia."},{"en":"This does not work for subtraction or division.","es":"Esto no funciona con la resta ni con la división."}],"example":{"en":"3 + 8 = 8 + 3 = 11 and 4 × 6 = 6 × 4 = 24. Subtraction cannot swap.","es":"3 + 8 = 8 + 3 = 11 y 4 × 6 = 6 × 4 = 24. En la resta no se puede cambiar el orden."},"model":{"kind":"grid","data":{"rows":4,"cols":6,"filled":24,"groupSize":10,"label":"4 × 6 = 6 × 4 = 24"},"alt":{"en":"An array of 4 rows of 6. Turned sideways it is 6 rows of 4. Both have 24 squares.","es":"Un arreglo de 4 filas de 6. Si lo giras, son 6 filas de 4. Los dos tienen 24 cuadros."}},"check":{"q":{"en":"Fill in the blank: 5 × 7 = 7 × ?","es":"Completa: 5 × 7 = 7 × ?"},"options":["7","5","35"],"correctIdx":1,"calc":{"expr":"35 ÷ 7","value":"5"},"feedback":[{"en":"The 7 is already there. Swapping the order brings the 5 to the other side.","es":"El 7 ya está. Al cambiar el orden, el 5 pasa al otro lado."},{"en":"Yes. Swapping the factors keeps the product: both equal 35.","es":"Sí. Cambiar el orden de los factores no cambia el producto: los dos dan 35."},{"en":"35 is the product. The blank needs the missing factor, 5.","es":"35 es el producto. En el espacio va el factor que falta, 5."}]}}]},"6-7":{"skills":[{"name":{"en":"Find factor pairs of a number","es":"Hallar los pares de factores de un número"},"why":{"en":"Tonight's greatest common factor starts with listing every factor of each number.","es":"El máximo común divisor de hoy empieza con la lista de todos los factores de cada número."},"steps":[{"en":"Start with 1 times the number.","es":"Empieza con 1 por el número."},{"en":"Try 2, 3, 4, and so on. Keep each one that divides evenly.","es":"Prueba 2, 3, 4, etc. Guarda cada uno que divide exacto."},{"en":"Stop when the pairs start to repeat.","es":"Detente cuando los pares empiecen a repetirse."}],"example":{"en":"12: 1 × 12, 2 × 6, 3 × 4. The factors are 1, 2, 3, 4, 6, 12.","es":"12: 1 × 12, 2 × 6, 3 × 4. Los factores son 1, 2, 3, 4, 6 y 12."},"model":{"kind":"grid","data":{"rows":3,"cols":4,"filled":12,"groupSize":10,"label":"3 × 4 = 12"},"alt":{"en":"An array of 3 rows of 4 squares. It shows the factor pair 3 × 4 = 12.","es":"Un arreglo de 3 filas de 4 cuadros. Muestra el par de factores 3 × 4 = 12."}},"check":{"q":{"en":"Which number pairs with 4 to make 20?","es":"¿Qué número forma pareja con el 4 para dar 20?"},"options":["16","5","24"],"correctIdx":1,"calc":{"expr":"20 ÷ 4","value":"5"},"feedback":[{"en":"16 subtracts: 20 − 4. A factor pair multiplies: 4 × ? = 20.","es":"16 es una resta: 20 − 4. Un par de factores se multiplica: 4 × ? = 20."},{"en":"Yes. 4 × 5 = 20, so 4 and 5 are a factor pair.","es":"Sí. 4 × 5 = 20, así que 4 y 5 son un par de factores."},{"en":"24 adds 20 + 4. Find the number that times 4 makes 20.","es":"24 es la suma 20 + 4. Busca el número que por 4 da 20."}]}},{"name":{"en":"List multiples by skip-counting","es":"Hacer la lista de múltiplos contando de tanto en tanto"},"why":{"en":"Tonight's least common multiple comes from comparing lists of multiples.","es":"El mínimo común múltiplo de hoy sale de comparar listas de múltiplos."},"steps":[{"en":"Start with the number itself.","es":"Empieza con el mismo número."},{"en":"Add that number again each time: that is skip-counting.","es":"Suma ese número otra vez cada vez: así cuentas de tanto en tanto."}],"example":{"en":"Multiples of 4: 4, 8, 12, 16, 20.","es":"Múltiplos de 4: 4, 8, 12, 16 y 20."},"model":{"kind":"numberline","data":{"min":0,"max":20,"step":4,"points":[{"value":4,"label":"4","kind":"given"},{"value":8,"label":"8","kind":"given"},{"value":12,"label":"12","kind":"given"},{"value":16,"label":"16","kind":"given"},{"value":20,"label":"20","kind":"given"}]},"alt":{"en":"A number line from 0 to 20 with jumps of 4. Dots sit on 4, 8, 12, 16 and 20.","es":"Una recta numérica de 0 a 20 con saltos de 4. Hay puntos en 4, 8, 12, 16 y 20."}},"check":{"q":{"en":"Skip-count by 6: 6, 12, 18, ... What comes next?","es":"Cuenta de 6 en 6: 6, 12, 18, ... ¿Qué número sigue?"},"options":["19","30","24"],"correctIdx":2,"calc":{"expr":"6 × 4","value":"24"},"feedback":[{"en":"19 adds only 1. Each step adds 6: 18 + 6.","es":"19 suma solo 1. Cada paso suma 6: 18 + 6."},{"en":"30 skips a number. 18 + 6 = 24 comes first.","es":"30 se salta un número. Primero viene 18 + 6 = 24."},{"en":"Yes. 18 + 6 = 24, and 24 = 6 × 4.","es":"Sí. 18 + 6 = 24, y 24 = 6 × 4."}]}}]},"6-8":{"skills":[{"name":{"en":"Adding 0 and multiplying by 1","es":"Sumar 0 y multiplicar por 1"},"why":{"en":"Tonight's identity property is built on these facts: adding 0 or multiplying by 1 keeps a number the same.","es":"La propiedad de identidad de hoy se basa en esto: sumar 0 o multiplicar por 1 no cambia el número."},"steps":[{"en":"Any number plus 0 is that same number.","es":"Cualquier número más 0 da el mismo número."},{"en":"Any number times 1 is that same number.","es":"Cualquier número por 1 da el mismo número."},{"en":"Careful: a number times 0 is 0.","es":"Cuidado: un número por 0 da 0."}],"example":{"en":"8 + 0 = 8 and 9 × 1 = 9, but 9 × 0 = 0.","es":"8 + 0 = 8 y 9 × 1 = 9, pero 9 × 0 = 0."},"model":{"kind":"grid","data":{"rows":1,"cols":9,"filled":9,"groupSize":10,"label":"9 × 1 = 9"},"alt":{"en":"One row of 9 squares. One group of 9 is still 9.","es":"Una fila de 9 cuadros. Un grupo de 9 sigue siendo 9."}},"check":{"q":{"en":"What is 18 × 1?","es":"¿Cuánto es 18 × 1?"},"options":["19","0","18"],"correctIdx":2,"calc":{"expr":"18 × 1","value":"18"},"feedback":[{"en":"19 adds 1. Times 1 means one group of 18, which is 18.","es":"19 suma 1. Por 1 significa un grupo de 18, o sea 18."},{"en":"0 is the rule for times 0. Times 1 keeps the number: 18.","es":"0 es la regla de multiplicar por 0. Por 1 deja el número igual: 18."},{"en":"Yes. Multiplying by 1 keeps 18 the same.","es":"Sí. Multiplicar por 1 deja el 18 igual."}]}},{"name":{"en":"Group numbers in a friendly order","es":"Agrupar números en un orden fácil"},"why":{"en":"Tonight's commutative and associative properties let you reorder and regroup to make the math easier.","es":"Las propiedades conmutativa y asociativa de hoy te dejan cambiar el orden y agrupar para facilitar las cuentas."},"steps":[{"en":"When you only add, or only multiply, you can change the order.","es":"Si solo sumas, o solo multiplicas, puedes cambiar el orden."},{"en":"Look for pairs that make 10 or 100, and do them first.","es":"Busca pares que den 10 o 100 y hazlos primero."}],"example":{"en":"25 × 3 × 4: do 25 × 4 = 100 first, then 100 × 3 = 300.","es":"25 × 3 × 4: haz primero 25 × 4 = 100, y luego 100 × 3 = 300."},"model":{"kind":"order","data":{"steps":[{"rule":"start","expr":"(25 × 4) × 3"},{"rule":"P","expr":"100 × 3"},{"rule":"MD","expr":"300"}]},"alt":{"en":"The friendly pair 25 × 4 is grouped first and makes 100. Then 100 × 3 = 300.","es":"El par fácil 25 × 4 se agrupa primero y da 100. Luego 100 × 3 = 300."}},"check":{"q":{"en":"Use a friendly order: 25 × 7 × 4. What is the product?","es":"Usa un orden fácil: 25 × 7 × 4. ¿Cuál es el producto?"},"options":["175","700","36"],"correctIdx":1,"calc":{"expr":"25 × 7 × 4","value":"700"},"feedback":[{"en":"175 is only 25 × 7. Multiply by the 4 too: 25 × 4 = 100, then 100 × 7.","es":"175 es solo 25 × 7. Multiplica también por 4: 25 × 4 = 100 y luego 100 × 7."},{"en":"Yes. 25 × 4 = 100, and 100 × 7 = 700.","es":"Sí. 25 × 4 = 100, y 100 × 7 = 700."},{"en":"36 adds 25 + 7 + 4. The × signs mean multiply.","es":"36 suma 25 + 7 + 4. Los signos × piden multiplicar."}]}}]},"6-9":{"skills":[{"name":{"en":"Count unit fractions in several wholes","es":"Contar fracciones unitarias en varios enteros"},"why":{"en":"Tonight 3 ÷ 1/4 asks how many fourths fit in 3 wholes.","es":"Hoy 3 ÷ 1/4 pregunta cuántos cuartos caben en 3 enteros."},"steps":[{"en":"The denominator tells how many pieces fit in 1 whole.","es":"El denominador dice cuántas partes caben en 1 entero."},{"en":"Multiply by the number of wholes.","es":"Multiplica por la cantidad de enteros."}],"example":{"en":"Halves in 3 wholes: 2 halves in each whole, so 3 × 2 = 6 halves.","es":"Medios en 3 enteros: 2 medios en cada entero, así que 3 × 2 = 6 medios."},"model":{"kind":"numberline","data":{"min":0,"max":3,"step":0.5,"points":[{"value":3,"label":{"en":"6 halves","es":"6 medios"},"kind":"answer"}]},"alt":{"en":"A number line from 0 to 3 marked in halves. There are 6 half-jumps from 0 to 3.","es":"Una recta numérica de 0 a 3 marcada en medios. Hay 6 saltos de un medio del 0 al 3."}},"check":{"q":{"en":"How many 1/4 pieces fit in 3 wholes?","es":"¿Cuántas partes de 1/4 caben en 3 enteros?"},"options":["3/4","12","7"],"correctIdx":1,"calc":{"expr":"3 × 4","value":"12"},"feedback":[{"en":"3/4 is three pieces of 1/4, less than 1 whole. Count all the fourths in 3 wholes.","es":"3/4 son solo tres partes de 1/4, menos de 1 entero. Cuenta todos los cuartos en 3 enteros."},{"en":"Yes. 4 fourths in each whole, and 3 × 4 = 12.","es":"Sí. Hay 4 cuartos en cada entero, y 3 × 4 = 12."},{"en":"7 adds 3 + 4. Each of the 3 wholes holds 4 fourths, so multiply.","es":"7 suma 3 + 4. Cada uno de los 3 enteros tiene 4 cuartos, así que multiplica."}]}},{"name":{"en":"Find the reciprocal of a fraction","es":"Hallar el recíproco de una fracción"},"why":{"en":"Tonight you can divide a whole number by a fraction by multiplying by its reciprocal.","es":"Hoy puedes dividir un número entero entre una fracción multiplicando por su recíproco."},"steps":[{"en":"Swap the numerator and the denominator.","es":"Intercambia el numerador y el denominador."},{"en":"Check: a number times its reciprocal equals 1.","es":"Comprueba: un número por su recíproco da 1."}],"example":{"en":"The reciprocal of 1/4 is 4/1, or 4, because 1/4 × 4 = 1.","es":"El recíproco de 1/4 es 4/1, o sea 4, porque 1/4 × 4 = 1."},"model":{"kind":"kcf","data":{"dividend":"1","divisor":"1/4"},"alt":{"en":"Keep, Change, Flip for 1 ÷ 1/4: 1/4 flips to 4/1, and 1 × 4/1 = 4.","es":"Mantener, Cambiar, Invertir para 1 ÷ 1/4: 1/4 se invierte a 4/1, y 1 × 4/1 = 4."}},"check":{"q":{"en":"What is the reciprocal of 5/3?","es":"¿Cuál es el recíproco de 5/3?"},"options":["3/5","5/3","1 2/3"],"correctIdx":0,"calc":{"expr":"1 ÷ (5/3)","value":"3/5"},"feedback":[{"en":"Yes. The 5 and the 3 trade places, and 5/3 × 3/5 = 1.","es":"Sí. El 5 y el 3 cambian de lugar, y 5/3 × 3/5 = 1."},{"en":"That is the same fraction. Swap the top and the bottom.","es":"Es la misma fracción. Intercambia el número de arriba y el de abajo."},{"en":"1 2/3 is 5/3 written as a mixed number. Flip 5/3 instead.","es":"1 2/3 es 5/3 escrito como número mixto. Mejor invierte 5/3."}]}}]},"7-1":{"skills":[{"name":{"en":"Numbers grow to the right on a number line","es":"En la recta numérica, los números crecen hacia la derecha"},"why":{"en":"Tonight negative numbers go left of 0, so you need to know which way means greater.","es":"Hoy los números negativos van a la izquierda del 0, así que necesitas saber qué dirección indica mayor."},"steps":[{"en":"0 is the starting point.","es":"El 0 es el punto de partida."},{"en":"Moving right, numbers get greater. Moving left, they get smaller.","es":"Hacia la derecha, los números son mayores. Hacia la izquierda, son menores."}],"example":{"en":"5 is right of 2, so 5 is greater than 2.","es":"El 5 está a la derecha del 2, así que 5 es mayor que 2."},"model":{"kind":"numberline","data":{"min":0,"max":6,"step":1,"points":[{"value":2,"label":"2","kind":"given"},{"value":5,"label":"5","kind":"given"}]},"alt":{"en":"A number line from 0 to 6 with dots at 2 and 5. The 5 is farther right, so it is greater.","es":"Una recta numérica de 0 a 6 con puntos en 2 y 5. El 5 está más a la derecha, así que es mayor."}},"check":{"q":{"en":"Which number is farthest right on a number line?","es":"¿Qué número está más a la derecha en la recta numérica?"},"options":["19","9","15"],"correctIdx":0,"calc":{"expr":"20 - 1","value":"19"},"feedback":[{"en":"Yes. 19 is the greatest, so it sits farthest right.","es":"Sí. 19 es el mayor, así que está más a la derecha."},{"en":"9 is the smallest here, so it sits farthest left. Look for the greatest number.","es":"9 es el menor de estos, así que está más a la izquierda. Busca el mayor."},{"en":"15 is right of 9 but left of 19. The greatest number is farthest right.","es":"15 está a la derecha del 9 pero a la izquierda del 19. El mayor está más a la derecha."}]}},{"name":{"en":"Count the distance between two numbers","es":"Contar la distancia entre dos números"},"why":{"en":"Tonight opposites sit the same distance from 0, so you count steps from 0.","es":"Hoy los opuestos están a la misma distancia del 0, así que cuentas los pasos desde el 0."},"steps":[{"en":"Start at one number on the number line.","es":"Empieza en un número de la recta numérica."},{"en":"Count the jumps, not the tick marks, to the other number.","es":"Cuenta los saltos, no las marcas, hasta el otro número."}],"example":{"en":"From 0 to 4 is 4 jumps: 0 to 1, 1 to 2, 2 to 3, 3 to 4.","es":"Del 0 al 4 hay 4 saltos: del 0 al 1, del 1 al 2, del 2 al 3 y del 3 al 4."},"model":{"kind":"numberline","data":{"min":0,"max":5,"step":1,"points":[{"value":0,"label":{"en":"start","es":"inicio"},"kind":"given"},{"value":4,"label":{"en":"4 jumps","es":"4 saltos"},"kind":"answer"}]},"alt":{"en":"A number line from 0 to 5. Four jumps go from 0 to 4.","es":"Una recta numérica de 0 a 5. Cuatro saltos van del 0 al 4."}},"check":{"q":{"en":"How many steps is it from 3 to 10 on a number line?","es":"¿Cuántos pasos hay del 3 al 10 en la recta numérica?"},"options":["13","7","8"],"correctIdx":1,"calc":{"expr":"10 - 3","value":"7"},"feedback":[{"en":"13 adds 3 + 10. Distance subtracts: 10 − 3.","es":"13 suma 3 + 10. La distancia se halla restando: 10 − 3."},{"en":"Yes. 10 − 3 = 7 jumps.","es":"Sí. 10 − 3 = 7 saltos."},{"en":"8 counts the tick marks, including 3. Count the jumps between marks.","es":"8 cuenta las marcas, incluido el 3. Cuenta los saltos entre las marcas."}]}}]},"7-2":{"skills":[{"name":{"en":"Find a fraction between whole numbers","es":"Ubicar una fracción entre números enteros"},"why":{"en":"Tonight you place fractions and decimals, like −2.5, between the integers on a number line.","es":"Hoy ubicas fracciones y decimales, como −2.5, entre los números enteros de la recta numérica."},"steps":[{"en":"Find the two whole numbers it falls between.","es":"Busca los dos números enteros entre los que está."},{"en":"Split that space into equal parts, using the denominator.","es":"Divide ese espacio en partes iguales según el denominador."},{"en":"Count the parts from the smaller whole number.","es":"Cuenta las partes desde el número entero menor."}],"example":{"en":"2 1/2: go to 2, then halfway toward 3.","es":"2 1/2: ve al 2 y luego avanza la mitad del camino hacia el 3."},"model":{"kind":"numberline","data":{"min":0,"max":3,"step":0.5,"points":[{"value":2.5,"label":"2 1/2","kind":"answer"}]},"alt":{"en":"A number line from 0 to 3 marked in halves. A dot sits halfway between 2 and 3.","es":"Una recta numérica de 0 a 3 marcada en medios. Un punto está a la mitad entre 2 y 3."}},"check":{"q":{"en":"What number is halfway between 3 and 4?","es":"¿Qué número está a la mitad entre 3 y 4?"},"options":["1/2","3 1/2","4 1/2"],"correctIdx":1,"calc":{"expr":"3 + 1/2","value":"3 1/2"},"feedback":[{"en":"1/2 is halfway between 0 and 1. Start at 3, then add the half.","es":"1/2 está a la mitad entre 0 y 1. Empieza en 3 y suma la mitad."},{"en":"Yes. Start at 3 and go half of the way to 4.","es":"Sí. Empieza en 3 y avanza la mitad del camino hacia 4."},{"en":"4 1/2 is past 4. Halfway between 3 and 4 is 3 1/2.","es":"4 1/2 está después del 4. La mitad entre 3 y 4 es 3 1/2."}]}},{"name":{"en":"Match a fraction to its decimal","es":"Relacionar una fracción con su decimal"},"why":{"en":"Tonight's number lines mix fractions and decimals, so 1/2 and 0.5 must mean the same spot.","es":"Las rectas numéricas de hoy mezclan fracciones y decimales, así que 1/2 y 0.5 deben indicar el mismo punto."},"steps":[{"en":"Divide the numerator by the denominator.","es":"Divide el numerador entre el denominador."},{"en":"Or rename the fraction with a denominator of 10 or 100.","es":"O escribe la fracción con denominador 10 o 100."}],"example":{"en":"1/4 = 25/100 = 0.25, and 1/2 = 5/10 = 0.5.","es":"1/4 = 25/100 = 0.25, y 1/2 = 5/10 = 0.5."},"model":{"kind":"numberline","data":{"min":0,"max":0.5,"step":0.25,"points":[{"value":0.25,"label":"1/4 = 0.25","kind":"given"},{"value":0.5,"label":"1/2 = 0.5","kind":"given"}]},"alt":{"en":"A number line from 0 to 0.5. The point 1/4 sits at 0.25 and 1/2 sits at 0.5.","es":"Una recta numérica de 0 a 0.5. El punto 1/4 está en 0.25 y 1/2 está en 0.5."}},"check":{"q":{"en":"Which decimal equals 3/4?","es":"¿Qué decimal es igual a 3/4?"},"options":["0.34","3.4","0.75"],"correctIdx":2,"calc":{"expr":"3 ÷ 4","value":"0.75"},"feedback":[{"en":"0.34 just writes the digits after a point. Rename 3/4 as 75/100.","es":"0.34 solo pone las cifras después de un punto. Escribe 3/4 como 75/100."},{"en":"3.4 is more than 3, but 3/4 is less than 1. Divide 3 ÷ 4.","es":"3.4 es mayor que 3, pero 3/4 es menor que 1. Divide 3 ÷ 4."},{"en":"Yes. 3/4 = 75/100 = 0.75.","es":"Sí. 3/4 = 75/100 = 0.75."}]}}]},"7-3":{"skills":[{"name":{"en":"Opposites sit on both sides of 0","es":"Los opuestos están a ambos lados del 0"},"why":{"en":"Tonight 6 and −6 have the same absolute value because they are opposites.","es":"Hoy 6 y −6 tienen el mismo valor absoluto porque son opuestos."},"steps":[{"en":"Opposites are the same distance from 0.","es":"Los opuestos están a la misma distancia del 0."},{"en":"They sit on different sides, so one has a negative sign.","es":"Están en lados distintos, así que uno lleva signo negativo."}],"example":{"en":"The opposite of 5 is −5. Both are 5 steps from 0.","es":"El opuesto de 5 es −5. Los dos están a 5 pasos del 0."},"model":{"kind":"numberline","data":{"min":-6,"max":6,"step":1,"points":[{"value":-5,"label":"−5","kind":"given"},{"value":5,"label":"5","kind":"given"}]},"alt":{"en":"A number line from −6 to 6 with dots at −5 and 5. Each is 5 steps from 0, on opposite sides.","es":"Una recta numérica de −6 a 6 con puntos en −5 y 5. Cada uno está a 5 pasos del 0, en lados opuestos."}},"check":{"q":{"en":"What is the opposite of 9?","es":"¿Cuál es el opuesto de 9?"},"options":["9","1/9","-9"],"correctIdx":2,"calc":{"expr":"0 - 9","value":"-9"},"feedback":[{"en":"9 is the same number. The opposite is on the other side of 0.","es":"9 es el mismo número. El opuesto está del otro lado del 0."},{"en":"1/9 is the reciprocal, not the opposite. Keep 9 and change the sign.","es":"1/9 es el recíproco, no el opuesto. Deja el 9 y cambia el signo."},{"en":"Yes. −9 is 9 steps left of 0, and 9 is 9 steps right.","es":"Sí. −9 está 9 pasos a la izquierda del 0, y 9 está 9 pasos a la derecha."}]}},{"name":{"en":"Count steps from a negative number to 0","es":"Contar los pasos de un número negativo al 0"},"why":{"en":"Tonight absolute value is the distance from 0, counted the same in either direction.","es":"Hoy el valor absoluto es la distancia al 0, que se cuenta igual en cualquier dirección."},"steps":[{"en":"Find the number on the number line.","es":"Busca el número en la recta numérica."},{"en":"Count the jumps to 0. A distance is never negative.","es":"Cuenta los saltos hasta el 0. Una distancia nunca es negativa."}],"example":{"en":"−3 is 3 jumps from 0: −3 to −2, −2 to −1, −1 to 0.","es":"−3 está a 3 saltos del 0: de −3 a −2, de −2 a −1 y de −1 a 0."},"model":{"kind":"numberline","data":{"min":-5,"max":1,"step":1,"points":[{"value":-3,"label":"−3","kind":"given"},{"value":0,"label":{"en":"3 jumps","es":"3 saltos"},"kind":"answer"}]},"alt":{"en":"A number line from −5 to 1. Three jumps go from −3 to 0.","es":"Una recta numérica de −5 a 1. Tres saltos van de −3 a 0."}},"check":{"q":{"en":"How many steps is it from −4 to 0?","es":"¿Cuántos pasos hay de −4 a 0?"},"options":["-4","4","5"],"correctIdx":1,"calc":{"expr":"4 - 0","value":"4"},"feedback":[{"en":"A distance is never negative. Count the jumps: there are 4.","es":"Una distancia nunca es negativa. Cuenta los saltos: son 4."},{"en":"Yes. −4 is 4 jumps left of 0, so the distance is 4.","es":"Sí. −4 está a 4 saltos a la izquierda del 0, así que la distancia es 4."},{"en":"5 counts the tick marks, including −4. Count the jumps between marks.","es":"5 cuenta las marcas, incluido el −4. Cuenta los saltos entre las marcas."}]}}]},"7-4":{"skills":[{"name":{"en":"Moving right on a number line","es":"Moverse a la derecha en la recta numérica"},"why":{"en":"Tonight you compare integers, and the number farther right on a number line is always greater.","es":"Hoy comparas números enteros, y el número que está más a la derecha en la recta numérica siempre es mayor."},"steps":[{"en":"Numbers grow as you move right.","es":"Los números crecen cuando te mueves a la derecha."},{"en":"Numbers shrink as you move left, even past 0.","es":"Los números se hacen más pequeños cuando te mueves a la izquierda, incluso después del 0."}],"example":{"en":"Start at 1 and move 4 steps right: you land on 5, and 5 is greater than 1.","es":"Empieza en 1 y avanza 4 pasos a la derecha: llegas a 5, y 5 es mayor que 1."},"check":{"q":{"en":"Start at 2 and move 5 steps right. Where do you land?","es":"Empieza en 2 y avanza 5 pasos a la derecha. ¿Dónde llegas?"},"options":["5","-3","7"],"correctIdx":2,"calc":{"expr":"2 + 5","value":"7"},"feedback":[{"en":"5 counts only the steps. Start at 2, then add the 5 steps.","es":"5 cuenta solo los pasos. Empieza en 2 y luego suma los 5 pasos."},{"en":"-3 means you moved left. Moving right makes the number bigger.","es":"-3 significa que te moviste a la izquierda. Moverte a la derecha hace el número más grande."},{"en":"Yes. 2 + 5 = 7, and 7 is to the right of 2.","es":"Sí. 2 + 5 = 7, y 7 está a la derecha de 2."}]},"model":{"kind":"numberline","data":{"min":0,"max":6,"step":1,"points":[{"value":1,"label":"start","kind":"given"},{"value":5,"label":{"en":"4 steps right","es":"4 pasos a la derecha"},"kind":"answer"}],"unit":null},"alt":{"en":"A number line from 0 to 6. A jump starts at 1 and moves 4 steps right to 5.","es":"Una recta numérica del 0 al 6. Un salto empieza en 1 y avanza 4 pasos a la derecha hasta 5."}}},{"name":{"en":"Opposites: same distance from 0","es":"Los opuestos: misma distancia del 0"},"why":{"en":"Negative numbers are the opposites of positive numbers, placed left of 0, which helps you compare them tonight.","es":"Los números negativos son los opuestos de los positivos y están a la izquierda del 0; eso te ayuda a compararlos hoy."},"steps":[{"en":"Find how far the number is from 0.","es":"Halla a qué distancia del 0 está el número."},{"en":"Go the same distance on the other side of 0.","es":"Avanza la misma distancia al otro lado del 0."},{"en":"Positive turns negative; negative turns positive.","es":"El positivo se vuelve negativo; el negativo se vuelve positivo."}],"example":{"en":"3 is 3 steps right of 0, so its opposite, −3, is 3 steps left.","es":"El 3 está 3 pasos a la derecha del 0, así que su opuesto, −3, está 3 pasos a la izquierda."},"check":{"q":{"en":"What is the opposite of 6?","es":"¿Cuál es el opuesto de 6?"},"options":["-6","1/6","6"],"correctIdx":0,"calc":{"expr":"0 - 6","value":"-6"},"feedback":[{"en":"Yes. 6 is 6 steps right of 0, so −6 is 6 steps left.","es":"Sí. El 6 está 6 pasos a la derecha del 0, así que −6 está 6 pasos a la izquierda."},{"en":"1/6 is the flip of 6. The opposite keeps 6 but changes the sign.","es":"1/6 es el 6 invertido. El opuesto mantiene el 6 pero cambia el signo."},{"en":"6 is the same number. Go to the other side of 0.","es":"6 es el mismo número. Pasa al otro lado del 0."}]},"model":{"kind":"numberline","data":{"min":-4,"max":4,"step":1,"points":[{"value":3,"label":"3","kind":"given"},{"value":-3,"label":"−3","kind":"answer"}],"unit":null},"alt":{"en":"A number line from −4 to 4. The numbers 3 and −3 sit 3 steps from 0 on opposite sides.","es":"Una recta numérica de −4 a 4. Los números 3 y −3 están a 3 pasos del 0, en lados opuestos."}}}]},"7-5":{"skills":[{"name":{"en":"Read an ordered pair: across, then up","es":"Leer un par ordenado: primero de lado, luego arriba"},"why":{"en":"Every point you plot tonight is named by an ordered pair, and the order tells which way to move first.","es":"Cada punto que ubicas hoy tiene un par ordenado, y el orden te dice hacia dónde moverte primero."},"steps":[{"en":"Start at the origin, (0, 0).","es":"Empieza en el origen, (0, 0)."},{"en":"The first number, x, moves you right.","es":"El primer número, x, te mueve a la derecha."},{"en":"The second number, y, moves you up.","es":"El segundo número, y, te mueve hacia arriba."}],"example":{"en":"(5, 4): move 5 units right, then 4 units up, and mark the point.","es":"(5, 4): muévete 5 unidades a la derecha, luego 4 unidades hacia arriba, y marca el punto."},"check":{"q":{"en":"A point is 3 units right and 6 units up. What is its x-coordinate?","es":"Un punto está 3 unidades a la derecha y 6 hacia arriba. ¿Cuál es su coordenada x?"},"options":["6","3","9"],"correctIdx":1,"calc":{"expr":"3","value":"3"},"feedback":[{"en":"6 is the move up, the y-coordinate. The x-coordinate is the move right.","es":"6 es el movimiento hacia arriba, la coordenada y. La coordenada x es el movimiento a la derecha."},{"en":"Yes. Across comes first, so x = 3, and the point is (3, 6).","es":"Sí. El movimiento de lado va primero, así que x = 3 y el punto es (3, 6)."},{"en":"9 adds both moves. Each move is its own coordinate.","es":"9 suma los dos movimientos. Cada movimiento es su propia coordenada."}]},"model":{"kind":"coord","data":{"xmax":6,"ymax":6,"points":[{"x":5,"y":4,"label":"(5, 4)"}],"quadrants":false},"alt":{"en":"A grid with one point at (5, 4): 5 units right of the origin and 4 units up.","es":"Una cuadrícula con un punto en (5, 4): 5 unidades a la derecha del origen y 4 hacia arriba."}}},{"name":{"en":"Place negatives and decimals on a number line","es":"Ubicar negativos y decimales en la recta numérica"},"why":{"en":"Tonight's coordinates include numbers like −2.5, so you need to find them on each number line.","es":"Las coordenadas de hoy incluyen números como −2.5, así que necesitas hallarlos en cada recta numérica."},"steps":[{"en":"Negative numbers are left of 0, or below 0 on the up-down line.","es":"Los números negativos están a la izquierda del 0, o debajo del 0 en la recta vertical."},{"en":"A number ending in .5 sits halfway between two whole numbers.","es":"Un número que termina en .5 está a la mitad entre dos números enteros."}],"example":{"en":"−2.5 sits halfway between −2 and −3, to the left of 0.","es":"−2.5 está a la mitad entre −2 y −3, a la izquierda del 0."},"check":{"q":{"en":"What number is halfway between −1 and −2?","es":"¿Qué número está a la mitad entre −1 y −2?"},"options":["1.5","-1.2","-1.5"],"correctIdx":2,"calc":{"expr":"(-1 - 2) / 2","value":"-1.5"},"feedback":[{"en":"1.5 is right of 0. Between −1 and −2 you are left of 0, so it is negative.","es":"1.5 está a la derecha del 0. Entre −1 y −2 estás a la izquierda del 0, así que es negativo."},{"en":"−1.2 is closer to −1. Halfway is 5 tenths from each, so −1.5.","es":"−1.2 está más cerca de −1. La mitad está a 5 décimas de cada uno: −1.5."},{"en":"Yes. −1.5 is halfway between −1 and −2.","es":"Sí. −1.5 está justo a la mitad entre −1 y −2."}]},"model":{"kind":"numberline","data":{"min":-4,"max":1,"step":0.5,"points":[{"value":-3,"label":"−3","kind":"given"},{"value":-2.5,"label":"−2.5","kind":"answer"},{"value":-2,"label":"−2","kind":"given"}],"unit":null},"alt":{"en":"A number line from −4 to 1 marked every half. −2.5 sits halfway between −3 and −2.","es":"Una recta numérica de −4 a 1 marcada cada media unidad. −2.5 está a la mitad entre −3 y −2."}}}]},"7-6":{"skills":[{"name":{"en":"Absolute value: distance from 0","es":"El valor absoluto: la distancia desde 0"},"why":{"en":"Tonight you find distance between points using absolute value, which counts how far a number is from 0.","es":"Hoy hallas la distancia entre puntos con el valor absoluto, que cuenta qué tan lejos del 0 está un número."},"steps":[{"en":"Find the number on the number line.","es":"Halla el número en la recta numérica."},{"en":"Count the steps to 0.","es":"Cuenta los pasos hasta el 0."},{"en":"Distance is never negative, so drop the minus sign.","es":"La distancia nunca es negativa, así que quita el signo menos."}],"example":{"en":"|−4| = 4, because −4 is 4 steps from 0. Also |4| = 4.","es":"|−4| = 4, porque −4 está a 4 pasos del 0. También |4| = 4."},"check":{"q":{"en":"What is |−7|?","es":"¿Cuánto es |−7|?"},"options":["-7","7","0"],"correctIdx":1,"calc":{"expr":"0 - (-7)","value":"7"},"feedback":[{"en":"Absolute value is a distance, and a distance is never negative.","es":"El valor absoluto es una distancia, y una distancia nunca es negativa."},{"en":"Yes. −7 is 7 steps from 0.","es":"Sí. −7 está a 7 pasos del 0."},{"en":"0 is the starting point, not the distance. Count the steps from −7 to 0.","es":"0 es el punto de partida, no la distancia. Cuenta los pasos de −7 hasta 0."}]},"model":{"kind":"numberline","data":{"min":-5,"max":5,"step":1,"points":[{"value":-4,"label":"−4","kind":"given"},{"value":4,"label":"4","kind":"given"}],"unit":null},"alt":{"en":"A number line from −5 to 5. Both −4 and 4 are 4 steps from 0, so each has absolute value 4.","es":"Una recta numérica de −5 a 5. Tanto −4 como 4 están a 4 pasos del 0, así que los dos tienen valor absoluto 4."}}},{"name":{"en":"Distance between two numbers on a line","es":"Distancia entre dos números en una recta"},"why":{"en":"Points that share a row or column sit on one line, so their distance works like a number line distance.","es":"Los puntos que comparten fila o columna están en una misma recta, así que su distancia se mide como en la recta numérica."},"steps":[{"en":"Same side of 0: subtract the smaller absolute value from the bigger one.","es":"Mismo lado del 0: resta el valor absoluto menor del mayor."},{"en":"Opposite sides of 0: add the two absolute values.","es":"Lados opuestos del 0: suma los dos valores absolutos."}],"example":{"en":"From 3 to 8: 8 − 3 = 5. From −3 to 4: 3 + 4 = 7.","es":"De 3 a 8: 8 − 3 = 5. De −3 a 4: 3 + 4 = 7, porque cruzas el 0."},"check":{"q":{"en":"How far apart are −2 and 6 on a number line?","es":"¿Qué distancia hay entre −2 y 6 en la recta numérica?"},"options":["4","8","-8"],"correctIdx":1,"calc":{"expr":"2 + 6","value":"8"},"feedback":[{"en":"4 is 6 − 2. These are on opposite sides of 0, so add: 2 + 6.","es":"4 es 6 − 2. Están en lados opuestos del 0, así que suma: 2 + 6."},{"en":"Yes. −2 is 2 from 0 and 6 is 6 from 0: 2 + 6 = 8.","es":"Sí. −2 está a 2 del 0 y 6 está a 6 del 0: 2 + 6 = 8."},{"en":"Distance is never negative. Use the absolute values and add them.","es":"La distancia nunca es negativa. Usa los valores absolutos y súmalos."}]},"model":{"kind":"numberline","data":{"min":-4,"max":5,"step":1,"points":[{"value":-3,"label":"−3","kind":"given"},{"value":4,"label":"4","kind":"answer"}],"unit":null},"alt":{"en":"A number line from −4 to 5. From −3 to 0 is 3 steps and from 0 to 4 is 4 steps, 7 in all.","es":"Una recta numérica de −4 a 5. De −3 a 0 hay 3 pasos y de 0 a 4 hay 4 pasos: 7 en total."}}}]},"7-7":{"skills":[{"name":{"en":"Side length from two corner points","es":"Longitud de un lado con dos vértices"},"why":{"en":"Tonight you find each side of a polygon from its vertex coordinates before you find perimeter and area.","es":"Hoy hallas cada lado de un polígono con las coordenadas de sus vértices antes de hallar el perímetro y el área."},"steps":[{"en":"Find the coordinate the two points share; the side runs along that line.","es":"Halla la coordenada que comparten los dos puntos; el lado va por esa recta."},{"en":"Use the other coordinates. Same side of 0: subtract. Opposite sides: add absolute values.","es":"Usa las otras coordenadas. Mismo lado del 0: resta. Lados opuestos: suma los valores absolutos."}],"example":{"en":"(−4, 3) and (5, 3) share y = 3. Then 4 + 5 = 9 units.","es":"(−4, 3) y (5, 3) comparten y = 3. Entonces 4 + 5 = 9 unidades."},"check":{"q":{"en":"How long is the side from (2, −1) to (2, 6)?","es":"¿Cuánto mide el lado de (2, −1) a (2, 6)?"},"options":["5","7","4"],"correctIdx":1,"calc":{"expr":"1 + 6","value":"7"},"feedback":[{"en":"5 is 6 − 1. The points are on opposite sides of 0, so add: 1 + 6.","es":"5 es 6 − 1. Los puntos están en lados opuestos del 0, así que suma: 1 + 6."},{"en":"Yes. Same x, so use y: −1 is 1 from 0, and 1 + 6 = 7.","es":"Sí. La x es igual, así que usa la y: −1 está a 1 del 0, y 1 + 6 = 7."},{"en":"4 mixes x and y. The x-values match, so use only the y-values.","es":"4 mezcla la x y la y. Las x son iguales, así que usa solo las y."}]},"model":{"kind":"coord","data":{"xmax":6,"ymax":6,"points":[{"x":-4,"y":3,"label":"(−4, 3)"},{"x":5,"y":3,"label":"(5, 3)"}],"quadrants":true},"alt":{"en":"A four-quadrant grid with corners at (−4, 3) and (5, 3) on the same flat line, 9 units apart.","es":"Una cuadrícula de cuatro cuadrantes con vértices en (−4, 3) y (5, 3) en la misma línea plana, a 9 unidades."}}},{"name":{"en":"Perimeter and area of a rectangle","es":"Perímetro y área de un rectángulo"},"why":{"en":"Once you know the side lengths, tonight's questions ask for the perimeter or the area.","es":"Cuando ya sabes las longitudes de los lados, las preguntas de hoy piden el perímetro o el área."},"steps":[{"en":"Perimeter: add all four sides.","es":"Perímetro: suma los cuatro lados."},{"en":"Area: multiply length × width, in square units.","es":"Área: multiplica largo × ancho, en unidades cuadradas."}],"example":{"en":"A 9 by 5 rectangle: perimeter 9 + 5 + 9 + 5 = 28 units; area 9 × 5 = 45 square units.","es":"Un rectángulo de 9 por 5: perímetro 9 + 5 + 9 + 5 = 28 unidades; área 9 × 5 = 45 unidades cuadradas."},"check":{"q":{"en":"A rectangle is 6 units long and 4 units wide. What is its area?","es":"Un rectángulo mide 6 unidades de largo y 4 de ancho. ¿Cuál es su área?"},"options":["20","10","24"],"correctIdx":2,"calc":{"expr":"6 × 4","value":"24"},"feedback":[{"en":"20 is the perimeter, 6 + 4 + 6 + 4. Area multiplies: 6 × 4.","es":"20 es el perímetro, 6 + 4 + 6 + 4. El área multiplica: 6 × 4."},{"en":"10 adds only two sides. For area, multiply length × width.","es":"10 suma solo dos lados. Para el área, multiplica largo × ancho."},{"en":"Yes. 6 × 4 = 24 square units.","es":"Sí. 6 × 4 = 24 unidades cuadradas."}]},"model":{"kind":"area","data":{"shape":"rectangle","dims":{"base":9,"height":5},"unit":{"en":"units","es":"unidades"},"cutAndSlide":false},"alt":{"en":"A rectangle 9 units long and 5 units wide. Its area is 9 × 5 = 45 square units.","es":"Un rectángulo de 9 unidades de largo y 5 de ancho. Su área es 9 × 5 = 45 unidades cuadradas."}}}]},"7-8":{"skills":[{"name":{"en":"Plot a point: x across, then y","es":"Ubicar un punto: primero x, luego y"},"why":{"en":"Tonight you plot points in all four quadrants, and every point still starts with x, then y.","es":"Hoy ubicas puntos en los cuatro cuadrantes, y cada punto empieza igual: primero x, luego y."},"steps":[{"en":"Start at the origin, (0, 0).","es":"Empieza en el origen, (0, 0)."},{"en":"Move across by the first number, x.","es":"Muévete de lado según el primer número, x."},{"en":"Then move up or down by the second number, y.","es":"Luego muévete hacia arriba o hacia abajo según el segundo número, y."}],"example":{"en":"(2, 5): 2 units right, then 5 units up. (5, 2) is a different point.","es":"(2, 5): 2 unidades a la derecha, luego 5 hacia arriba. (5, 2) es otro punto."},"check":{"q":{"en":"For the point (6, 2), how many units up do you move?","es":"Para el punto (6, 2), ¿cuántas unidades subes?"},"options":["2","6","8"],"correctIdx":0,"calc":{"expr":"2","value":"2"},"feedback":[{"en":"Yes. The second number, 2, is the move up.","es":"Sí. El segundo número, 2, es cuánto subes."},{"en":"6 is the first number, the move across. Up comes second.","es":"6 es el primer número, el movimiento de lado. Subir va en segundo lugar."},{"en":"8 adds both numbers. Each number is its own move.","es":"8 suma los dos números. Cada número es su propio movimiento."}]},"model":{"kind":"coord","data":{"xmax":6,"ymax":6,"points":[{"x":2,"y":5,"label":"(2, 5)"},{"x":5,"y":2,"label":"(5, 2)"}],"quadrants":false},"alt":{"en":"A grid with two points: (2, 5) and (5, 2). Swapping the numbers moves the point.","es":"Una cuadrícula con dos puntos: (2, 5) y (5, 2). Cambiar el orden de los números mueve el punto."}}},{"name":{"en":"Negative means the opposite direction","es":"Negativo significa la dirección opuesta"},"why":{"en":"In the other quadrants, a negative x moves you left and a negative y moves you down.","es":"En los otros cuadrantes, una x negativa te mueve a la izquierda y una y negativa te mueve hacia abajo."},"steps":[{"en":"Positive x goes right; negative x goes left.","es":"La x positiva va a la derecha; la x negativa va a la izquierda."},{"en":"Positive y goes up; negative y goes down.","es":"La y positiva va hacia arriba; la y negativa va hacia abajo."}],"example":{"en":"(−3, −2): 3 units left, then 2 units down. It lands in the lower-left quadrant.","es":"(−3, −2): 3 unidades a la izquierda, luego 2 hacia abajo. Queda en el cuadrante de abajo a la izquierda."},"check":{"q":{"en":"On a number line, start at 0, move 3 right, then 5 left. Where are you?","es":"En la recta numérica, empieza en 0, avanza 3 a la derecha y luego 5 a la izquierda. ¿Dónde estás?"},"options":["2","-2","8"],"correctIdx":1,"calc":{"expr":"3 - 5","value":"-2"},"feedback":[{"en":"2 is right of 0. You moved left more than right, so you passed 0.","es":"2 está a la derecha del 0. Te moviste más a la izquierda que a la derecha, así que pasaste el 0."},{"en":"Yes. 3 right, then 5 left lands 2 steps left of 0: −2.","es":"Sí. 3 a la derecha y luego 5 a la izquierda te deja 2 pasos a la izquierda del 0: −2."},{"en":"8 adds the moves. Moving left takes you back toward 0 and past it.","es":"8 suma los movimientos. Ir a la izquierda te regresa hacia el 0 y más allá."}]},"model":{"kind":"coord","data":{"xmax":4,"ymax":4,"points":[{"x":-3,"y":-2,"label":"(−3, −2)"}],"quadrants":true},"alt":{"en":"A four-quadrant grid with the point (−3, −2): 3 units left of the origin and 2 units down.","es":"Una cuadrícula de cuatro cuadrantes con el punto (−3, −2): 3 unidades a la izquierda del origen y 2 hacia abajo."}}}]},"7-9":{"skills":[{"name":{"en":"Opposites: same distance, other side of 0","es":"Opuestos: misma distancia, otro lado del 0"},"why":{"en":"A reflection flips a point to the other side of an axis, so one coordinate becomes its opposite.","es":"Una reflexión voltea un punto al otro lado de un eje, así que una coordenada se vuelve su opuesto."},"steps":[{"en":"Keep the distance from 0 the same.","es":"Mantén igual la distancia desde 0."},{"en":"Change the sign: positive becomes negative, negative becomes positive.","es":"Cambia el signo: el positivo se vuelve negativo y el negativo se vuelve positivo."}],"example":{"en":"The opposite of 4 is −4. The opposite of −2.5 is 2.5.","es":"El opuesto de 4 es −4. El opuesto de −2.5 es 2.5."},"check":{"q":{"en":"What is the opposite of −5?","es":"¿Cuál es el opuesto de −5?"},"options":["-5","0","5"],"correctIdx":2,"calc":{"expr":"0 - (-5)","value":"5"},"feedback":[{"en":"−5 is the same number. Move to the other side of 0.","es":"−5 es el mismo número. Pasa al otro lado del 0."},{"en":"0 is the middle, not the opposite. Keep the distance of 5.","es":"0 es el centro, no el opuesto. Mantén la distancia de 5."},{"en":"Yes. −5 and 5 are both 5 steps from 0.","es":"Sí. −5 y 5 están los dos a 5 pasos del 0."}]},"model":{"kind":"numberline","data":{"min":-5,"max":5,"step":0.5,"points":[{"value":-4,"label":"−4","kind":"given"},{"value":-2.5,"label":"−2.5","kind":"given"},{"value":2.5,"label":"2.5","kind":"given"},{"value":4,"label":"4","kind":"given"}],"unit":null},"alt":{"en":"A number line from −5 to 5. The pairs 4 and −4, and 2.5 and −2.5, mirror each other across 0.","es":"Una recta numérica de −5 a 5. Los pares 4 y −4, y 2.5 y −2.5, son reflejos uno del otro respecto al 0."}}},{"name":{"en":"Distance from an axis","es":"Distancia desde un eje"},"why":{"en":"A reflected point stays the same distance from the axis, so you need to read that distance first.","es":"Un punto reflejado queda a la misma distancia del eje, así que primero necesitas leer esa distancia."},"steps":[{"en":"The y-coordinate tells how far above or below the x-axis.","es":"La coordenada y dice qué tan arriba o abajo del eje x está el punto."},{"en":"The x-coordinate tells how far right or left of the y-axis.","es":"La coordenada x dice qué tan a la derecha o a la izquierda del eje y está."},{"en":"A distance is never negative.","es":"Una distancia nunca es negativa."}],"example":{"en":"(3, −4) is 4 units below the x-axis and 3 units right of the y-axis.","es":"(3, −4) está 4 unidades debajo del eje x y 3 unidades a la derecha del eje y."},"check":{"q":{"en":"How many units below the x-axis is the point (2, −6)?","es":"¿Cuántas unidades debajo del eje x está el punto (2, −6)?"},"options":["6","2","-6"],"correctIdx":0,"calc":{"expr":"6","value":"6"},"feedback":[{"en":"Yes. y = −6, so the point is 6 units below the x-axis.","es":"Sí. y = −6, así que el punto está 6 unidades debajo del eje x."},{"en":"2 is the x-coordinate. Up and down from the x-axis comes from y.","es":"2 es la coordenada x. Lo de arriba y abajo del eje x viene de la y."},{"en":"The minus sign means below. A distance itself is never negative.","es":"El signo menos significa abajo. Una distancia nunca es negativa."}]},"model":{"kind":"coord","data":{"xmax":5,"ymax":5,"points":[{"x":3,"y":-4,"label":"(3, −4)"}],"quadrants":true},"alt":{"en":"A four-quadrant grid with the point (3, −4), 4 units below the x-axis and 3 units right of the y-axis.","es":"Una cuadrícula de cuatro cuadrantes con el punto (3, −4), 4 unidades debajo del eje x y 3 a la derecha del eje y."}}}]},"8-1":{"skills":[{"name":{"en":"Find the missing number","es":"Hallar el número que falta"},"why":{"en":"Tonight's equations have an unknown, and finding it starts with this fact-family thinking.","es":"Las ecuaciones de hoy tienen un valor desconocido, y hallarlo empieza con esta idea de familias de operaciones."},"steps":[{"en":"Read the sentence: some number plus 3 equals 7.","es":"Lee la oración: un número más 3 es igual a 7."},{"en":"Ask what you add to 3 to make 7, or subtract: 7 − 3.","es":"Pregúntate qué sumas a 3 para llegar a 7, o resta: 7 − 3."},{"en":"Check it: put the number back in the sentence.","es":"Compruébalo: pon el número de nuevo en la oración."}],"example":{"en":"□ + 3 = 7. Since 7 − 3 = 4, the box is 4, and 4 + 3 = 7.","es":"□ + 3 = 7. Como 7 − 3 = 4, el cuadro es 4, y 4 + 3 = 7."},"check":{"q":{"en":"□ + 9 = 15. What number goes in the box?","es":"□ + 9 = 15. ¿Qué número va en el cuadro?"},"options":["24","6","5"],"correctIdx":1,"calc":{"expr":"15 - 9","value":"6"},"feedback":[{"en":"24 adds 9 and 15. Ask what plus 9 makes 15.","es":"24 suma 9 y 15. Pregúntate qué número más 9 da 15."},{"en":"Yes. 15 − 9 = 6, and 6 + 9 = 15.","es":"Sí. 15 − 9 = 6, y 6 + 9 = 15."},{"en":"Check it: 5 + 9 = 14, not 15. Try one more.","es":"Compruébalo: 5 + 9 = 14, no 15. Prueba con uno más."}]},"model":{"kind":"balance","data":{"left":["□","3"],"right":["7"],"unknown":"□"},"alt":{"en":"A level balance. The left pan holds a box and 3; the right pan holds 7.","es":"Una balanza en equilibrio. El platillo izquierdo tiene una caja y 3; el derecho tiene 7."}}},{"name":{"en":"Substitute a number for a letter","es":"Sustituir una letra por un número"},"why":{"en":"To check a solution tonight, you put the value in place of the letter and see if the equation is true.","es":"Para comprobar una solución hoy, pones el valor en lugar de la letra y ves si la ecuación es verdadera."},"steps":[{"en":"Write the number where the letter was.","es":"Escribe el número donde estaba la letra."},{"en":"A number next to a letter means multiply: 2n is 2 × n.","es":"Un número junto a una letra significa multiplicar: 2n es 2 × n."},{"en":"Multiply first, then add or subtract.","es":"Primero multiplica, luego suma o resta."}],"example":{"en":"Test n = 12 in n + 8 = 20: 12 + 8 = 20 is true, so 12 is the solution.","es":"Prueba n = 12 en n + 8 = 20: 12 + 8 = 20 es verdadero, así que 12 es la solución."},"check":{"q":{"en":"What is 5 + 2n when n = 3?","es":"¿Cuánto es 5 + 2n cuando n = 3?"},"options":["28","21","11"],"correctIdx":2,"calc":{"expr":"5 + 2 × 3","value":"11"},"feedback":[{"en":"28 reads 2n as 23. 2n means 2 × 3 = 6.","es":"28 lee 2n como 23. 2n significa 2 × 3 = 6."},{"en":"21 adds first. Multiply 2 × 3 first, then add 5.","es":"21 suma primero. Multiplica 2 × 3 primero y luego suma 5."},{"en":"Yes. 2 × 3 = 6, and 5 + 6 = 11.","es":"Sí. 2 × 3 = 6, y 5 + 6 = 11."}]},"model":{"kind":"balance","data":{"left":["12","8"],"right":["20"],"unknown":null},"alt":{"en":"A level balance with 12 and 8 on the left and 20 on the right, so n = 12 makes n + 8 = 20 true.","es":"Una balanza en equilibrio con 12 y 8 a la izquierda y 20 a la derecha: n = 12 hace verdadera n + 8 = 20."}}}]},"8-2":{"skills":[{"name":{"en":"Addition and subtraction undo each other","es":"La suma y la resta se deshacen entre sí"},"why":{"en":"Tonight you solve equations like n + 23 = 58 with the inverse operation, so subtraction must undo addition.","es":"Hoy resuelves ecuaciones como n + 23 = 58 con la operación inversa, así que la resta debe deshacer la suma."},"steps":[{"en":"A fact family links 3 + 4 = 7 with 7 − 4 = 3.","es":"Una familia de operaciones une 3 + 4 = 7 con 7 − 4 = 3."},{"en":"If a number was added, subtract it to undo it.","es":"Si se sumó un número, réstalo para deshacerlo."},{"en":"If a number was subtracted, add it back.","es":"Si se restó un número, súmalo de nuevo."}],"example":{"en":"□ + 4 = 9. Undo the + 4: 9 − 4 = 5. Check: 5 + 4 = 9.","es":"□ + 4 = 9. Deshaz el + 4: 9 − 4 = 5. Comprueba: 5 + 4 = 9."},"check":{"q":{"en":"□ − 7 = 12. What number goes in the box?","es":"□ − 7 = 12. ¿Qué número va en el cuadro?"},"options":["5","19","20"],"correctIdx":1,"calc":{"expr":"12 + 7","value":"19"},"feedback":[{"en":"5 subtracts again. To undo − 7, add 7: 12 + 7.","es":"5 vuelve a restar. Para deshacer − 7, suma 7: 12 + 7."},{"en":"Yes. 12 + 7 = 19, and 19 − 7 = 12.","es":"Sí. 12 + 7 = 19, y 19 − 7 = 12."},{"en":"Check it: 20 − 7 = 13, not 12. Add 12 + 7 carefully.","es":"Compruébalo: 20 − 7 = 13, no 12. Suma 12 + 7 con cuidado."}]},"model":{"kind":"balance","data":{"left":["□","4"],"right":["9"],"unknown":"□"},"alt":{"en":"A level balance. The left pan holds a box and 4; the right pan holds 9.","es":"Una balanza en equilibrio. El platillo izquierdo tiene una caja y 4; el derecho tiene 9."}}},{"name":{"en":"Subtract decimals by lining up the points","es":"Restar decimales alineando los puntos"},"why":{"en":"Tonight's equations often use money and decimals, so undoing an addition means subtracting decimals.","es":"Las ecuaciones de hoy suelen usar dinero y decimales, así que deshacer una suma significa restar decimales."},"steps":[{"en":"Line up the decimal points.","es":"Alinea los puntos decimales."},{"en":"Write 0s so both numbers have the same places.","es":"Escribe ceros para que los dos números tengan las mismas posiciones."},{"en":"Subtract, and regroup when the top digit is smaller.","es":"Resta y reagrupa cuando el dígito de arriba es menor."}],"example":{"en":"8 − 1.25: write 8.00 − 1.25 = 6.75.","es":"8 − 1.25: escribe 8.00 − 1.25, y el resultado es 6.75."},"check":{"q":{"en":"What is 6 − 2.35?","es":"¿Cuánto es 6 − 2.35?"},"options":["4.35","3.65","2.29"],"correctIdx":1,"calc":{"expr":"6 - 2.35","value":"3.65"},"feedback":[{"en":"4.35 takes the smaller digit from the bigger one in each place. Write 6.00 and regroup.","es":"4.35 resta el dígito menor del mayor en cada lugar. Escribe 6.00 y reagrupa."},{"en":"Yes. 6.00 − 2.35 = 3.65.","es":"Sí. 6.00 − 2.35 = 3.65."},{"en":"2.29 lines up the right edges. Line up the decimal points instead.","es":"2.29 alinea los números por la derecha. Mejor alinea los puntos decimales."}]},"model":{"kind":"numberline","data":{"min":6,"max":8,"step":0.25,"points":[{"value":8,"label":"8","kind":"given"},{"value":6.75,"label":"6.75","kind":"answer"}],"unit":null},"alt":{"en":"A number line from 6 to 8 marked every quarter. A jump back 1.25 from 8 lands on 6.75.","es":"Una recta numérica de 6 a 8 marcada cada cuarto. Un salto de 1.25 hacia atrás desde 8 llega a 6.75."}}}]},"8-3":{"skills":[{"name":{"en":"Multiplication and division undo each other","es":"La multiplicación y la división se deshacen entre sí"},"why":{"en":"Tonight you solve equations like 3x = 21 by dividing, because division undoes multiplication.","es":"Hoy resuelves ecuaciones como 3x = 21 dividiendo, porque la división deshace la multiplicación."},"steps":[{"en":"A fact family links 3 × 7 = 21 with 21 ÷ 3 = 7.","es":"Una familia de operaciones une 3 × 7 = 21 con 21 ÷ 3 = 7."},{"en":"If a number was multiplied, divide to undo it.","es":"Si se multiplicó por un número, divide para deshacerlo."},{"en":"If a number was divided, multiply to undo it.","es":"Si se dividió entre un número, multiplica para deshacerlo."}],"example":{"en":"3 × □ = 12. Undo × 3: 12 ÷ 3 = 4. Check: 3 × 4 = 12.","es":"3 × □ = 12. Deshaz × 3: 12 ÷ 3 = 4. Comprueba: 3 × 4 = 12."},"check":{"q":{"en":"6 × □ = 42. What number goes in the box?","es":"6 × □ = 42. ¿Qué número va en el cuadro?"},"options":["36","252","7"],"correctIdx":2,"calc":{"expr":"42 ÷ 6","value":"7"},"feedback":[{"en":"36 subtracts 6. To undo × 6, divide: 42 ÷ 6.","es":"36 resta 6. Para deshacer × 6, divide: 42 ÷ 6."},{"en":"252 multiplies again. Divide to undo multiplying.","es":"252 vuelve a multiplicar. Divide para deshacer la multiplicación."},{"en":"Yes. 42 ÷ 6 = 7, and 6 × 7 = 42.","es":"Sí. 42 ÷ 6 = 7, y 6 × 7 = 42."}]},"model":{"kind":"balance","data":{"left":["□","□","□"],"right":["12"],"unknown":"□"},"alt":{"en":"A level balance. Three equal boxes on the left weigh the same as 12 on the right.","es":"Una balanza en equilibrio. Tres cajas iguales a la izquierda pesan lo mismo que 12 a la derecha."}}},{"name":{"en":"What 3x means","es":"Qué significa 3x"},"why":{"en":"Tonight's equations write multiplication as 3x, so you need to read it as 3 times x.","es":"Las ecuaciones de hoy escriben la multiplicación como 3x, así que necesitas leerla como 3 por x."},"steps":[{"en":"A number written next to a letter means multiply.","es":"Un número escrito junto a una letra significa multiplicar."},{"en":"x ÷ 4 means x divided by 4.","es":"x ÷ 4 significa x dividido entre 4."}],"example":{"en":"3x = 21 means 3 times some number is 21.","es":"3x = 21 significa que 3 por algún número da 21."},"check":{"q":{"en":"What is 4x when x = 9?","es":"¿Cuánto es 4x cuando x = 9?"},"options":["49","36","13"],"correctIdx":1,"calc":{"expr":"4 × 9","value":"36"},"feedback":[{"en":"49 puts the digits side by side. 4x means 4 × 9.","es":"49 pone los dígitos lado a lado. 4x significa 4 × 9."},{"en":"Yes. 4 × 9 = 36.","es":"Sí. 4 × 9 = 36."},{"en":"13 adds. A number next to a letter means multiply.","es":"13 suma. Un número junto a una letra significa multiplicar."}]},"model":{"kind":"tape","data":{"parts":3,"highlight":1,"partLabel":{"en":"x","es":"x"},"wholeLabel":{"en":"21","es":"21 en total"},"blockLabel":{"en":"x","es":"x"},"unknown":"part"},"alt":{"en":"A bar of 21 split into 3 equal parts. Each part is x, so 3x = 21.","es":"Una barra de 21 dividida en 3 partes iguales. Cada parte es x, así que 3x = 21."}}}]},"8-4":{"skills":[{"name":{"en":"Greater than and less than","es":"Mayor que y menor que"},"why":{"en":"Tonight you write inequalities, which compare amounts with greater than or less than.","es":"Hoy escribes desigualdades, que comparan cantidades con mayor que o menor que."},"steps":[{"en":"Greater than means bigger; less than means smaller.","es":"Mayor que significa más grande; menor que significa más pequeño."},{"en":"In the symbol, the open side faces the bigger number.","es":"En el símbolo, el lado abierto mira hacia el número más grande."},{"en":"A number is never greater than itself.","es":"Un número nunca es mayor que sí mismo."}],"example":{"en":"If n is greater than 5, n can be 6, 10 or 5.5, but not 5.","es":"Si n es mayor que 5, n puede ser 6, 10 o 5.5, pero no 5."},"check":{"q":{"en":"Which number is greater than 9?","es":"¿Qué número es mayor que 9?"},"options":["9","12","4"],"correctIdx":1,"calc":{"expr":"12","value":"12"},"feedback":[{"en":"9 equals 9. A number is never greater than itself.","es":"9 es igual a 9. Un número nunca es mayor que sí mismo."},{"en":"Yes. 12 is to the right of 9 on a number line.","es":"Sí. 12 está a la derecha del 9 en la recta numérica."},{"en":"4 is less than 9. Greater means farther right.","es":"4 es menor que 9. Mayor significa más a la derecha."}]},"model":{"kind":"numberline","data":{"min":4,"max":11,"step":0.5,"points":[{"value":5,"label":{"en":"not 5","es":"no 5"},"kind":"given"},{"value":5.5,"label":"5.5","kind":"answer"},{"value":6,"label":"6","kind":"answer"},{"value":10,"label":"10","kind":"answer"}],"unit":null},"alt":{"en":"A number line from 4 to 11. 5.5, 6 and 10 are marked as greater than 5; 5 itself is not.","es":"Una recta numérica de 4 a 11. 5.5, 6 y 10 están marcados como mayores que 5; el 5 no lo es."}}},{"name":{"en":"At least and at most","es":"Al menos y a lo más"},"why":{"en":"Tonight's word problems say at least or at most, and these words decide whether the number itself counts.","es":"Los problemas de hoy dicen al menos o a lo más, y estas palabras deciden si el número mismo cuenta."},"steps":[{"en":"At least 18 means 18 or more; 18 counts.","es":"Al menos 18 significa 18 o más; el 18 cuenta."},{"en":"At most 18 means 18 or less; 18 counts.","es":"A lo más 18 significa 18 o menos; el 18 cuenta."},{"en":"More than 18 or less than 18 leaves 18 out.","es":"Más de 18 o menos de 18 deja fuera el 18."}],"example":{"en":"Must be at least 18 years old: 18 works, 20 works, 16 does not.","es":"Hay que tener al menos 18 años: 18 sirve, 20 sirve, 16 no sirve."},"check":{"q":{"en":"A ride needs riders at least 12 years old. What is the youngest age that works?","es":"Un juego pide tener al menos 12 años. ¿Cuál es la menor edad que sirve?"},"options":["11","13","12"],"correctIdx":2,"calc":{"expr":"12","value":"12"},"feedback":[{"en":"11 is less than 12, so it is too young.","es":"11 es menor que 12, así que no alcanza la edad."},{"en":"13 works, but 12 works too. At least includes 12.","es":"13 sirve, pero 12 también. Al menos incluye el 12."},{"en":"Yes. At least 12 means 12 or older, so 12 counts.","es":"Sí. Al menos 12 significa 12 o más, así que el 12 cuenta."}]},"model":{"kind":"numberline","data":{"min":14,"max":22,"step":1,"points":[{"value":16,"label":{"en":"16 no","es":"16 no"},"kind":"given"},{"value":18,"label":"18","kind":"answer"},{"value":20,"label":"20","kind":"answer"}],"unit":null},"alt":{"en":"A number line from 14 to 22. Ages 18 and 20 are marked as working; 16 is too young.","es":"Una recta numérica de 14 a 22. Las edades 18 y 20 sirven; 16 no alcanza."}}}]},"8-5":{"skills":[{"name":{"en":"Compare numbers on a number line","es":"Comparar números en la recta numérica"},"why":{"en":"To graph an inequality tonight, you shade toward bigger or smaller numbers, so you must know which way is which.","es":"Para representar una desigualdad hoy, sombreas hacia los números mayores o menores, así que debes saber hacia dónde van."},"steps":[{"en":"Numbers get bigger to the right and smaller to the left.","es":"Los números son mayores hacia la derecha y menores hacia la izquierda."},{"en":"For negatives, the one closer to 0 is greater.","es":"Entre negativos, el que está más cerca del 0 es mayor."}],"example":{"en":"−3 is greater than −5, because −3 is to the right of −5.","es":"−3 es mayor que −5, porque −3 está a la derecha de −5."},"check":{"q":{"en":"Which number is greatest: −5, −3, or −8?","es":"¿Cuál número es el mayor: −5, −3 o −8?"},"options":["-8","-3","-5"],"correctIdx":1,"calc":{"expr":"-3","value":"-3"},"feedback":[{"en":"−8 is farthest left, so it is the least. Look for the one farthest right.","es":"−8 está más a la izquierda, así que es el menor. Busca el que está más a la derecha."},{"en":"Yes. −3 is closest to 0, so it is farthest right.","es":"Sí. −3 está más cerca del 0, así que está más a la derecha."},{"en":"−5 is in the middle. −3 is to its right, so −3 is greater.","es":"−5 está en medio. −3 está a su derecha, así que −3 es mayor."}]},"model":{"kind":"numberline","data":{"min":-6,"max":0,"step":1,"points":[{"value":-5,"label":"−5","kind":"given"},{"value":-3,"label":"−3","kind":"answer"}],"unit":null},"alt":{"en":"A number line from −6 to 0. −3 is to the right of −5, so −3 is greater.","es":"Una recta numérica de −6 a 0. −3 está a la derecha de −5, así que −3 es mayor."}}},{"name":{"en":"Is the boundary number included?","es":"¿Se incluye el número límite?"},"why":{"en":"Tonight's graph uses an open or closed circle, depending on whether the boundary number is a solution.","es":"La gráfica de hoy usa un círculo abierto o cerrado, según si el número límite es una solución."},"steps":[{"en":"Greater than or less than: the number itself is left out.","es":"Mayor que o menor que: el número mismo queda fuera."},{"en":"With ≥ or ≤ (greater or equal, less or equal), the number is included.","es":"Con ≥ o ≤ (mayor o igual, menor o igual), el número se incluye."}],"example":{"en":"x ≥ 4 includes 4. If x is greater than 4, the smallest whole number that works is 5.","es":"x ≥ 4 incluye el 4. Si x es mayor que 4, el menor número entero que sirve es 5."},"check":{"q":{"en":"x ≥ 7. What is the smallest whole number that works?","es":"x ≥ 7. ¿Cuál es el menor número entero que sirve?"},"options":["7","8","6"],"correctIdx":0,"calc":{"expr":"7","value":"7"},"feedback":[{"en":"Yes. The line under ≥ means 7 itself is included.","es":"Sí. La raya debajo de ≥ significa que el 7 se incluye."},{"en":"8 works, but so does 7. The ≥ sign includes 7.","es":"8 sirve, pero el 7 también. El signo ≥ incluye el 7."},{"en":"6 is less than 7, so it does not work.","es":"6 es menor que 7, así que no sirve."}]},"model":{"kind":"numberline","data":{"min":0,"max":8,"step":1,"points":[{"value":4,"label":{"en":"4 included","es":"4 incluido"},"kind":"answer"},{"value":5,"label":"5","kind":"given"}],"unit":null},"alt":{"en":"A number line from 0 to 8. 4 is marked as included for x ≥ 4; 5 is the first whole number greater than 4.","es":"Una recta numérica de 0 a 8. El 4 está incluido en x ≥ 4; 5 es el primer número entero mayor que 4."}}}]},"8-6":{"skills":[{"name":{"en":"Solve a one-step equation with the inverse","es":"Resolver una ecuación de un paso con la operación inversa"},"why":{"en":"Tonight you get the letter alone in an inequality the same way you solve an equation.","es":"Hoy dejas sola la letra en una desigualdad igual que cuando resuelves una ecuación."},"steps":[{"en":"Find what is being done to the letter.","es":"Halla qué operación se le hace a la letra."},{"en":"Do the inverse operation to both sides.","es":"Haz la operación inversa en los dos lados."},{"en":"Check by putting the answer back in.","es":"Comprueba poniendo la respuesta de nuevo en la ecuación."}],"example":{"en":"x + 3 = 53: subtract 3 from both sides, so x = 50.","es":"x + 3 = 53: resta 3 en los dos lados, así que x = 50."},"check":{"q":{"en":"Solve 4x = 32. What is x?","es":"Resuelve 4x = 32. ¿Cuánto vale x?"},"options":["28","8","128"],"correctIdx":1,"calc":{"expr":"32 ÷ 4","value":"8"},"feedback":[{"en":"28 subtracts 4. 4x means 4 × x, so divide by 4.","es":"28 resta 4. 4x significa 4 × x, así que divide entre 4."},{"en":"Yes. 32 ÷ 4 = 8, and 4 × 8 = 32.","es":"Sí. 32 ÷ 4 = 8, y 4 × 8 = 32."},{"en":"128 multiplies again. Divide to undo the × 4.","es":"128 vuelve a multiplicar. Divide para deshacer el × 4."}]},"model":{"kind":"balance","data":{"left":["x","3"],"right":["53"],"unknown":"x"},"alt":{"en":"A level balance. The left pan holds x and 3; the right pan holds 53.","es":"Una balanza en equilibrio. El platillo izquierdo tiene x y 3; el derecho tiene 53."}}},{"name":{"en":"Test a number in an inequality","es":"Probar un número en una desigualdad"},"why":{"en":"After you solve tonight, you check by putting a number in and seeing if the inequality is true.","es":"Después de resolver hoy, compruebas poniendo un número y viendo si la desigualdad es verdadera."},"steps":[{"en":"Put the number in place of the letter.","es":"Pon el número en lugar de la letra."},{"en":"Work out the side with the letter.","es":"Calcula el lado que tiene la letra."},{"en":"Ask if the comparison is true. If yes, it is a solution.","es":"Pregúntate si la comparación es verdadera. Si lo es, es una solución."}],"example":{"en":"Is 60 a solution of x + 3 greater than 53? 60 + 3 = 63, and 63 is greater than 53. Yes.","es":"¿Es 60 una solución de x + 3 mayor que 53? 60 + 3 = 63, y 63 es mayor que 53. Sí."},"check":{"q":{"en":"Which number is a solution of n + 3 greater than 10?","es":"¿Qué número es una solución de n + 3 mayor que 10?"},"options":["5","7","8"],"correctIdx":2,"calc":{"expr":"8","value":"8"},"feedback":[{"en":"5 + 3 = 8, which is less than 10. Try a bigger number.","es":"5 + 3 = 8, que es menor que 10. Prueba un número mayor."},{"en":"7 + 3 = 10, and 10 is not greater than itself.","es":"7 + 3 = 10, y 10 no es mayor que sí mismo."},{"en":"Yes. 8 + 3 = 11, and 11 is greater than 10.","es":"Sí. 8 + 3 = 11, y 11 es mayor que 10."}]},"model":{"kind":"numberline","data":{"min":50,"max":66,"step":1,"points":[{"value":53,"label":"53","kind":"given"},{"value":63,"label":"63","kind":"answer"}],"unit":null},"alt":{"en":"A number line from 50 to 66. 63 sits to the right of 53, so 63 is greater than 53.","es":"Una recta numérica de 50 a 66. 63 está a la derecha de 53, así que 63 es mayor que 53."}}}]},"8-7":{"skills":[{"name":{"en":"Turn words into an equation","es":"Convertir palabras en una ecuación"},"why":{"en":"Tonight's word problems hide a number sentence, so you name the unknown and match words to symbols.","es":"Los problemas de hoy esconden una oración numérica, así que nombras el valor desconocido y unes palabras con símbolos."},"steps":[{"en":"Pick a letter for the unknown amount.","es":"Elige una letra para la cantidad desconocida."},{"en":"Match words: more than means +, times means ×, split equally means ÷, is means =.","es":"Une palabras y símbolos: más que es +, por es ×, repartir en partes iguales es ÷, es igual es =."},{"en":"Solve with the inverse operation, then check.","es":"Resuelve con la operación inversa y luego comprueba."}],"example":{"en":"4 more than a number is 10: n + 4 = 10, so n = 6.","es":"4 más que un número es 10: n + 4 = 10, así que n = 6."},"check":{"q":{"en":"A total split equally among 5 people gives each $8. What is the total?","es":"El total repartido en partes iguales entre 5 personas da $8 a cada una. ¿Cuál es el total?"},"options":["13","1.6","40"],"correctIdx":2,"calc":{"expr":"8 × 5","value":"40"},"feedback":[{"en":"13 adds 5 + 8. Write t ÷ 5 = 8, then multiply to undo.","es":"13 suma 5 + 8. Escribe t ÷ 5 = 8 y luego multiplica para deshacer."},{"en":"1.6 divides again. To undo ÷ 5, multiply: 8 × 5.","es":"1.6 vuelve a dividir. Para deshacer ÷ 5, multiplica: 8 × 5."},{"en":"Yes. t ÷ 5 = 8, so t = 8 × 5 = 40.","es":"Sí. t ÷ 5 = 8, así que t = 8 × 5 = 40."}]},"model":{"kind":"balance","data":{"left":["n","4"],"right":["10"],"unknown":"n"},"alt":{"en":"A level balance. The left pan holds n and 4; the right pan holds 10.","es":"Una balanza en equilibrio. El platillo izquierdo tiene n y 4; el derecho tiene 10."}}},{"name":{"en":"At least, at most: equation or inequality","es":"Al menos, a lo más: ecuación o desigualdad"},"why":{"en":"Tonight you choose between an equation and an inequality, and words like at least or at most signal an inequality.","es":"Hoy decides entre una ecuación y una desigualdad, y palabras como al menos o a lo más indican una desigualdad."},"steps":[{"en":"One exact amount (is, equals) means an equation.","es":"Una cantidad exacta (es, es igual a) indica una ecuación."},{"en":"A range (at least, at most, more than, less than) means an inequality.","es":"Un rango (al menos, a lo más, más de, menos de) indica una desigualdad."},{"en":"For at most, the answer cannot go over the limit.","es":"Con a lo más, la respuesta no puede pasar del límite."}],"example":{"en":"Tickets cost $5 and you have $22. You can buy at most 4, because 5 × 5 = 25 is too much.","es":"Los boletos cuestan $5 y tienes $22. Puedes comprar a lo más 4, porque 5 × 5 = 25 es demasiado."},"check":{"q":{"en":"Tickets cost $6 and you have $40. What is the most tickets you can buy?","es":"Los boletos cuestan $6 y tienes $40. ¿Cuántos boletos puedes comprar como máximo?"},"options":["6","7","34"],"correctIdx":0,"calc":{"expr":"6","value":"6"},"feedback":[{"en":"Yes. 6 × 6 = 36 fits in $40, and 7 tickets cost $42.","es":"Sí. 6 × 6 = 36 cabe en $40, y 7 boletos cuestan $42."},{"en":"7 tickets cost 7 × 6 = $42, more than $40. Round down here.","es":"7 boletos cuestan 7 × 6 = $42, más de $40. Aquí redondea hacia abajo."},{"en":"34 subtracts 40 − 6. Divide the money by the price instead.","es":"34 resta 40 − 6. Mejor divide el dinero entre el precio."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Tickets","es":"Boletos"},{"en":"Cost","es":"Costo"}],"rows":[[1,"$5"],[2,"$10"],[3,"$15"],[4,"$20"],[5,"$25"]],"unknownCells":[],"arrows":[]},"alt":{"en":"A table of ticket costs at $5 each. 4 tickets cost $20, which fits in $22; 5 tickets cost $25, too much.","es":"Una tabla de boletos a $5 cada uno. 4 boletos cuestan $20 y caben en $22; 5 boletos cuestan $25, demasiado."}}}]},"9-1":{"skills":[{"name":{"en":"Read and extend a table","es":"Leer y continuar una tabla"},"why":{"en":"Tonight's tables pair two amounts in each row, so you read across to see which values go together.","es":"Las tablas de hoy emparejan dos cantidades en cada fila, así que lees de lado a lado para ver qué valores van juntos."},"steps":[{"en":"Find the column you know, like tickets.","es":"Halla la columna que conoces, como los boletos."},{"en":"Read across that same row to the other column.","es":"Lee de lado a lado en esa misma fila hasta la otra columna."},{"en":"Look for how much each row changes.","es":"Busca cuánto cambia de una fila a otra."}],"example":{"en":"A row says 3 tickets and $12. That means 3 tickets cost $12.","es":"Una fila dice 3 boletos y $12. Eso significa que 3 boletos cuestan $12."},"check":{"q":{"en":"A table shows 1 ticket costs $4, 2 cost $8, and 3 cost $12. What do 5 tickets cost?","es":"Una tabla muestra que 1 boleto cuesta $4, 2 cuestan $8 y 3 cuestan $12. ¿Cuánto cuestan 5 boletos?"},"options":["16","20","17"],"correctIdx":1,"calc":{"expr":"5 × 4","value":"20"},"feedback":[{"en":"16 is the cost of 4 tickets. Go one more row: 5 × 4.","es":"16 es el costo de 4 boletos. Avanza una fila más: 5 × 4."},{"en":"Yes. Each ticket adds $4, so 5 tickets cost 5 × 4 = $20.","es":"Sí. Cada boleto suma $4, así que 5 boletos cuestan 5 × 4 = $20."},{"en":"17 adds 5 dollars, but each ticket adds $4. Use 5 × 4.","es":"17 suma 5 dólares, pero cada boleto suma $4. Usa 5 × 4."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Tickets","es":"Boletos"},{"en":"Cost","es":"Costo"}],"rows":[[1,"$4"],[2,"$8"],[3,"$12"]],"unknownCells":[],"arrows":[]},"alt":{"en":"A table: 1 ticket costs $4, 2 cost $8, and 3 cost $12. Each row pairs tickets with cost.","es":"Una tabla: 1 boleto cuesta $4, 2 cuestan $8 y 3 cuestan $12. Cada fila une boletos con su costo."}}},{"name":{"en":"Multiply by the price for each one","es":"Multiplicar por el precio de cada uno"},"why":{"en":"In tonight's stories, the total depends on how many you choose, and you find it by multiplying.","es":"En las historias de hoy, el total depende de cuántos escoges, y lo hallas multiplicando."},"steps":[{"en":"Find the price for one.","es":"Halla el precio de uno."},{"en":"Multiply it by how many you choose.","es":"Multiplícalo por cuántos escoges."},{"en":"When how many changes, the total changes too.","es":"Cuando cambia la cantidad que escoges, el total también cambia."}],"example":{"en":"Tickets cost $9 each. 3 tickets cost 3 × 9 = $27.","es":"Cada boleto cuesta $9. 3 boletos cuestan 3 × 9 = $27."},"check":{"q":{"en":"Each snack costs $7. What do 6 snacks cost, in dollars?","es":"Cada merienda cuesta $7. ¿Cuánto cuestan 6 meriendas, en dólares?"},"options":["42","13","49"],"correctIdx":0,"calc":{"expr":"6 × 7","value":"42"},"feedback":[{"en":"Yes. 6 × 7 = 42, so 6 snacks cost $42.","es":"Sí. 6 × 7 = 42, así que 6 meriendas cuestan $42."},{"en":"13 adds 6 + 7. Each snack costs $7, so multiply.","es":"13 suma 6 + 7. Cada merienda cuesta $7, así que multiplica."},{"en":"49 is the cost of 7 snacks. Multiply by 6, the number you buy.","es":"49 es el costo de 7 meriendas. Multiplica por 6, la cantidad que compras."}]},"model":{"kind":"tape","data":{"parts":3,"highlight":3,"partLabel":null,"wholeLabel":{"en":"3 × 9 = $27","es":"3 × 9 = $27 en total"},"blockLabel":{"en":"$9","es":"$9"},"unknown":null},"alt":{"en":"A bar of 3 equal blocks, each $9 for one ticket. Together they make $27.","es":"Una barra de 3 bloques iguales, cada uno de $9 por boleto. Juntos suman $27."}}}]},"9-2":{"skills":[{"name":{"en":"Write a table row as an ordered pair","es":"Escribir una fila como par ordenado"},"why":{"en":"Tonight each table row becomes one point on a graph, written as an ordered pair.","es":"Hoy cada fila de la tabla se vuelve un punto en la gráfica, escrito como par ordenado."},"steps":[{"en":"Put the independent variable first, like tickets.","es":"Pon primero la variable independiente, como los boletos."},{"en":"Put the dependent variable second, like cost.","es":"Pon en segundo lugar la variable dependiente, como el costo."},{"en":"Move right by the first number, then up by the second.","es":"Muévete a la derecha según el primer número y luego hacia arriba según el segundo."}],"example":{"en":"2 tickets cost $90, so the pair is (2, 90). (90, 2) is a different point.","es":"2 boletos cuestan $90, así que el par es (2, 90). (90, 2) es otro punto."},"check":{"q":{"en":"For the point (3, 135), how many units up do you move?","es":"Para el punto (3, 135), ¿cuántas unidades subes?"},"options":["3","138","135"],"correctIdx":2,"calc":{"expr":"135","value":"135"},"feedback":[{"en":"3 is the first number, the move to the right. Up comes second.","es":"3 es el primer número, el movimiento a la derecha. Subir va en segundo lugar."},{"en":"138 adds both numbers. Each number is its own move.","es":"138 suma los dos números. Cada número es su propio movimiento."},{"en":"Yes. The second number, 135, is the move up.","es":"Sí. El segundo número, 135, es cuánto subes."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Tickets","es":"Boletos"},{"en":"Cost ($)","es":"Costo ($)"}],"rows":[[1,45],[2,90],[3,135]],"unknownCells":[],"arrows":[]},"alt":{"en":"A table with tickets first and cost second. The row 2 and 90 becomes the ordered pair (2, 90).","es":"Una tabla con boletos primero y costo después. La fila 2 y 90 se vuelve el par ordenado (2, 90)."}}},{"name":{"en":"Multiply by a rate to fill a table","es":"Multiplicar por una tasa para completar una tabla"},"why":{"en":"Before you graph tonight, you fill the table by multiplying each amount by the rate.","es":"Antes de hacer la gráfica hoy, completas la tabla multiplicando cada cantidad por la tasa."},"steps":[{"en":"Find the rate for one, like $45 a ticket.","es":"Halla la tasa para uno, como $45 por boleto."},{"en":"Multiply each number of tickets by the rate.","es":"Multiplica cada número de boletos por la tasa."}],"example":{"en":"1 × 45 = 45, 2 × 45 = 90, 3 × 45 = 135.","es":"1 × 45 = 45, 2 × 45 = 90 y 3 × 45 = 135."},"check":{"q":{"en":"Tickets are $45 each. What do 4 tickets cost, in dollars?","es":"Cada boleto cuesta $45. ¿Cuánto cuestan 4 boletos, en dólares?"},"options":["49","180","160"],"correctIdx":1,"calc":{"expr":"4 × 45","value":"180"},"feedback":[{"en":"49 adds 45 + 4. Each ticket costs $45, so multiply.","es":"49 suma 45 + 4. Cada boleto cuesta $45, así que multiplica."},{"en":"Yes. 4 × 45 = 180.","es":"Sí. 4 × 45 = 180."},{"en":"160 multiplies only the 40. Also add 4 × 5 = 20.","es":"160 multiplica solo el 40. Suma también 4 × 5 = 20."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Tickets","es":"Boletos"},{"en":"Cost ($)","es":"Costo ($)"}],"rows":[[1,45],[2,90],[3,135]],"unknownCells":[],"arrows":[{"from":0,"to":1,"label":"× 2"},{"from":0,"to":2,"label":"× 3"}]},"alt":{"en":"A table at $45 a ticket: 1 × 45 = 45, 2 × 45 = 90 and 3 × 45 = 135.","es":"Una tabla a $45 por boleto: 1 × 45 = 45, 2 × 45 = 90 y 3 × 45 = 135."}}}]},"9-3":{"skills":[{"name":{"en":"Find the amount added each row","es":"Hallar cuánto se suma en cada fila"},"why":{"en":"Tonight you write an equation like c = 24.95m, and 24.95 is the amount added each row.","es":"Hoy escribes una ecuación como c = 24.95m, y 24.95 es lo que se suma en cada fila."},"steps":[{"en":"Check that the first column goes up by 1.","es":"Revisa que la primera columna sube de 1 en 1."},{"en":"Subtract one row's total from the next row's total.","es":"Resta el total de una fila del total de la fila siguiente."},{"en":"If every row adds the same amount, that amount is the rate.","es":"Si cada fila suma la misma cantidad, esa cantidad es la tasa."}],"example":{"en":"1 month costs $24.95 and 2 months cost $49.90: 49.90 − 24.95 = 24.95 added each month.","es":"1 mes cuesta $24.95 y 2 meses cuestan $49.90: 49.90 − 24.95 = 24.95 por cada mes."},"check":{"q":{"en":"1 hour pays $12, 2 hours pay $24, 3 hours pay $36. How much is added each hour?","es":"1 hora paga $12, 2 horas pagan $24 y 3 horas pagan $36. ¿Cuánto se suma por cada hora?"},"options":["36","1","12"],"correctIdx":2,"calc":{"expr":"24 - 12","value":"12"},"feedback":[{"en":"36 is the pay for 3 hours. Subtract one row from the next.","es":"36 es el pago por 3 horas. Resta una fila de la siguiente."},{"en":"1 is the change in hours. Look at the change in pay.","es":"1 es el cambio en las horas. Mira el cambio en el pago."},{"en":"Yes. 24 − 12 = 12, and 36 − 24 = 12.","es":"Sí. 24 − 12 = 12, y 36 − 24 = 12."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"Months","es":"Meses"},{"en":"Cost","es":"Costo"}],"rows":[[1,"$24.95"],[2,"$49.90"],[3,"$74.85"]],"unknownCells":[],"arrows":[{"from":0,"to":1,"label":"+ 24.95"},{"from":1,"to":2,"label":"+ 24.95"}]},"alt":{"en":"A table of months and cost. Each row adds the same $24.95.","es":"Una tabla de meses y costo. Cada fila suma los mismos $24.95."}}},{"name":{"en":"Substitute into an expression like 15h","es":"Sustituir en una expresión como 15h"},"why":{"en":"To check your equation tonight, you put a table value in for the letter and multiply.","es":"Para comprobar tu ecuación hoy, pones un valor de la tabla en lugar de la letra y multiplicas."},"steps":[{"en":"15h means 15 × h.","es":"15h significa 15 por h."},{"en":"Replace the letter with the number.","es":"Cambia la letra por el número."},{"en":"Multiply, then compare with the table.","es":"Multiplica y compara con la tabla."}],"example":{"en":"c = 24.95m with m = 3: 24.95 × 3 = 74.85, which matches the table.","es":"c = 24.95m con m = 3: 24.95 × 3 = 74.85, igual que en la tabla."},"check":{"q":{"en":"What is 15h when h = 4?","es":"¿Cuánto es 15h cuando h = 4?"},"options":["19","60","154"],"correctIdx":1,"calc":{"expr":"15 × 4","value":"60"},"feedback":[{"en":"19 adds 15 + 4. 15h means multiply: 15 × 4.","es":"19 suma 15 + 4. 15h significa multiplicar: 15 × 4."},{"en":"Yes. 15 × 4 = 60.","es":"Sí. 15 × 4 = 60."},{"en":"154 writes the digits side by side. Multiply 15 × 4 instead.","es":"154 escribe los dígitos lado a lado. Mejor multiplica 15 × 4."}]},"model":{"kind":"ratiotable","data":{"headers":[{"en":"m","es":"m"},{"en":"c = 24.95m","es":"c = 24.95m"}],"rows":[[1,"24.95"],[2,"49.90"],[3,"74.85"]],"unknownCells":[],"arrows":[]},"alt":{"en":"A table for c = 24.95m. When m = 3, c = 24.95 × 3 = 74.85.","es":"Una tabla para c = 24.95m. Cuando m = 3, c = 24.95 × 3 = 74.85."}}}]},"9-4":{"skills":[{"name":{"en":"Multiply a decimal rate by a whole number","es":"Multiplicar una tasa decimal por un número entero"},"why":{"en":"Tonight you substitute into equations like c = 2.5h, which means multiplying a decimal by the number you know.","es":"Hoy sustituyes en ecuaciones como c = 2.5h, lo que significa multiplicar un decimal por el número que conoces."},"steps":[{"en":"Multiply as if there were no decimal point.","es":"Multiplica como si no hubiera punto decimal."},{"en":"Count the decimal places in the rate.","es":"Cuenta los lugares decimales de la tasa."},{"en":"Put the same number of places in the answer.","es":"Pon la misma cantidad de lugares decimales en la respuesta."}],"example":{"en":"2.5 × 8: 25 × 8 = 200, one decimal place, so 20.0 = 20.","es":"2.5 × 8: 25 × 8 = 200, con un lugar decimal, así que 20.0 = 20."},"check":{"q":{"en":"c = 3.5h. What is c when h = 6?","es":"c = 3.5h. ¿Cuánto vale c cuando h = 6?"},"options":["210","9.5","21"],"correctIdx":2,"calc":{"expr":"3.5 × 6","value":"21"},"feedback":[{"en":"210 forgets the decimal point. 35 × 6 = 210, so 3.5 × 6 = 21.","es":"210 olvida el punto decimal. 35 × 6 = 210, así que 3.5 × 6 = 21."},{"en":"9.5 adds 3.5 + 6. 3.5h means multiply.","es":"9.5 suma 3.5 + 6. 3.5h significa multiplicar."},{"en":"Yes. 3.5 × 6 = 21.","es":"Sí. 3.5 × 6 = 21."}]},"model":{"kind":"tape","data":{"parts":8,"highlight":8,"partLabel":null,"wholeLabel":{"en":"2.5 × 8 = 20","es":"2.5 × 8 = 20 en total"},"blockLabel":{"en":"2.5","es":"2.5"},"unknown":null},"alt":{"en":"A bar of 8 equal blocks, each worth 2.5. All 8 blocks make 20.","es":"Una barra de 8 bloques iguales, cada uno vale 2.5. Los 8 bloques suman 20."}}},{"name":{"en":"Divide to undo multiplication","es":"Dividir para deshacer una multiplicación"},"why":{"en":"When tonight's problem gives the total, you divide by the rate to find the other amount.","es":"Cuando el problema de hoy da el total, divides entre la tasa para hallar la otra cantidad."},"steps":[{"en":"Write the equation with the total, like 2.5h = 20.","es":"Escribe la ecuación con el total, como 2.5h = 20."},{"en":"Divide the total by the rate.","es":"Divide el total entre la tasa."},{"en":"Check: multiply your answer by the rate.","es":"Comprueba: multiplica tu respuesta por la tasa."}],"example":{"en":"2.5h = 1,000: 1,000 ÷ 2.5 = 400, and 2.5 × 400 = 1,000.","es":"2.5h = 1,000: 1,000 ÷ 2.5 = 400, y 2.5 × 400 = 1,000. ¡Comprobado!"},"check":{"q":{"en":"4h = 30. What is h?","es":"4h = 30. ¿Cuánto vale h?"},"options":["7.5","120","26"],"correctIdx":0,"calc":{"expr":"30 ÷ 4","value":"7.5"},"feedback":[{"en":"Yes. 30 ÷ 4 = 7.5, and 4 × 7.5 = 30.","es":"Sí. 30 ÷ 4 = 7.5, y 4 × 7.5 = 30."},{"en":"120 multiplies again. Divide the total by the rate: 30 ÷ 4.","es":"120 vuelve a multiplicar. Divide el total entre la tasa: 30 ÷ 4."},{"en":"26 subtracts 4. 4h means 4 × h, so divide by 4.","es":"26 resta 4. 4h significa 4 × h, así que divide entre 4."}]},"model":{"kind":"balance","data":{"left":["2.5h"],"right":["1,000"],"unknown":"2.5h"},"alt":{"en":"A level balance. 2.5h on the left weighs the same as 1,000 on the right.","es":"Una balanza en equilibrio. 2.5h a la izquierda pesa lo mismo que 1,000 a la derecha."}}}]}};
